/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161128-8","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"建設委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)第１０１号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"はじめに、(1)第１０１号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"すごく丁寧な説明だったと思うのですけれども、私はあまりちょっとよくわからなかったので、そこをお聞きしたいと思います。現行手数料と廃棄物処理原価との乖離を解消することを目的としてということですけれども、これは乖離するのはなぜなのか。それで、その乖離を解消していくのがなぜ必要なのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"ただ、東京２３区につきましては、東京都時代からの流れで、合わせ産廃と申しまして、専ら自治体がやるべき家庭系のごみに合わせて、主に中小規模の事業者については、委託をすると、比較的料金体系が、少量なために高くなるという現状にも配慮して、無理のない範囲。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういったものの、中小、また商店街、商店の実態というのは、ごみに関してですけれども、どのように把握されているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"なお先ほど、原則は一般処理業者・許可業者への委託が原則だというふうにご説明をしましたけれども、今回定めたこの４０円は、これを定めると、業者との協定で、それを超える料金を、量にかかわらず、一般処理業者・許可業者は設定できません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"事業コストも下げる努力というふうに今おっしゃったのですけれども、事業コストというのはどういうふうにしていくと下がっていくものなのでしょうか。そして、事業コストも下げていく努力をしていくというふうに答弁があったので、その事業コストというものを下げる努力というのは、どのような努力を、どこをどのようにしていくことなのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"合わせて、廃棄物を減らすのは、結果的にリサイクルの推進によって減ってくるので、今回の手数料とは、ちょっと分野が違うわけですけれども、資源のリサイクルを進めていく等の努力をしてまいりましたし、今後もしてまいりたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"その差額はどうするのですかというのが３点目。４点目は、動物死体処理のところでは、野良猫とか、まあ野良犬はいないと思いますけれども、事故に遭ったりした場合には、多分、区民の方が見つけて保健所等々に連絡をした場合にお金をどうするのですか。２５kg以上、猫で２５kg以上というのはないと思うのですけれども、そういう、２５kg以上になった場合はどういう算定になるのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"さて、３点目の、１０月実施でというお話でしたけれども、９月にお買い求めいただいた券、これは経過措置として、１０月１ヶ月間は、安い料金のもとであっても、併用して使えるようにしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"券なのですけれども、１ヶ月間の猶予期間ということなのですが、これは多分、色を変えるなり何なり、違うものとわかるようになるのですよね、ということ。わからないと、買いだめしてということがあるので、わかるようになっているのですよね、という確認です。契約するところが、いや、３５円でできますよと言ったら、３５円のほうが安く済むではないですか。そういうやりとりはあるのですか。","respondent":"小林品川区清掃事務所長","answer":"ただ、かわいそうだから云々という、どこかに挟まってしまってとか、そういうものもあるので、それには動物愛護センター等の連絡先をご紹介して、ご連絡、対応を区民の方にお願いしていることになります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"先ほどの質疑にもあったのですけれども、改めて、この乖離というところについてお伺いしたいのですけれども。要するに、ごみの量とこの原価というのが、比例関係みたいになるのか。そういうものとは違う、何かこう、複雑なものなのかという、そこのところをお伺いしたいのですけれども。なぜ原価が、この４年ごとの中で上がっていくのか。そこのところをお伺いします。","respondent":"小林品川区清掃事務所長","answer":"したがって、それを見込んで収集車両を減らし、それに応じた収集人員も減らしていくということで、若干タイムラグはありますけれども、ごみの量が、極端なことを言うと、１台分に相当するものが減れば、１台減らせるのですけれども、なまじ減少幅が少ないと。","voiceIndex":16,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"そういうところで言うと、今、原価との乖離というのは、ある程度予測ができるという、乖離していくような仕組みになっているというか、できるのですかね。もしくは、事業系はちょっと変わっているのかもしれないのですけれども。要するに、４年後もまた乖離ということは、今の段階では見通せないというか、乖離しないということでつくられているのかというところが、お聞きしたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、基本的には、非常に簡単に言うと、先ほども言っていましたけれども、工場設備の整備に負担がかかったということだったのですけれども、これが、当初の予測よりも大きく経費として膨らんだ結果というようなことが、一番の今回の改定の要因と、４年間においてですね。そういう捉え方として収めておけばよろしいのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"全体の費用構成としては、おっしゃるとおりです。ただ、今回の３円５０銭について言いますと、工場の経費は比較的落ち着いておりますので、その他の人件費、それから車両等の物件費、主に収集関係の費用が乖離の要因となっているというふうに理解しております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"人件費と、物品は円安とかいろいろなこともあって、物価が上がっているというところもあるのでわかるのですけれども。人件費もそういうことで、社会の情勢において、当初よりも上向いているというところで判断して、ということで理解すればよろしいですか。","respondent":"小林品川区清掃事務所長","answer":"収集関係でも最近負担になっているのは、工場だけではなくて、収集筐体の、例えば清掃事務所の大崎の建物、こういったものが、区役所全体の施設がそうですけれども、改修時期に来て、いわゆる施設改修等の費用がかさんでいる等も。","voiceIndex":23,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それともう１点、動物死体処理なのですけれども、２５kg未満、本当に２５kgというと大体、大型犬も当然含まれると思うのですけれども、今まで、２５kg以上もあった動物というのは、実績というか、平成２７年度、平成２６年度でもいいのですけれども、そういったケースがあったかどうかをお知らせください。","respondent":"小林品川区清掃事務所長","answer":"しかしながら、この手を緩めますと、町の中、排出場所ではない所に出てきてしまいますので、引き続き対応してまいりたいと考えています。それから、動物で２５kgを超えるものというのは、私、４年目になりますけれども、その中では、お問い合わせがあったのは１件。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど、手数料と区長会という話があって、東日本大震災のときに変えなかったと伺いました。これは品川だけでしたか、全区がそのとき上げなかったのでしたか。ちょっと自分の記憶が曖昧なのですが、前にこの手数料、品川だけ下がっていたときがあったのは、これではなかったでしょうか。そこが自分の中でわかっていなかったので。","respondent":"小林品川区清掃事務所長","answer":"したがって、前回の平成２５年の改定、そして今回の改定で、その平成２０年当時上げなかった分の差額を２円ずつ足し増しをして、解消をしていきたいと思います。今回の改定がお認めいただけますと、２３区統一の水準に品川区も追いつくという状況にあります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。そこがちょっと、自分の中では解決したのですけれども、ここで２３区統一になると。もう１件、動物死体処理のところで、先ほど収集と保管の費用のお話があったのですけれども、収集は別料金でとっているということですか。そこをもう少し教えてください。","respondent":"小林品川区清掃事務所長","answer":"清掃事業の職員の本務は、やはり可燃・不燃のごみの収集ですが、上がってきた後の時間で、動物の死体の収集に当たっているので、動物の死体対応のための職員というのはいない。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。ちょっと意見を言わせていただきたいのですが、やはり中小の事業者であったり、商店街、個人商店などを見ると、今どのような状況にあるかというところはもうご存じかと思うのですが、こういったごみ処理の手数料のところでも上げる状況ではないのではないかというふうに思っています。やはりそういうところに支援こそ、今、必要なときだと思いますので、この議案には反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"}]},{"id":"topic-02","title":"第１０２号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第１０２号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"区内の区営の駐輪場で、２,５００円の所というのはあるのでしょうか、ということと、あと地下式にするということ、なっていくわけですけれども、なぜここの大森駅水神口の自転車駐輪場は地下式にしたのか、そこをちょっと伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"そのたびに放置警備を強化したり、もしくは駐輪場を増設したりして対応してきたところでありますけれども、やはりどうしてもそれだけでは足りないということで、今回、一気に３基の地下駐輪場を増設する。","voiceIndex":43,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"同じだけの料金で使えるように、そしてさらに便利になるというのは、とても喜ばれることだと思いますので、そういった料金の変更というのは、この機械式になる、便利になる、それを考慮したと書いてありますけれども、そこだけでの２,５００円なのかというのを、ちょっともう１回伺いたいと思います。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"やはり２,５００円というのは、現行条例の最高額で２,５００円になっております。そこをまだ、そこまで使った駐輪場は、区内の中では１つもありません。こちらの地下式の駐輪場を設置し料金を考えるに当たって、従来と同じという形になりますと、他の駐輪場の料金設定自体に、差が、逆に下げてとか、そういうふうな話も当然出てくる可能性もありますし、これにかかわる維持管理費。","voiceIndex":47,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"ちなみに、この障害者の区民以外、区民以外の障害者の方は何人ぐらいいらっしゃるのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"障害者の方ですけれども、これは区民以外の方、９名いらっしゃいます。全体、区内合わせますと７３名の方がいらっしゃるということで、そのうちの９名が区外の方ということになっております。","voiceIndex":50,"id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この大森駅水神口自転車等駐車場は、何名入れるのでしたか。","respondent":"桑波田交通安全担当課長","answer":"地下式駐輪場につきましては、７６５台の車両を収納することができます。","voiceIndex":52,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"ということは、区民以外の障害者の方が９名ということで、その程度の利用者数でしたら、区民の方の利用は、今、特に問題にならないという点でよろしいでしょうか。","respondent":"桑波田交通安全担当課長","answer":"区内全体で９名ですので、対応は十分可能です。","voiceIndex":54,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それで、この受付の方法なのですけれども、施行規則改正のアのほう、優先順位は、手続き的にどういうふうにやっていくのでしょうか。その作業を１点、教えてください。それから、先ほど規則の改正と、料金のところで、逆にこれ気になったのは、天王洲アイル駅第２区営自転車等駐車場というのは３,５００円になっていますよね。そこが、先ほどの説明と、ちょっとどうなっているのかという確認です。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"そのために、免許証だとか、パスポート、こういったものをご提示いただきまして、区民であるということを確認して、それ以外の方とまた別にして、受付を実施していくように、来年以降、実施してまいります。ほかの所は、同じ施設の中で、自転車とバイクが一緒になっているような形なので、括弧書きで、例えば大井競馬場前駅であると、括弧書きで３,３００円と、そういうふうな形で分けているのですけれども、この天王洲アイルだけは。","voiceIndex":56,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"別のところに出ているのかどうか。それから優先承認関係を１カ月前からやっていく中で、では、区民の方が申込みをしたときに、すぐ４月１日から使えますよという形になるのか。その中で、１ヵ月前に申し込んで、例えば２週間前に決定しましたとか、そういう作業がどうなるのかなという、手続きがちょっとわからなかったのですが。","respondent":"桑波田交通安全担当課長","answer":"順次、区民以外の方は、契約が切れましたらその時点でそれ以降は１カ月というふうに、もしくは区民を優先して入っていくので、契約はできなくなるというような状況になっております。","voiceIndex":59,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"例えば新規で申込み、区民の方がしますよね。そうすると、その時点では空きがないということだけれども。今、満杯だったら空きがないということになりますよね。それが、５月なら入れますよという意味にとればいいのか。その辺、申し込むとき、今もう空きがないのは申込み順でしたけれども、その辺の作業の問題が、今の流れがよくわからなかったのですが。","respondent":"桑波田交通安全担当課長","answer":"もし、まだ残余期間がありまして使えないようであれば、その残余期間が切れますので、その時点から、申込みを受け付けておきまして、それ以降、５月から、６月から、そういった感じでお伝えして、区民の方はそのときから入っていただくようになる流れです。","voiceIndex":61,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"既存のところはそうだと思います。今度、水神口も始まりますよね。水神口は、申込みが始まる時期がいつなのかと。それから料金が、最初のとき、このカード等は無料なのですよね、そこもちょっと意味がよくつかめなかったので。水神口の申込み手続きと、その順番づけみたいなのはどういう形になるのか。それで、いつ頃から、いつの時点でここが入れますよと決まるのかなと、日にちがわかればと思うのですが。","respondent":"桑波田交通安全担当課長","answer":"水神口につきましては、まず７６５台できますので、今の見込みですと、まだ余裕がありますので、区外の方も含めて全員が、申込みされた方は入れるようになっております。","voiceIndex":63,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"区民優先利用のところについてなのですが、まず今、品川区内で区民以外が利用している数というのがどれぐらいなのかと、もしわかっているのであれば教えていただきたい。こういう考え方というのは、品川区だけではなくて、基本的に２３区、あるいは都市部のそういう駐輪問題がいろいろ出ている自治体では、こういうことが１つの共通的な考え方となっているのか、そこの確認をお願いします。","respondent":"桑波田交通安全担当課長","answer":"優先につきましては、他区のほうでも実施しているところがありまして、大田区でありましても、これは全体ではないのですが、大森の駅、蒲田の駅、田園調布、こういったところで、区民の優先等を取り入れている状況にあります。","voiceIndex":65,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうですか、もっといろいろあるのかなと、他自治体でもいろいろこういう動きが出てきているのかなというところもあったのですけれども。現状を今お伺いしたのですが、今後の１つの方向性としてどういう方向なのか。徒歩等別の交通機関等を使うという方向性に行っていただければ一番いいのだろうと思うのですが、この辺の見通しをどのように見ていらっしゃるか、お伺いします。","respondent":"桑波田交通安全担当課長","answer":"千代田区でありますとか、新宿区、文京区、荒川区であったりとか、ほかの自治体でも数カ所実施しているところがあります。優先に関しましては、今、区民の方でもキャンセル待ちして、当日利用を使っているという方がいらっしゃいます。","voiceIndex":67,"id":"exchange-024"},{"speaker":"西本委員","kind":"確認","question":"すみません、先ほど説明があったのですが、確認をしたいのですけれども、大森駅水神口のほうですけれども、利用者識別カード５００円、札が７００円という１,２００円は、２,５００円の中に入っているということでいいのですね、というところを。","respondent":"桑波田交通安全担当課長","answer":"カードの再交付のお金は示しておりますけれども、２,５００円以外で取ることはございません。入っております。","voiceIndex":69,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"１００円でもいいのではないかと、極端な話ですよ。それで、水神口のほうの使い方なのですけれども、申込みをして利用していました、でも１年間休みます、それでまた再度するという場合はどういう流れになるのですか。なので、その辺、多くなった場合の、使っていくといろいろなパターンが出てくると思うのですが、それはどういう整理の方法を使えるようになっているのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"カードのほうにつきまして、上限としているのは、これは規則のほうでそれよりも低い価格としていますが、今後、単価の変動等を考慮しまして、今、同じ単価で実施しているところですけれども、今、低い設定をしておきますと。","voiceIndex":71,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"値段の上下するということでの設定とは何ですか。これは、条例の中で、５００円と７００円としているわけだから、上限額という表現というのはどうなのかなと思うのですね。ですから、そういうニーズというか、変動というか、心情的なところも含めて、それをどう考えられているのかなというふうに思うのですね。そういったときの対処について、何か決めていますかということをお聞きしたいのですけれども。","respondent":"桑波田交通安全担当課長","answer":"大森につきましては、やはり大田区の方も近接なので使っている状況もありますし、また今後、人口が増加するということも予測しておりますので、それで、あえて、どうしても地上だけではできない、入り切れないということも合わせまして３基、７６５台ということで、多めに。","voiceIndex":73,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"上限額のほうは、あまりこだわっていないかもしれないのですけれども、わかりました。大分、変更があるはずです。そうすると、あそこがすかすかになっている状況だったら、それこそ、そこを整備し直しをみたいなことも言ってくる可能性があるので、そこは、区としてはきちんと考えていただきたいなと思うのですが、それについてのご意見をお伺いしていいですか。","respondent":"桑波田交通安全担当課長","answer":"需要のほうも、当初、地下式をつくる前は、地上のほうの公園の所の整備ということで考えたのですけれども、やはりこういう従前の充足を考えますと、どうしてもそれでは対処できないということで、地下のほうへ３台増設という、そういうことを見込んで、地上ではできない。","voiceIndex":75,"id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、規則の第９条の２で、(1)１カ月間、(2)３カ月間、(3)６カ月間と書いてあるのですけれども、これは、利用者の方が何カ月にするのかということを決める、という理解でよろしいのでしょうかということ。よろしくお願いします。","respondent":"桑波田交通安全担当課長","answer":"利用期間については、申込みをされた方が自分で、１カ月間、３カ月間、自分で決めて申込みしていただきます。そして、当日のほうは誰でも使える場所でありますので、いつでも空いていれば使えることになっていますので、特に申込み等は要りません。","voiceIndex":77,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"現在、区民以外の方も定期利用されている方はいらっしゃるのですよね。先ほど言っていた当日利用に徐々に行っていただくという、１つの誘導方法としては、継続手続のところで、区民以外の方の継続をお断りして、当日利用に行っていただくということでよろしいのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"区外の方は、原則、４月１日以降は１カ月というふうになりますので、空きがあれば入れますけれども、継続的には１カ月やって、その間に区民の方から申込みが来れば、翌月からは区民の方が使っていただくというふうにしていくところです。","voiceIndex":79,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。ここの地下式駐輪場が便利になって、それが２,３００円だとほかも下げてという議論になってくるとおっしゃられていたのですけれども、私はほかも下げていっていただきたいぐらいです。やはり区営の駐輪場ですし、区民は一生懸命税金を払っているわけですので、より低廉に使えるということは当然だと思いますので、この定期利用料金を２,５００円にするという、ここに反対したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"この２の公募の例外とした理由のところで、いろいろ今、借上型区民住宅が、建設型についても、いろいろな指定管理期間中ですかね、この５年間という、年度の曲がり角に来ているというところで、そういう意味で、これまでの経験を持った事業者が継続してやることが望ましいということだと思うのですけれども。","respondent":"今井住宅課長","answer":"やはり区内事業者ですので、これは、ほかの事業者でもそうではあるのですけれども、さらに区内の近隣の事業者とも連携しておりますので、何か、修繕であったりとかそういうことに対して、的確に速やかに対応できるというのが。","voiceIndex":96,"id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"今、再委託先の業務、または委託先についてご説明いただいたのですけれども、その辺というのは、こういうところに資料として示していただいたほうがいいのではないかと。指定管理の議案として上げていただくに当たっては、やはり見える化ということの１つとして、あったほうがいいのではないかなというふうにも思いますけれども、その点についてどのようにお考えか教えてください。","respondent":"今井住宅課長","answer":"再委託先につきましては、再委託という言葉自体が適切かというところも、ちょっと今、委員のご質問をお受けして考えているところなのですけれども、一般的に工事を再委託するとか、ただ単に管理を別の業者に渡してしまうのではなくて、同じ不動産業者の団体の中で。","voiceIndex":98,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"これは、どうなのですかね。もう１つの、選定委員会の構成は、1)から5)、ありますけれども、これはこういうものなのですかね。区の職員ですよね、これはそういうものでいいのですか。規定がどうなっているかなと思っているのですけれども。選定理由も方々とりつつ、選定するときの理由の中に、いろいろな項目を入れればいい話なのかなと思うのですけれども、それはいかがなのでしょうか。","respondent":"今井住宅課長","answer":"それはやはり、先ほどから繰り返して述べておりますように、借上型区民住宅の返還というのが、やはり年度途中に入ってくる中で、３月、４月で切ることは、なかなか途中では難しいだろうというふうに判断したのが１つになります。","voiceIndex":100,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"そうですね、この借上型のことを考えると、それが適切なのだろうというふうに思います。ただ、やはり示していかなければいけない部分があると思うのですよね。なので、次回のときに、どういう選定理由を立て、そしてこれからどうしていくのかということを考えると、今までのような状況でいいのでしょうかということも当然議論に入ってくると思うので。それに対してご意見あればお願いします。","respondent":"今井住宅課長","answer":"委員ご指摘のとおり、やはりこれはただし書き上の特別な理由の場合ですので、先ほど申しましたとおり、やはり指定管理者につきましては、公募というものが前提、複数の事業者から提案を受けるということが基本になっておりますので、もう一度、今後。","voiceIndex":102,"id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"この指定管理者制度活用に係る基本方針なのですけれども、３の(1)で、割合的には過去にどの程度、要は公募プロポーザル方式で選定した業者数と、このただし書きの特別な理由がある場合の特定の事業者の選定。わかる範囲で。","respondent":"今井住宅課長","answer":"そして区民住宅ですけれども、もう１つ、ファミーユの西五反田、西館と東館の指定管理業務というのが、ほかの区民住宅です。こちらにつきましては公募型でございまして、来年度が公募型のプロポーザルを迎える時期です。","voiceIndex":104,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民の皆さんの利用するこの区営住宅と区民住宅というところで、ちょっと改めて、この役割を教えていただきたいと思います。","respondent":"今井住宅課長","answer":"区営住宅と区民住宅のそれぞれの役割ですけれども、ご案内のとおり、区営住宅につきましては、所得の低いなど、住宅に困窮する低所得者向けの公営住宅というのが、私どもが考える区営住宅です。","voiceIndex":106,"id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、私たち、以前からずっとこうした区営住宅、区民住宅というのは、区が直営で進めるべきだということを求め続けてきているわけです。やはり安心に安全に住み続けられるというところでは、株式会社での運営というところが、やはりなじまないなと感じるのですね。株式会社ということなので、ここでも従業員数、また、その方々の平均賃金など、そういうところはわかるのでしょうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"給料等につきましては、こちらのほうは、私どもでは把握しているところではございません。それぞれの適切な法に基づきまして、給料を支給しているというふうに認識しております。","voiceIndex":108,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで今回、公募によらないということで、先ほどから、ほかの委員からもありますけれども、そういった面で、ちょっとなあなあになってくるのではないかというふうな見方がされるのも致し方がないところだと思うのですが、改めて、今後の区民住宅、区営住宅の管理をしていくというところは、どのように考えられているのか伺いたいと思います。","respondent":"今井住宅課長","answer":"先ほど申しましたとおり、指定管理者の選定につきましては、ただし書きで、特別な理由がある場合というところで、今、宅建管理センターを公募の例外ということで対応しておりますけれども、今後、借上型区民住宅の満了を迎えた後に、また改めて。","voiceIndex":110,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。１つ意見を、この間ずっと区の直営でということを求め続けています。区民の安心な住まいをというところでは、区の直営で進めていっていただきたい、株式会社はなじまないというふうに思いますので、反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-040"}]},{"id":"topic-03","title":"建設委員会を再開いたします。 引き続き、議案審査、(5)第１１２号議案 指定管理者の指定","agenda":"建設委員会を再開いたします。 引き続き、議案審査、(5)第１１２号議案 指定管理者の指定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この自転車の駐輪場の指定管理者制度、初めてでしょうか。それで、今回６団体に配布をしてということで、結局１団体しか残らなかったという現実があります。これはなぜでしょうかという分析ですね。それであと、今までもしていただいているということで、ちょっと５のところで気になるのが何点かあって、自社努力というところ、自社努力はありがたいのですけれども、どういう意味なのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"自社努力の関係なのですけれども、こういったものは、大型な設備の改善であれば区のほうでも費用を出して整備等は進めてまいりますけれども、簡易な、ラックを外すだとか、間隔を広げるだとか、ラック自体を取り除いてそのまま平置きにして置いたりすることによって。","voiceIndex":125,"id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"ただ、自社努力でいいのですかね。提案は提案で受けて、それに対する必要な経費、区がいいと思ったら、やはり経費は経費できちんと払うべきだと私は思うのです。それから接遇研修、やっていると言うのですけれども、評価はどうなのでしょうか。いや、私はいいのです、そういう改善提案はあるのだけれども、でも現在できているというふうな、自分で評価をしているとするとどうなのかなと。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"我々、この１社しかないときに、そういった第三者というのはなかなか難しいですけれども、基本的なモニタリングだけではなくて、そういった評価も重ねながら、しっかりと改善をしていくと、そういった指定管理者制度を進めていきたいと。必要な経費については、今後、指定管理者のほうと、いろいろな改善等があれば連携をとりながらやっていきますので、今後また連携を図りながら、出すものは出すということでやっていきたいと考えております。","voiceIndex":127,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、接遇の問題です。先ほどちょっと答弁の中で、要はこのダイナミクスのほうからシルバー人材センターに頼んだりとかしているのですか。その人材センターから派遣されてきている、その派遣された人に対しても、接遇の対応をどういう仕組みでやられているのですか。","respondent":"桑波田交通安全担当課長","answer":"各駐輪場の方には、場長と管理人とがいます。管理人等をシルバーの方に、ＮＣＤのほうからお願いして派遣していただいているところです。こういった方々に、研修会等の実施と、あと場長等を通じてのいろいろな教養等をやるような仕組みになっております。","voiceIndex":130,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ということは、そういう委託をしても、委託されたＡさん、仮にですね、Ａさんに対しても、きちんと研修はされていますという認識でよろしいのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"委託された方について、基本的にはやっているです。","voiceIndex":132,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"機械的に対応しても満足度は得られなくて、例えば困っているときに「どうかされましたか」とか、「お金を入れたのに出られないのですよ」と言いに来たときに「ああ、わかりました」と返事をきちんとするとか。もう少し現場を見ていただいて、きちんと配慮されているのかどうかという評価をしっかりしていただきたいと思うのです。それに対してのご意見を伺います。","respondent":"桑波田交通安全担当課長","answer":"いろいろなクレーム等も、現場のほうではあるというのも聞いておりますし、また逆に、本当に出し入れするのに困っている時に、職員の方が、管理人の方が、お手伝いをサポートしてくれたりだとか、雨で濡れているサドルを拭いてくれたりだとか。","voiceIndex":134,"id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。夜間とかそういったときに、平成２７年度でも構わないので、件数ですとか、それでどういったことがあったのか、わかる範囲で教えていただきたい。もう１点が、提携警備会社。差し支えなければ現在の警備会社をお知らせください。あれば、件数を教えてください。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"件数的なものはこちらのほうではとっておりません。その防止のために、それ以外にも、防犯カメラの設置だとかといったことを各駐輪場のほうにやっているです。警備会社はセコムを呼ぶような形です。","voiceIndex":136,"id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"サポートセンター、２４時間やっているということで、今までそういった、あってはならないですけれども、そういった被害とかはないというようなご答弁でしたけれども、大小ある中でそういったサポートセンターを設置している以上、２４時間、年間通してやっているということで、区に対して、何らかの報告というのは当然あると思うのですけれども、もう少しその辺を詳しく教えていただきたいと思います。","respondent":"桑波田交通安全担当課長","answer":"特にサポートセンターのほうは、お金を入れたけれどもちょっと電磁ロックが解除できないだとか、そういったものの対応ということで、そちらのほうも一括集中制御しておりますので、機器の故障で開かないのであれば自動ロック解除ができるようになっておりますので。","voiceIndex":139,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"この、最後に１団体しか残らないというところまでの改善というのが必要なのではないかなというふうに思うのですね。シルバー人材の方との連携というか、そういう方にも管理をしてもらっているということですけれども、この２３ある施設の中で、全ての駐輪場のところでシルバー人材の方を使われているのか、どれぐらいの施設、駐輪場が、このシルバー人材の方を使われているのか、伺います。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"前段のほうです。１社ということで、我々もその点については危惧をしているところでありますけれども、まずどうして１社だったのかというのは、先ほど担当課長から申し上げました。６社が応募したということ、これは事実です。人員の関係ですけれども、場長を入れまして９１名の方が従事されております。そのうち、シルバーの方は３３名の方が、管理人として勤務しています。","voiceIndex":141,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"最終的にやはり残ってしまうのが１社だということなのですけれども、１社に絞ろうとして１社にしているのですか、それとも何社かあっていいかなというふうな思いもあるのでしょうか、それを伺いたいと思います。それとあと、シルバー人材が、先ほど接遇の話もありまして、いろいろ教育体制、もっと講じていくということなのですけれども、こういう方たちの時給というのですかね。","respondent":"松代防災まちづくり部長、桑波田交通安全担当課長","answer":"いろいろと検討していただいて、それを提案していただいて、利用者の満足度につながる、また利用者が喜んでいただけるような提案をしてもらう業者を、ぜひ複数の業者から選びたい。こういう姿勢で臨んでいるところです。シルバーの時給の関係ですけれども、こちらは区のほうでお願いしているわけではありませんので、指定管理者のほうでやっておりますので、それは企業とそちらのほうの契約となっておりますので、区のほうでは把握してはおりません。","voiceIndex":144,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区の姿勢として、よりよいサービスを区民にというのはあると思うのですけれども、そういった企業がより集まってこられるようなＰＲというのですか、こちらの打ち出しも大事ではないかなというふうに思います。どれぐらいの賃金で働いているかわからないのに、もっとやれ、もっと頑張れというのは、やはり働く意欲につながらないと思いますので、その辺の把握を求めますけれども、いかがでしょうか。","respondent":"桑波田交通安全担当課長、安井土木管理課長","answer":"公募につきましては、それぞれ段階を経まして実施しておりますので、とりあえず１社だけにこだわるということでは、全くございません。そういう形で担保されていると考えております。","voiceIndex":147,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。意見を述べさせていただきたいのですが、やはり１社独占というのは、そもそも指定管理者制度にちょっと問題があると思っているのですけれども、それにしてもやはり１社独占というのは、この指定管理にも合っていないのではないかなというふうに思います。こういった理由を含めて、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-051"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"この委員会でこうした損害賠償についての専決処分の報告を受けるのですけれども、いろいろなご事情があるとは思うのですが、この再発防止策は具体的にどのような形で行っているのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"それぞれの案件につきましては、発生して、基本的には１週間以内に、担当の技能長を含めて何が悪かったのだろうという分析をして、その概要を、各運転手に、ケースとして学んでいただくということで、教訓を生かすために周知を図っているところです。","voiceIndex":162,"id":"exchange-052"}]},{"id":"topic-05","title":"区営住宅入居者募集","agenda":"区営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今回は、単身者向けの予定はないということですが、２人以上、３人以上ということですけれども、複数、要は世帯向けになってくると、募集の状況というのは単身者と比べてどうなのかというのを伺いたいのと、あと、募集対象なのですけれども、ちょっと私、勉強不足なのですが、夫婦別姓の場合とかはこうした対象にはならない、戸籍名が違う場合のパートナーというのは。","respondent":"今井住宅課長","answer":"初めに、応募倍率ですけれども、今回、７月に募集した状況を見ましても、あまり、単身だから、２人以上だからということで、差はついていないです。","voiceIndex":168,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"税とかの状況が証明できればということだったのですけれども、住民票上は、未届の妻、未届の夫というふうになって、保育料とか保険料とかは合算して、世帯の収入として算定されるみたいなのですけれども、そういう場合は大丈夫ということですかね。","respondent":"今井住宅課長","answer":"内縁関係、大変恐縮なのですけれども、こちらのほうでは、遠縁のほうでも内縁関係というふうな表現をさせていただいているのですが、住民票の続柄の記載が、未届の夫または妻となっており、戸籍上の配偶者がいないことということの確認をしていますので。","voiceIndex":170,"id":"exchange-054"}]},{"id":"topic-06","title":"１の議案審査に戻りまして、残っておりました(6)第９４号議案 平成２８年度品川区一般会計補正予算（建設委員会所管分）","agenda":"１の議案審査に戻りまして、残っておりました(6)第９４号議案 平成２８年度品川区一般会計補正予算（建設委員会所管分）","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"例えばスケートボードの利用者が、今までどのぐらいあってとか、品川区の公園の中でこれを整備する、何かメリットというのがあるのかなと。なので、ちょっとその理由が、もうちょっと欲しいなというところがあるのですけれども、それが１つ。それから２つ目が、しながわ区民公園中央ゾーン改修、これは早期に着手というこの意味が、どういう意味で早期着手に至っているのかということを教えてください。","respondent":"溝口公園課長","answer":"例えばサーフィンなども追加になっておりますが、それを公園でできるかというと、なかなかそういったものの整備ができない中、今回、追加種目５種目ある中で、何ができるかというのを考えた中で、今回、スケートボードということで選定をさせていただいたものです。","voiceIndex":180,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"それはそれで、きっかけはきっかけで、チャンスがあってということなのでしょうが、ただ、いろいろな競技がある中で、やはり本来は、区民のニーズとして、競技人口がどのぐらいで、要望があって、足りないので、それで整備しましたというような、そういうきちんと分析した上で設置すべきものではないのかなという。それと、しながわ区民公園は、ここに、中央公園に保育園ができるということですか。","respondent":"溝口公園課長","answer":"いずれにいたしましても、これまで長年にわたって、スケートボード場、何とか整備してほしいという声がずっと寄せられてくる中、今までなかなかできなかったものが、やっとこの機に整備ができるようになりましたので、しっかりと利用者が、また。","voiceIndex":182,"id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"スケートボードは、以前から自民党からもずいぶん要望をさせていただいて、前は第二駐車場につくっていく案などもあったこともあるかと思うのですが、音の問題で進まなかった。あの広さの中で、台みたいな、４カ所ぐらい置いていましたけれども、あの中で、大体どのぐらいの人数が一度に使えるのかなというのがよくわからないので、想定はどのぐらいなのでしょうか。","respondent":"溝口公園課長","answer":"ただ、いろいろ置く物、いろいろな物、様々な物も置いて、楽しめるようにしていきたいというふうには考えておりますが、利用状況を見ながら、また安全状況等も、そういったものも確認しながら、いろいろ配置等も考慮しながら、開園しておしまいではなくて、その後もしっかり。","voiceIndex":184,"id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。結局、表が路上駐車になってきて、となるようなことがないようにその辺、場所がないからこれ以上駐車場をつくってと言うのも難しいのだけれども、その辺の管理も十分注意していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"周辺の音の問題も出ましたけれども、利用時間は何時から何時までになっているのでしょうか。","respondent":"溝口公園課長","answer":"今、実際、スケートボード場の運用につきましては、スポーツ推進課と最終的な協議をしていますが、今この八潮北公園にあります野球場・テニスコートと同じように、朝９時から夜９時までを今想定しているものです。","voiceIndex":187,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"あまり近隣にないと、逆に集中してきてしまうのではないかなという感じもするのですが、近隣区のスケートボード場というものの整備状況というのは把握しているのかどうかということ。こういった、トリック台と言うのですか、技をするような台があったりするわけですけれども、こういった物は、やっている方と一緒に、こういうものを設置してほしいとか、そういうふうにして進めていくのでしょうか。","respondent":"溝口公園課長","answer":"これにつきましては、今回、日本スケートボード協会というところがありますので、そことまず、今現在、設計段階でよく話を聞きながら、どういった形でつくっていけばいいのかというのを検討していますし、先ほども話したように、それでおしまいではありませんので、その後。","voiceIndex":189,"id":"exchange-060"},{"speaker":"塚本委員","kind":"確認","question":"今までの質疑にもちょっと出てきているのですけれども、今、設計段階ということなので、ある程度、形が見えてきた段階で、完成予想図みたいな形のものが、この委員会で示されるのだろうなというふうに思っているのですけれども、それの確認が１つ。一応、この債務負担行為の理由というところでは、工期が２カ年にわたり、分割契約が困難なためということで、こういうことは結構あるのでしょうか。","respondent":"溝口公園課長","answer":"ただ、今回のように、年度をまたぐことによって、少しでも早く、４月から工事をするのではなく、少しでも早く契約をし、少しでも早く開園していく、そういった考えのもとに、今回は、債務負担という、きちんとそういった手続きにのっとった形で、２年にまたいで工事を進める。","voiceIndex":191,"id":"exchange-061"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"家賃助成をという質問があったのですけれども、そこでは、要は子育て世帯の入居支援ということを求めたのですけれども、そこで、ＵＲが親と子の近居で減額している、あと都営と公社住宅は倍率優遇制度を実施しているということだったのですけれども、これらのちょっと詳しい説明と、八潮でこれがどのように、どれぐらい行われているのかという具体的な内容、実施状況を聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":60803,"voices":210}},{"id":"h28-20161128-9","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を93件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"すみません、制度の確認なのですけれども、養子縁組を前提としない養育家庭の仕組みもあったと思うのですが、これについては医療費というのはどういう扱いになるのでしょうか。将来的に養子縁組を前提としない養育家庭についての医療費の扱いはどうなっていますか。","respondent":"廣田子ども家庭支援課長","answer":"里親に種類があるかと思いますが、養子縁組をしない里親として子どもをお預かりする養育里親でありますとか、専門里親でありますとか、それぞれ里親の制度が省令、規則で定められているのですが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"児童福祉法の改正に伴ってという説明があるのですけれども、国のところなのですが、この改正の趣旨とか、時代的な背景とか、国でどんな議論がされていたのか、わかる範囲で教えていただきたいのが１点です。文言のところで、「６条の４第１項」を「６条の４」に改めるという、この中身自体の説明をしてください。","respondent":"廣田子ども家庭支援課長","answer":"法改正の里親の部分の変更の趣旨につきましては、大きく言うと、里親支援の一貫した業務について、都道府県の業務として法の中で位置づけたということです。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"第１００号議案 品川区立保育所条例の一部を改正する条例","agenda":"第１００号議案 品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"この件はこれまでもご報告をいただいているので、ここについてはいろいろ伺っておりますけれども、これ、暫定５年間で決まりということで、現段階でもそこは固まっている話で、５年で閉園ということなのでしたか。現状でのお考えを確認させてください。","respondent":"佐藤保育施設調整担当課長","answer":"保育園の開設期間なのですが、品川駅南地域の再開発の状況で、１年ずつどうしていくかというのを見極めていきたいと考えております。現時点では、５年間は保育園として利用するということは決まっております。","voiceIndex":30,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"その場合の、これからまだ１年延びますというような判断というのは、いつごろにされるものなのでしょうか。やはり在園されている方とか、例えば、３歳児ぐらいで入りたいという方なんかも、来年なのか、あと１年延びるのであれば入りたいけれどもどうしようとか、個別の悩みが出てくると思うのですが、直前というか、１年前ではちょっと遅いのです。いつごろの判断にしていくのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"再開発の状況にもよると思うのですけれども、関連部署と連携を密にして、できるだけ早い段階で情報を受けまして、速やかに混乱がないように、事前に申請者の方にお伝えしたいと思います。","voiceIndex":32,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本条例は設置の条例ではあるのですけれども、株式会社サクセスアカデミーへの委託が決まっているということでの設置なので、委託の契約のことで、今のとも関連して何点かお伺いしたいのですけれども、１年ずつの判断ということなのですが、不都合があったらまた契約の解除があり得るのかどうか。１年ごとの契約で更新していくということなので、その点が１点。３点、大まかに。よろしくお願いします。","respondent":"佐藤保育施設調整担当課長","answer":"保育士の処遇と業者の経営状況の確認なのですが、これに関しても、年度末に収支報告書等を出してもらっていまして、その確認は当然いたしますし、月に一度は保育園長会等を実施しますし、随時連携をとるような打ち合わせも行いますので。","voiceIndex":35,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先日の芦屋の報告なんかを聞いても、品川区でできない範囲があるといったことも言われていたので、どこまで品川区でこの問題、ひろまち保育園を繰り返さないという立場において、どこまで調査をしていくのかというところをもう少し明確に、本来だったら項目を挙げて、こういうところをチェックしていきますというのが出されるべきであると思っているのですが、そこはいかがでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"これも当然やっていくのですが、常に中身のほうを確認して、もし何かあれば早目に連携をとって、いい状態で保育を実施していきたいと考えております。","voiceIndex":37,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、東京都に問い合わせをして、それは区のほうで決めますからというお答えが幾つかあったので、やはりここの点検を区が責任を持ってやっていくという、姿勢的にはこれとこれを今まで以上にチェックしますという項目をやはり設けていただかないと、この間のご説明では、時間を長く使って選びましたとか、そういうことではとても区民の方の納得は得られないと思うのですが、私、この点。","respondent":"佐藤保育施設調整担当課長","answer":"関連会社のほうの収支状況等も適宜、今現在も確認はしておるのですが、そういった中身も今まで以上によりきめ細かく適切に状況を確認していきたいと考えております。","voiceIndex":39,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"夢工房の事例だと、全国に結構何カ所もあったのですけれども、普通の定期監査ではわからなかったので、内部告発によってさらに詳しく突っ込んで、第三者委員会で調べて、いっぱいいろいろなことがわかってきたのです。一度問題が起きたところを繰り返さないといった意味で、説得力のある、特に経営状況の調査、報告をぜひしていただきたいと思いますが、最後ですが、お伺いします。","respondent":"佐藤保育施設調整担当課長","answer":"ひがしやつやま保育園のほうの経費の執行状況なのですが、公設民営ということで委託になりますので、委託する金額の項目ごとに、その辺にどういったものを歳出しているかという報告書を出すように委託書に盛り込む予定です。","voiceIndex":41,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後になりますけれども、区のほうはそうやって納得をすると思うのですが、私たちはその中身をきちんと知らされなくて、大丈夫です、きちんとしていますという文言だけでは納得できないのです。そういった面でどこまで議会に報告できるのかというところは、ぜひ今後の課題として検討していただきたいと思います。よろしくお願いします。これはお願いをいたしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません、確認なのですけれども、５年で契約をしていて、１年１年協定を結んで更新していくという理解でよろしいでしょうか。そこら辺を確認したい。","respondent":"佐藤保育施設調整担当課長","answer":"契約は１年１年の委託契約になるのですけれども、基本協定というのを結んでいまして、５年間施設の運営をお願いしますということで、細かい項目等が書いてあるのですけれども、そういう形で行っております。","voiceIndex":44,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、５年というところが基本協定の中に入っているということの理解でよろしいでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"５年というのは基本協定の中に入っております。","voiceIndex":46,"id":"exchange-011"},{"speaker":"あべ委員","kind":"確認","question":"先ほどのやりとりで一応確認したいのですけれども、こちらの事業者、人件費の比率というのはどの程度になっているのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"既存の運営をしている園に関しては、５０％から６０％の間と聞いております。ただ、こちらの保育園に関しては、公設民営ですので、施設整備費がかからない関係もありますので、７割以上は人件費比率に割きたいというふうに業者から確認をとっています。","voiceIndex":48,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"人件費比率というのが一つの大きな法人の性格をあらわす目安だと考えています。その法人の性格を知るためには、人件費比率というのをもう少しオープンにしていくことによって、保護者の方にとってもそれが一つの目安になるだろうと考えていますし、私どもにとっても、もちろん行政にとっても大きな目安になると考えていますので、ぜひその方向もお考えいただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"公設民営保育園に係る人件費比率のご紹介、お知らせについては検討させていただきたいと思います。","voiceIndex":50,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとお時間いただいていいですか。この点が１点目です。この２点です。一方、認可保育園増設は、保護者や保育士、また、地域の強い要求であり、共産党としてもこの間、認可保育園の増設は、求めてきた問題ですので、本条例が通れば、新たに６０名の定員拡大となります。そして、１年ごとの契約ということなので、ぜひ委託は１年でやめて直営にすることを強く求めて、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"私どもとしても、やはり公設民営の形をとるということで、ひろまち保育園のことがあった直後でありますので、ぜひ契約書の段階から、十分に練っていただいて、モデルケースとなるぐらいのレベルにしていただかないと、やはり今後の公設民営の議論にかかわってくると思いますので、そこについてはぜひ努力をしていただいた上で、運営そのものについては、本議案については賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成です。ちょっとだけなのですけれども、いろいろなチェックについて、権限も東京の関係があるかもしれませんけれども、ぜひ一番身近なところなので、区のほうで十分にリーダーシップを発揮してチェックをして、先ほどほかの委員からもありましたけれども、夢工房の形にならないようにぜひチェックを充実させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"人事委員会勧告に基づくものですので、この所定の内容については異論はないのですが、何点かお伺いしたいと思います。固有教員については、これは、要は都費の教員とそろえなければいけない性質のものなのかどうかということ、それから、給与以外の、例えば、研修などに係るところというのはどういうことになっているのか教えてください。","respondent":"熊谷指導課長","answer":"これは、同じ職場で働く同じ職層の給与については、均衡を図るという意味合いです。２点目の研修につきましては、都の教職員と同様の研修の機会があります。","voiceIndex":63,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろ品川区としてオリジナルな研修をしたいと思っても、育てたころにはまたどこかに行ってしまうというのが、やはり都費の先生のつらいところで、行ってしまわない先生であれば、私はどんどん新しいことを学んでいただいて、なかなか出ていってしまう人にはもったいないような、例えば、北欧の教育を見てもらうとか、上海の教育を見てもらうとか、そういったこともどんどん私。","respondent":"熊谷指導課長","answer":"現在もオークランドへの派遣等も行ったりもしておりますけれども、また改めて今後の研修については改善を図ってまいりたいと思います。","voiceIndex":65,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第１１４号議案なのですが、前に伺ったのですが、議案書を１ページめくって、１級から２級、３級、４級とありますが、どういう立場の方に該当する級なのかを教えていただきたいのと、あと、中程のページに「再任用職員以外の職員」という欄があるので、これは一体何なのか説明をしてください。","respondent":"熊谷指導課長","answer":"１級が教諭、それから主任教諭、それから副園長級、それから４級で園長級ということで、上がっていっているところであります。それから、再任用以外といいますのは、これはそのとおり、一般の教職員のことを再任用以外という言い方をしております。","voiceIndex":67,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最高の方というのは、給料が一番上がってどのぐらいまで行っているのか教えていただきたいのと、第１１５号議案のほうなのですけれども、品川区で同じ物価とかお家賃の中で暮らしているのに、どうして学校の先生のところだけがお給料が上がらないのかということで、特別区の人勧と東京都の人勧がそれぞれの違いで書いてあるのですが、この辺、どうしてこうやって変わってくるのか。","respondent":"熊谷指導課長","answer":"初任といいますか、若い方になりますけれども、今回の影響額といいますか、実際に影響で増えている額なのですけれども、非常に若い方に関しては３万３,６９１円、これが今回の改定に伴って上がってくる額です。初任給につきましては……。","voiceIndex":69,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"特別区の人勧と東京都の人勧の内容で、大もとのところが何で違ってくるのか、大もとのところをお伺いします。","respondent":"熊谷指導課長","answer":"先ほどもお伝えしたとおり、まず、大もとのところにおきましては、特別区と東京都の勧告で公民較差に差が出るのは、民間給与の実態を調査するときに、特別区では特別区管内の事業所ですけれども、東京都では多摩地区の事業所もその調査対象となっておりますので。","voiceIndex":73,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"制度の話になってしまうのかもしれませんが、今回、学校教育職員のほうが０.０２％差で、極めて小さいということで、アップはされないということですけれども、これは今度また差が出たときに、この分というのは積み上がっていくのか、それともまた一からということになるのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"それにつきましては、そのときの格差ということになりますので、積み上がるということではございません。","voiceIndex":75,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"歳出額のほうがもしわかれば、全部でどれぐらいになるのか。賃金が上がるわけですので、全体として対象となる先生方が何人いて、幾ら上がって、全体の歳出は幾らになるのかということを教えて下さい。","respondent":"熊谷指導課長","answer":"総額につきましては、幼稚園教育職員が３５名おりまして、１７１万８,３３８円です。固有教員につきましては、正規１９名で、今、育休を取っております関係で、代替の者１名で２０名。７１万９,１１４円です。合わせまして、２４３万７,４５２円ということになっております。","voiceIndex":77,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"賛成します。一言だけ。教職員組合で、勧告がやはり不当な内容であるという評価が出ていたのですけれども、東京都と都労連の協議にて妥結をしたと伺ったので、労使協議を尊重して、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-024"}]},{"id":"topic-03","title":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第９４号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"鈴木（博）委員","kind":"意見","question":"１枚目のほうなのですけれども、よくわからないのですが、新の都制度で、平成２４年４月１日以降の新規開設園が対象だということで、開設後５年間と書いてあるということは、平成２４年４月に開設した場合は、平成２９年までしか補助が受けられないのか。","respondent":"竹田保育課長","answer":"委員ご指摘のとおり、平成２４年から５年間ですので、残存期間のみとなります。","voiceIndex":98,"id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"開設補助金、品川区で独自にスタートしていて、都が後から制度をつくってくれたということで、品川区として積極的な取り組みだったと思います。それで、区制度から都の制度に、これは併用ではなくて、移行だと思ってよいのですか。それで間違いないですね。制度が変わることによって、この仕組みでいくと逆に負担が増える事業者もあるのでしょうか。どういう感じなのか、把握されていますでしょうか。","respondent":"竹田保育課長","answer":"こちらの制度は、どちらかを適用するという制度です。それで、今年度に限って試算した結果、全ての事業者が都の新制度を利用したほうがメリットがあるということで、今回、助成するのは、全て都の新制度を利用したものとなる予定です。","voiceIndex":100,"id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"すみません、やはりよくわからなかった。区の単独１,５００万円というのは、上限つきの旧の区の制度１０分の１０というので１,５００万円、新制度８分の７というのは、これは都からの４分の３というか、８分の６も足した８分の７で、区からは８,１００万円出すけれども、そのうちの８分の６の分は都からお金が来ていると考えていいのですか。","respondent":"竹田保育課長","answer":"委員おっしゃるとおり、区の単独補助の場合には区が全額補助しておりまして、こちらが約１,５００万円、それから、都の新制度の約８,１００万円は、これは都の補助を含む８分の７の金額です。","voiceIndex":104,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"ということは、新制度のほうは都から受け取った分を差し引いた１,０００万円ちょっとが、純粋なる区の負担分と考えていいのですか。","respondent":"竹田保育課長","answer":"おっしゃるとおりです。すみません、繰り返しの部分もありますが、東京都の新制度を利用した場合、区が支出する８分の７のほうが８,１００万円で、従来の制度の単独補助が１,５００万円なので、その差額が……。","voiceIndex":106,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったときに、月額８万２,０００円の中で、明らかにそれを上回ってしまうと思うのですけれども、経費の中では家賃と共益費、管理費等だけだと思うのですけれども、こういったときにどのようになっていくのかというか、本当に積み上がってしまうということになるのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"宿舎借り上げのほうですが、東京都から明確に示されていませんが、今回、礼金を月額で補助したというのは、来年の４月以降に採用される方を意識したものだと考えております。","voiceIndex":109,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"下がっていかないのではないかと思っているのですけれども、その中で、５年いかない、４年半ぐらいになっていくというところで、どうしてそうなったのかというところを聞いたので、もう少し詳しくわかれば、都から聞いていれば教えていただきたいと思います。","respondent":"竹田保育課長","answer":"開設後家賃補助金の関係ですが、こちらは東京都の緊急対策として、当面、こちらの期間ということで打ち出されたものですので、今後の動向を見て決めていくものだと考えております。","voiceIndex":111,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"宿舎借り上げのほうなのですが、更新料が発生するときも８万２,０００円で上限だということなので、これは都の制度だと思いますので、やはり更新料のところが大きくなってくると思うので、礼金を別枠にするという例もありますので、更新料のほうも別枠にしていただけないかというところで、都に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、新入社員というのですか、その方がご自分でというところは、都の仕組みだからなのかもしれませんけれども、そういう仕組みになっているのですか。だから、例えば７年目の方が今どこかに住んでいて、自分で借りている場合は、この支援を受けられないという解釈でよろしいでしょうか。","respondent":"竹田保育課長","answer":"宿舎借り上げ事業ですが、こちらはあくまでも事業者がオーナーと契約したものということになっておりますので、既に個人で住んでいらっしゃって契約されている部分については、契約変更によって事業者が借り上げたものというふうに契約を変更すれば。","voiceIndex":114,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、それはそれでそうしていただいて支援を受けられるのはいいのですけれども、使い勝手として、やはり従事される方々は、事業者との関係なのですけれども、自分で探してきて、ここを事業者に契約してくださいと言うのはなかなかやりにくいというか、そういうのがあって、事業者が用意したところに、ここに住みなさいみたいなパターンが多いと思うので。","respondent":"竹田保育課長","answer":"現在のスキームですと、保育士が何人利用していても、事業者に一括して該当金額を振り込むという形になります。ご提案の仕組みですと、それぞれの保育士に振り込むような形になろうかと思いますので、その辺はなかなか対象人数が増えてくると難しいかと考えております。","voiceIndex":116,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"あちこちに契約をしていても可能なのかどうか、その点も教えていただきたいのと、あと、私立保育園の家賃補助のところなのですけれども、具体的に区の制度のときの補助のところで、月額、低いところでどのくらい、高いところでどのくらいの補助が受けられていたのか、額を教えていただきたいのと、わかれば、新制度の、下の状況になったときに、その金額がどう動くのかも教えてください。","respondent":"竹田保育課長","answer":"事業所の家賃の最高、最低額の件ですが、認可園に限って申し上げますと、従来の区の制度ですと、最高が月額で６７万円ほど、最低は自社ビルですと０円等があります。","voiceIndex":118,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"すみません、新制度、下の制度になったときにこれがどういうふうになるのか、わかったらよろしくお願いします。","respondent":"竹田保育課長","answer":"すみません、正確な金額は今ご用意していませんので、お答えできかねます。","voiceIndex":120,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"わかった時点で教えていだたきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-036"},{"speaker":"あべ委員","kind":"確認","question":"すみません、宿舎借り上げのほうでお伺いしたいと思います。それから、仕組みは私はあまり詳しく覚えていなくて、これは単身だけではなくて、家族でも利用できる制度だったかということを確認したいのと、それから、これ、形としては事業者が契約をして、そこに保育士が入るという形だと思うのですけれども、事業者が給与天引きとかいう形で保育士から家賃を徴収することは可能な制度なのですか。","respondent":"竹田保育課長","answer":"事業者が家賃を徴収することについても、特段定めがございませんので、可能かと思います。それから、現在の人数ですが、認可保育園ですと利用した人数が３９人、地域型が２２人、認証が１８人、昨年度ですが、以上のようになっております。","voiceIndex":123,"id":"exchange-037"},{"speaker":"あべ委員","kind":"確認","question":"これから新規ないし更新でないと、この制度は使えないということになってくるのでしょうかという、これは確認です。結構園の中でも家賃負担がものすごく給料の差をはるかに超えた負担の差になる、そういう現実になっているのでしょうか。これも確認です。要は、事業者の負担分を超えて、事業者が保育士から家賃を家賃分として取ることも制度上可能ということなのでしょうか。","respondent":"竹田保育課長","answer":"ただ、契約を新たに交わすわけですから、場合によっては、オーナーの考え方によっては、契約者がかわるのだから新たな礼金、敷金等を求める方もいらっしゃるかもしれませんので、そういった場合はなかなか難しいのかと考えております。","voiceIndex":125,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、賃貸に住んでいる方も、積極的にこの制度に乗りかえられるように契約の変更などを働きかけたり、あるいは要望を受けているかどうかということと、それから、保育士の実質負担分というのを設定しているかしていないのか、しているとすると、どの程度であるのかということも、ぜひこれ、公費を入れてやっている事業ですので、把握していただければと思いますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"どのように運用しているかにつきましては、今後、調査していきたいと思います。実質的な負担についても、同様です。よりよい、使いやすい制度になるように、制度の趣旨が活かせるように今後検討してまいりたいと考えております。","voiceIndex":127,"id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"今の質問にかぶるかもしれませんが、現状、これ、制度がスタートしている部分もあると思うのですけれども、各園の中で職員の皆さんにどう説明がされていて、例えば、要望の声というのはすぐに出てくるかと思うのです。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"具体的に、各事業者がどのように説明しているかというのは、それぞれなので細かくは把握していないところなのですが、こちらの制度をしっかり理解していただいて、適切に運用していただくように努めてまいりたいと思います。特に処遇改善につきましては、税金を充てていろいろな対応をしているのですけれども、最近は保育士を新規で採用して、若い職員を研修して確保するというところに重点が行っていたのですが、５年目から６年目になって。","voiceIndex":129,"id":"exchange-040"},{"speaker":"沢田副委員長","kind":"確認","question":"先ほど高橋しんじ委員の質問の中で、処遇、借り上げの支援のところで、各保育士たちに補助金を出すのではなく、事業者のほうに出すということだったと思うのですけれども、確認したいのですけれども、開設後の家賃補助金とか、借り上げ支援事業の補助金とか、あと、処遇改善の人件費の補助というのは、基本的には事業者に出すときに、どういった形でお金を出されているのか。","respondent":"竹田保育課長","answer":"公定価格については、毎月月額で計算して支給しております。区の単独補助の分につきましては、物によっては年２回で支給しているものもあります。","voiceIndex":132,"id":"exchange-041"},{"speaker":"沢田副委員長","kind":"質問","question":"家賃補助と借り上げ支援のほうは毎月。それで、あと、処遇改善の、こちらで関係ない、ちょっと外れてしまいますけれども、区が単独でやられているのは、給与の上乗せ分というのは、事業者にはどういう形で出されているのでしょうか。それが半年ということですか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"処遇改善を含めた公定価格の分につきましては毎月ですし、区の単独補助の分については、物によって毎月のものもございまして、年２回のものもあります。宿舎借り上げについては、年２回という形でやっております。宿舎借り上げでいうと、各園ごとにきちんと契約書がありまして、実際の原契約書と、払っている家賃、誰がどこに住んでいるか、何号室かという、分厚いのが来まして、私もチェックさせてもらっていますけれども、年に２回。","voiceIndex":134,"id":"exchange-042"},{"speaker":"沢田副委員長","kind":"質問","question":"物によっては半月だったりとか１カ月ごとに、今の話だと家賃関係は半年ということで、大丈夫なのだと思うのですけれども、事業者としてはやはり毎月申請した分が来るほうが運営の形としてしやすいのではないかと思ったのですけれども、そういうわけでもないと言われて、物によって何カ月ごとに１回だったり、毎月ごとというのは違っていても問題ないということでしょうか。","respondent":"齋藤子ども未来部長","answer":"保育士が何人いて、標準の給与がこれで、あるいは加算で、例えば、特別支援の加算を何人とかというと、その部分の加算の部分は毎月行きますので、基本的に運営費についてはお渡しできておりますので、運営については支障はないかと考えています。","voiceIndex":137,"id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"賛成ですが、宿舎借り上げについては、いろいろと運用にある程度目を光らせたほうがいい面もあるのではないかと。いろいろな事業者がいらっしゃいますので、これはいろいろできそうな仕組みである以上、ぜひ調べながらの運用にしていただきたいということを踏まえて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成ですけれども、今、あべ委員がおっしゃったのですけれども、そういった課題の点をクリアしながら、使い勝手といいますか、保育士たちがぜひこの支援を使えるように、スキームが区のものではないとすると、先ほどもお話ししたのですけれども、保育士たちの声を聞いていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２番の方というのは、返還済額というのは０で、３８万２０００円が訴訟の金額で、確定違約金という１万７,１００円というのが、これが払うことになっている金額だと考えてよろしいのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"２番の方につきましては、貸し付け終了後、お支払いを全くいただいておりませんで、違約金につきましては、提訴になる前に分納の合意ができた場合については、今まで違約金についてはいただいていないのですけれども、提訴になった場合については判決として出てしまうので。","voiceIndex":150,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、２番の方というのは、実際、この人が支払う金額というのは、１万７,１００円だということになるのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"訴額になっている元本の残り３８万２,０００円と確定違約金の１万７,１００円で、合わせて３９万９,１００円が分納する金額となります。","voiceIndex":152,"id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"違約金の額なのですけれども、これ、それぞれの和解・決定条項の(1)ウにある遅延損害金（違約金）というのは、今後の分割での返還に対して遅れたらということで理解してよろしいでしょうか。１０％とか１０.９５％とか、人によって若干の違いがあるのですが、これは何か根拠があっての利率というのか、割合なのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"２カ月以上滞らないようにというふうに条文に書かれておりますので、２カ月以上滞納せずに払っていただければ、それ以後についてはいただかないということができます。できればそういう形でやっていきたいということでかかわっていきたいと思います。","voiceIndex":154,"id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"今の時代に年１０％という数字を見ると、非常に衝撃的な大きさなのですけれども、この３件だけを見ても、分割の内容からいって、経済力の違いがいろいろあるのだろうと思います。これは事情によってはご相談可能ということなのでしょうか。それとも、和解内容がそうなってしまったら、何が起きてもこのとおりで、１０％というのが適用されていくということなのでしょうか。どのようにお考えですか。","respondent":"廣田子ども家庭支援課長","answer":"こういう状況で払える状況にあったりであるとか、１番の方のように、親御さんが親の責任で払いますというような申し入れをいただいて、少しずつということにはなっておりますけれども、またその途中で収入が激減したりという場合には、滞納するのではなくて。","voiceIndex":156,"id":"exchange-049"},{"speaker":"新妻委員","kind":"質問","question":"今回、このご報告をいただきましたが、本来であれば、このような訴訟までにならないことが理想だと思うのですけれども、今回ご報告をいただいて、これで訴訟までするのは一段落していると見ていいのか、まだこういう払っていない人がいて、訴訟までしなければいけないというような方がいらっしゃるのか、教えていただけますか。","respondent":"廣田子ども家庭支援課長","answer":"件数といたしましては、今、何とも言えないのですけれども、平成２８年度に関しましては、現時点でまだ提訴するべき人というところは出てきていないのですけれども、一旦分納合意をしても、その後お支払いにならなくて、連絡もとれないという状態の場合には。","voiceIndex":158,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれ違うと思うのですけれども、私なんかはなるべく早く、下のお二人は訴訟外の和解ということもあるし、なるべく早い時点で困っている様子を相談できたり、いろいろな手立てがあることを知らせていけば、もっと裁判にならなくて済むのではないか。いろいろご努力されているのはわかるのですけれども、早期に区が対応できるような方法はないのかといつも思っているのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"訴外の和解になった２件については、提訴した結果、判決のときにも来てくれなくてというところですが、やっと見つけて分納合意をしたというところなので、この５件に関してはみんな提訴になってしまったけれども、提訴した結果、連絡がとれたというところなので。","voiceIndex":160,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"ご努力はこの間、何回も伺っているのでわかっていますけれども、ぜひ話し合いに来てほしいというところの思いが伝わっていくようにしてほしいと思います。","respondent":"廣田子ども家庭支援課長","answer":"訪問につきましては、品川区内と近隣につきましては、シルバー人材センターに委託をしておりまして、かつてＮＨＫの受信料を徴収した経験がある方にお願いしていて、自分では振込みがなかなか難しい方を集金してくれたりとかというところで、訪問していただいているところです。","voiceIndex":162,"id":"exchange-052"}]},{"id":"topic-04","title":"平成２８年度請願第１４号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２８年度請願第１４号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"保護者補助金についてお伺いしたいと思います。これまで段階的に品川区のほうでも補助金の所得制限については水準を上げていって、対象者を増やすということをされてこられました。これ、段階的に引き上げてきているのですが、対象者がいつも８０％程度のような気がするのです。対象割合というのは広がっているのでしょうか。","respondent":"竹田保育課長","answer":"対象割合は、緩和するごとに拡大しています。平成２３年度は６０％でございました対象が、平成２４年度には６５％、平成２６年度には７０％、今回、平成２８年度予算では８０％まで拡大してきたところです。","voiceIndex":170,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"品川区としては、対象者の割合というのは特段念頭に入っていなくて、額で決めているというふうに考えていらっしゃいますか。補助金の所得制限の意味といいますか、どういうところからこの数字をはじき出していらっしゃるのかを教えてください。根拠といいますか、考え方を教えていただければと思います。","respondent":"竹田保育課長","answer":"ちなみに、６５％に拡大したときが、推定年収が９００万円までの方が対象、７０％に拡大したときが約１,０００万円、現在の８０％は年収約１,３００万円までの方が対象となっているというところで、推定年収をにらみながら決めているところです。","voiceIndex":172,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"すみません、勉強不足なのですが、「所得制限の導入以来」というところが、請願項目の中で書いてあるのですけれども、それから格差が拡大しているというところで、導入されたのはいつで、なぜ導入されたのか伺いたいと思います。数が少なくなっている理由を教えてください。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"所得制限が導入されたのが平成８年度と聞いております。当時の状況がはっきりわからないので、直接的な理由というのは、後日お知らせしたいと思います。お調べするまでもなく、幼稚園に入っていらっしゃる方の保護者の方の負担の軽減を図るということが制度の導入の目的でございまして、ただし。","voiceIndex":174,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目は、この中にも切々と書かれていますけれども、教育費の負担が大変だという、就学前もそうですし、義務教育でもお金がかかりますし、高校、大学と教育費の負担というのは、やはり生活の中で重く位置をしていると思うのですが、教育費の負担増に対しての認識をお伺いしたいのが１点です。所得制限の考えなのですが、８割に拡大をしたと。","respondent":"竹田保育課長","answer":"現状の８０％というところですが、今後につきましては、状況を見ながら決めていきたいと考えております。それから、所得制限をなくしていくかどうかという点も、今後考えていきたいと思います。","voiceIndex":177,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが１点です。ここのところ、ずっと努力されて８割まで来ているので、あと残りの２割、ぜひ進めていただきたいと思うのと、子どもの教育に、私は子ども一人ひとりの成長、これからの主権者である大事な子どもに対して、等しく本当に公平に教育することが大事であると思っているので、所得制限を設けることはいけない、なくしてほしいと思っているのですが、その点、いかがでしょうか。","respondent":"竹田保育課長","answer":"適切かというご質問ですが、現状の保護者補助金は、国の補助、東京都の補助、さらに区の補助とを加味して、３者を合わせたもので補助しているものですので、３者の合計額は適切に補助されていると考えております。","voiceIndex":179,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、社会状況の厳しさの中から、どれだけ本当に頑張って、自治体が支援できるのかということにおいて、ぜひ困難を抱えている方への手立てをとっていただきたいと思いますが、いかがでしょうか。私は、すごく困難だ、人の確保なんかもすごく大変と聞いているので、その辺が進んでいるのか、ぜひここの支援は大事であると思っているのですが、いかがでしょうか。３点です。","respondent":"齋藤子ども未来部長、竹田保育課長","answer":"どこまで負担をすればいいかというのは、もちろん全部あげればいいのではないかという議論もあるのかもしれませんけれども、過大な支援になってしまうと、今度逆に行政依存という部分も出てきますので。区立幼稚園の保育料の件ですが、区立幼稚園の保育料は、消費税等が上がっても、物価が上がっても長年据え置いてきたものでございましたので、今回、国の新制度の考え方に基づきまして、応能負担の考え方を入れたものですので。","voiceIndex":181,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"医療費の助成もかなり自治体の負担になっています。これ自体、本当に全国的に国の段階に引き上げていかなくてはいけないものではありますけれども、でも、今では当たり前になっている。私はぜひこういう姿勢に立ったら、子どもにかかわる費用、所得制限は要らないと強く思っておりますので、意見として述べておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":184,"id":"exchange-059"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字を確認させていただきたいのですけれども、私立幼稚園の年間の所要額、多分、園によってばらつきはあるとは思うのですが、どのくらいの金額になっているのか。それと、所要額、補助を受け取れば、家庭で年間でどのくらいの負担になるのかということ、それから公立の場合だと、年間幾らぐらいになるのかというのを教えてください。預かり保育を使っている方々の割合が分かれば、教えて下さい。","respondent":"竹田保育課長","answer":"所要額の件ですが、平均ですけれども、選抜料が７,１１１円、それから、入園料、４歳児で入った場合が１３万２,７７８円、それから、保育料が、４歳児の場合ですと、年間３３万円、施設費が１万１,０００円、教材費が１万５,５６１円、冷暖房空調費が４,８６１円。","voiceIndex":185,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"すみません、区立幼稚園の年間支払い額は、この委員会で分からないものなのですか。多分、そんなに難しい質問ではないと思いますので、教えてください。私立のほうで、入園のほかに……。","respondent":"齋藤子ども未来部長","answer":"ご質問の趣旨は、おっしゃっていたのは年間の私立幼稚園の公費負担という意味ですか。","voiceIndex":187,"id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"今の私立の部分については、それで保護者の支払い分と、補助を受けたらどのくらいになるかということですので、欲を言えば、最も多い額だけではなくて、最も少ない額の補助、要は、補助を受けられる中では一番補助が少ない方でどの辺の水準になっているのかということも教えていただけると、なおよかったです。わかったら教えてください。これはそんなに複雑なものではないと思いますので。","respondent":"竹田保育課長","answer":"公立の負担額ですが、所得に応じて保育料が異なっておりまして、平成２８年度においては、最も低い世帯の方が０、それから、最も高い方が１万２,０００円になっておりますので、１万２,０００円掛ける１２カ月で、１４万４,０００円となっております。","voiceIndex":189,"id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"そうですね。その辺のことも考えると、これだけカバーしているからそれで十分ということでは、生活実感としては感じないのです。そういったことも含めて、あるいは、公私での子どもの費用の格差ということも考えると、やはり今の制度ではしんどいという方も多いのではないかと感じているのですが、区としての認識はいかがでしょうか。これでもう十分と感じていらっしゃるのでしょうか。","respondent":"竹田保育課長","answer":"年々拡大してきて、現在、１,３００万円の年収の方、おおむね全体の８割までカバーしているところでございまして、今後につきましては、保育料の推移等をしっかり調査しながら決めていきたいと考えております。","voiceIndex":193,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて。適切な補助が行われているというご答弁をいただいたのですが、毎年この請願が出されているということをやはり重く受けとめていかなければいけないと思っています。所得制限はなくしていくべきであると考えていますので、賛成で採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":205,"id":"exchange-064"}]},{"id":"topic-05","title":"平成２８年請願第１７号 一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２８年請願第１７号 一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"品川地区で２.３１m2、大崎地区で０.５４m2、大井地区が２.８２m2、荏原地区が１.２８m2で、八潮地区はいろいろ公園等多く、５８.３m2となっておりますけれども、やはりほかの地区では、大崎地区などは特に０.５４m2だというところで、公園整備のほうも少ないというところがありますので、ぜひ公園を増やしていっていただきたいと思いますけれども。","respondent":"溝口公園課長、大澤待機児童対策担当課長","answer":"今後につきましても、公園整備につきましてはしっかり進めていきたいと考えているものです。園庭のない保育園についてのお尋ねですけれども、園庭が全くないという園は２５園あります。園庭はあるけれども、既定の面積が足りずに、公園等とあわせて確保しているという園が３３園です。","voiceIndex":217,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"公園整備のほうはしっかりやっていくということなのですけれども、先ほどありました荏原では増やしているというお話もありますが、それを含めても、今、やはり平成２８年度のものですけれども、１人当たり１.２８m2と。そういった中で、実際にこういった運動能力の発達というのも確保できているのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"新規開設園につきましては、庭のない場合はできるだけ遊戯室を広くとるように事業者のほうも努力してくださっておりまして、例えば、平成２９年開設の園も、当初の予定よりも定員を１０名減らして、その分遊戯室を広くとるなど、それぞれ工夫をしていただいているところです。","voiceIndex":220,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"室内では、体操とかダンスなどできるようにしているということですけれども、やはり外で元気いっぱい遊ぶということは、それとはまた１つ違うものがあると思うのですけれども、その違いについて、どういった認識なのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"外で遊ぶことと室内で遊ぶことの保育内容の違いという意味でいえば、もちろん広い場所があればそれに越したことはありませんけれども、では室内で何をやっても体力がつかないかというと、そういうことはございませんので。","voiceIndex":222,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"園の中でもやっているということですけれども、やはり外で元気よく走り回るということも、相当子どもの体の成長、発達に寄与することだと思いますので、ぜひ整備に向けて進めていっていただきたいと思いますけれども、改めて伺いたいと思います。","respondent":"溝口公園課長","answer":"引き続き公園につきましては、安全に安心して誰もがご利用いただけるような公園を目指して、整備に取り組んでいきたいと考えているものです。","voiceIndex":224,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"新規園を整備する中で、園庭を設けるのが難しいということで園庭のないところが増えていると思うのですけれども、公園として整備することはできると思いますので、ぜひ進めて、積極的に、子どもが遊べるような公園を増やしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-069"},{"speaker":"あべ委員","kind":"質問・要望","question":"それも園庭があるとかないとか、公園がある、公園が近いとかいう以前の問題として、子どもが朝行ってから夕方まで、しかもそれが１日２日ではなくて、春に入園してから秋までお散歩に出たことがない保育園があるという話も聞いて、そういう運営面での外遊びというのは、区はどこまで把握していらっしゃるのでしょうか。かなりいろいろな運用があると思いますので、伺いたいと思います。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"ただ、運動会等のイベント時には土曜日、近くの公園、小学校の校庭等をお借りしているのが現状です。夏休みは、近くのプール等もお借りするようなこともありますが、園庭については、今後、検討していきたいと考えています。お散歩につきましては、なかなかうちも計画書をもらっていて、実際どうなっているかは把握しがたいところもありますけれども、そういった点も含めて今後私立保育園の指導の際には計画どおり実施されているか。","voiceIndex":227,"id":"exchange-070"},{"speaker":"あべ委員","kind":"質問・要望","question":"少数派とは思いますけれども、多分、１園２園ではなさそうな感じですので、ぜひ留意していただきたいと思います。ただ、仕組みの面から、やはり民間の場合は難しいところがあるので、チェックをしていただきたいと思います。ですので、どうなのでしょうか。実際のところ、改築等を除いたところでの運営費の差というのは、公立と民間と同規模であると、大体何対何ぐらいの割合になっているのですか。","respondent":"佐藤保育施設調整担当課長","answer":"公営の保育園と民設民営の保育園の運営費なのですけれども、８月の文教委員会でもご説明させていただいたのですが、１００名定員規模で大体どちらも１億７,０００万円ずつということで、大体１対１、同じ金額です。","voiceIndex":230,"id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうですよね。そんなに運営費自体が変わるものではないというふうに理解しました。特に保護者に対する説明のあり方ですとか、日々の保育のあり方ですとか、そういったことがいろいろ今聞こえてきていて、職員の方もかなり大勢の方が短時間ずつ働くような中で、公立認可園の質というのも、私はある程度チェックといったらいいのですか、強めていかなければいけないのではないかと感じております。","respondent":"竹田保育課長","answer":"今後も、保育の質をしっかり今まで以上に向上できるように、そういった研修を充実させていきたいと考えております。","voiceIndex":232,"id":"exchange-072"},{"speaker":"あべ委員","kind":"意見","question":"何もやっていないわけではないと思うのですけれども、やはりいろいろ具体的なことが聞こえてきますので、これはまた個々にでもお伝えもしていきますが、公立認可園だからといって必ずしも常に質が担保されているわけではないのだというのはここのところ感じているところで、その辺は区としては大分公立認可園の体制が変わってくる中で、危機感といったら何ですけれども。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"特段、大きく変わったというところは、認識してございません。そうすると、それを５０代のベテランの保育士が教えるとなると、新採後の３年間の計画、それからＯＪＴ、あるいは職層別の研修もして、深く系統立てて研修をしているのですが、やはり短い期間の中で担任を持つだとか。","voiceIndex":234,"id":"exchange-073"},{"speaker":"あべ委員","kind":"質問・要望","question":"３つ目、多分、半分はおっしゃるとおりなのだと思います。やはり親の意識ですとか、措置から契約に変わって随分たちますけれども、利用者という意識でいるというのが大きくなっているというのは確かにあると思うのです。ただ、これは私の意見で恐縮なのですけれども、お気持ちは大変わかるし、逆に親の側でも求めるし、保育士の側でも求めるけれども、ぜひそこから入らないでいただきたいと。","respondent":"齋藤子ども未来部長","answer":"これがチームという形になるかどうかはあれですけれども、少しずつそういった意識も持っていただければと。ぜひとも取り組んでいきたいと考えています。","voiceIndex":237,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、日経新聞の日経ＤＵＡＬという雑誌が、あれは不定期なのですが、出ている中で、保育園の特集がされていたのですけれども、９割の保護者の皆さんが認可保育園を求めていますという数字が出ていたので、この辺も受けとめながら、品川の現状をどう考えていらっしゃるのか、ぜひ聞かせていただきたいと思います。これが２点目です。そこをお伺いしたいのと、保育課で前、アンケートをとっていますよね。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"２点目ですけれども、認可保育園をご希望される保護者の方が大半であるということは私どもも認識しておりますので、先ほども申し上げたとおり、認可保育園の開設を中心に待機児童対策は進めてまいりたいと思います。そういった中で、引き続き公園というものは少しずつでもしっかり行政需要も踏まえ、また、地域性も考慮しながら増やしていきたいと考えているところではありますが、なかなか今すぐに園児、今回お話があったように。","voiceIndex":239,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公園のところだけ先に質問します。子どもの成長、発達に本当に大きく響く問題だし、保育園の子が独占したら、本当に地域の子どもがまた遊べないといった問題も含んでいますので、ぜひご努力をしていただきたいというのと、ほか、国家戦略特区か何かで、去年かおととしに保育園の公園の利用の調査があったかと思うのですが、私は認証保育園の園長先生にお伺いしたのですけれども、わからないでしょうか。","respondent":"溝口公園課長","answer":"そういった取り組みをしていく中で、しっかり安全で快適な皆様のご利用が確保できるように、そういったものに努めていきたいと考えているところです。","voiceIndex":243,"id":"exchange-076"},{"speaker":"新妻委員","kind":"質問","question":"すみません、公園課長、公園の件で１点だけお伺いしたいのですが、今後のまちづくりの中で公園づくりを進めていくというご答弁ですが、今、具体的に検討されている公園ですとか、こういうところができる予定なのだというのが具体的にありましたらお答えいただけますでしょうか。","respondent":"溝口公園課長","answer":"今年度もそうなのですけれども、木造密集地域、荏原地域において、２園ほど防災広場を整備していく予定にしております。","voiceIndex":245,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"続きをお話ししていいですか。大丈夫ですか。１番のところ、最初の、「健やかに育つ権利」のところ、もちろん当然という認識で、そうなのです。スタンダードですよね。なので、予算が民営化で軽減できるというところの意見は全く真っ向から違うので、その辺をお聞きしたいのと、やはり国の予算があまりにも低過ぎる、これの対策をしていかなければいけないと思っていますが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長、佐藤保育施設調整担当課長","answer":"保護者の方のニーズが、認可保育園に一番多いということは認識していますので、認可保育園の開設を中心に今後も進めてまいります。ただ、施設に関しては無償貸与で貸すということは、それも選択肢の一つですけれども、事業者の負担もいただきながら、さまざまな面で適切な費用等を検討して進めていきたいと考えております。","voiceIndex":248,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ＯＥＣＤなどの先進国のデータ分析等からも明らかになっていますが、子育て、教育支援をしていくと健全な主権者が育っていくということと、保護者の皆さんはじめ、安心して働けて、経済的効果が抜群であるということとか、安定した雇用につながって雇用が拡大していくといった、そういうたくさんの効果が、経済的効果、何十倍とかいう話もありますけれども、保育所はお金がかかって大変、公立をつくると大変。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"新規開設の事業者に対して、質の高い保育をしていただけるように働きかけるのも区の役割だと認識しておりますので、継続して努力してまいります。区の財源を重点的に投入して、保育事業、待機児童対策に取り組んでいるということであります、ということはご認識いただきたいと思います。","voiceIndex":251,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後、１点だけなのですが、この間、待機児童が減ると課長がおっしゃっているので、この根拠をしっかりと今日はお伺いしたいと思っているのですが、来年は４００人くらい申し込みが増えるのではないかというご答弁をいただいているのですが、９月の申請が１,０８５人、１０月が１,２１４人で、１１月頭の集計でどれだけになっているのかというところと。","respondent":"大澤待機児童対策担当課長","answer":"ですので、当初、申し込み、４００人ぐらい増えるのではないかと見込んでいたところですが、そこまでは増えないのではないかというふうに、１１月の数を見て思っているところです。","voiceIndex":254,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私が計算したところによると、大体今年と同じくらい、保育園に入れない人が出てきます。待機児童とおっしゃっているのが１７８人だと思うので、そうではなくて、９７１人、保育園に入れなかったお子さんの数からすると、来年もそんなに大きく変わらない数のお子さんが入園できないのではないかと心配しております。そういった意味でぜひ願いをかなえていただきたいと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"「区の責任で認可保育園を整備し待機児童を解消してください」という項目については、我々は一貫して認可保育園も非常に重要である、ただし、認可外の保育園の整備も並行してやってほしいという希望と要望を出しておりまして、これに関しては若干意見が違うと思っているわけです。それは今日の課長の答弁でも、ほとんど要するに民間でも公立でも費用は変わらないのだということで、現実はちょっと違うのかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-082"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点目、全ての子どもたちが遊べる公園ですけれども、最後に課長からご答弁がありました、荏原地域で２園開園の予定があるということもありました。ただ、やはり公園の整備は必要ですので、これを進めていただく中で、さらにこれは全ての子どもたちだけでなく、一般の利用者に対しても公園等の整備は必要でありますので、これはぜひ進めていただきたいという要望もします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"採択を主張しますが、ちょっと意見を言わせていただきます。予算のところ、国に求めているというところですけれども、引き上げていくこと、そして、人口増に合わせて予算を増やして、インフラの整備を行っていくこと、これも当然であると思っています。以上、賛成で採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほど申し上げたこととほぼ重なるのですけれども、まず、１番のところ、待機児童の解消に向けて、既に区も相当の努力をしていることは承知しておりますが、まだ待機児童があるという意味からいえば、さらにこのペースで進めていただければと思います。というところから、特に３番の民間委託に反対というところがひっかかるところもありまして、私どもとしては不採択としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、１番、３番なんかに関しては、先ほど課長がお話しされたのですけれども、区のほうの役割は非常に重要であると。一般質問でもさせていただいたのですが、先ほどあべ委員からもありましたけれども、所管を越えて、先ほどの学校の校庭なんかもそうなのですが、そういったことも含めて、待機児童の対策を全庁挙げてという体制づくりを要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-086"}]},{"id":"topic-06","title":"その他の(1)委員長報告","agenda":"その他の(1)委員長報告","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"質問６番目の、兵庫県の第三者委員会、調査が行われましたけれども、品川でも約２００万円ほど疑義があるということなので、その調査も行っているということですので、経過と課題等を、改善策の提案とか、報告書も提出してくださいと言ったのですけれども、しないということだったので、提出しない理由を伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"何に謝罪かというのは、事業者を選定したこと、そして、再度事業者を変更しなくてはいけない、それについて謝罪したと認識しておりますが、それを繰り返して説明してよろしいのですか。それでいいのですか。これしか言えませんけれども。","voiceIndex":275,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問","question":"同じく石田ちひろ議員の待機児童ゼロの質問なのですけれども、質問２のところで、待機児童が解消しない理由を伺ったら、答弁の中で区民の期待が高まっていますというような理解に苦しむ答弁だったので、何のことだか、答弁自体が理解できなかったので、結局、いろいろな区民の状況の困難を理解されているのかどうか、その辺が疑問だったので、もう一回その辺をお伺いしたい。","respondent":"齋藤子ども未来部長","answer":"お尋ねが、お母さん、「私が子どもを産んだのがいけないのですか、それで待機児童解消ができないのですか」という質問だったので、そんなわけはないので、そんなことはあり得ませんとも言えないので、きちんと事実を踏まえてご答弁させていただいたつもりでありまして。","voiceIndex":281,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"質疑の中で出てきた答弁をそのまま聞いているのです。だから、そちらから発した言葉に対して、これでいいのですかという質問であったわけなのです。こちらが選んだ質問ではないです。では、どこどこで質問した項目を聞いたというのを明らかにします。こういう聞き方をしていいのかと、今、質問が来たので、それの質問はそちらから答えられた言葉をこうやって表現したものなので。","respondent":"齋藤子ども未来部長","answer":"前のほうの、「子どもを産む母親のせいですか」と言われて、「そうだ」と思う人はいらっしゃるのですか。（「いないでしょう」と呼ぶ者あり）ということなので、丁寧にご説明したつもりです。","voiceIndex":283,"id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"もう一回質問の中身を、どうしてこういうことになったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問","question":"まだあったのですが、今、話が途中で紛糾してしまったのですが、まだ他にあるのですけれども、いいですか、具体的に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のではないです。途中だったのです。事によってはなしになるかもしれないのですが、質問３のところで、地域と年齢ごとの認可保育園の需要調査を求めたのですけれども、既に数を把握しています、なので調査はしませんというご答弁をいただいたのですが、もし把握しているのだったら、ぜひそういうのをみんな求めているので、どんな状況か、どこかで報告していただきたい。できるのかどうか。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":289,"id":"exchange-092"},{"speaker":"飯沼委員","kind":"確認","question":"ごめんなさい、検討したときに、今まで林試の森の国家公務員の宿舎の話ばかり出ていたのですが、その横のところの都有地まで視野に入っているのかというところで、確認したかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-093"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64791,"voices":296}},{"id":"h28-20161128-5","meetingId":"h28-cm11","date":"2016年11月28日","dateIso":"2016-11-28","committee":"総務委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会議の運営上、順番を入れ替えて、契約議案の審査を先に行います。 まず、(4) 第１０３号議案 中延一丁目区営住宅および従前居住者用住宅新築工事請負契約","agenda":"会議の運営上、順番を入れ替えて、契約議案の審査を先に行います。 まず、(4) 第１０３号議案 中延一丁目区営住宅および従前居住者用住宅新築工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと今の委員長の発言と外れる部分があるかもしれませんけれども、幾つか伺っていきたいと思います。それと、もともとあった住宅からどのくらい戸数が増える部分があるのかないのか、広くなったのかどうか、そのあたりと、大体３ＤＫとか２ＤＫというのは、どのくらいの広さなのか、そのあたりを具体的に教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"Ａ、Ｂ、Ｃ、Ｄということで、Ａ、Ｂについては区営住宅部分を示しております。Ａタイプが５１.２４m2、３ＤＫです。Ｂタイプが２ＤＫ、４６.４６m2。従前居住者住宅のＣタイプにつきましては、２ＤＫ、５０.１４m2。Ｄタイプ、１ＤＫ、３０.３６m2となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それと、住宅の広さなのですが、５０m2を超えているというファミリータイプ、そういうところで、もう少し広くていいのかなという気はするのですけれども、そういうことがわかったということで、それは伺っておくということでいいと思いますけれども、増えたのか、減ったのか、同じなのか、そのあたりを教えてください。","respondent":"小林施設整備課長","answer":"平米単価につきましては、どのくらいだというのは非常に難しいご質問で、用途、それと立地条件、例えば、今回みたいな中延一丁目は単品でこれをつくるのですけれども、地盤面からそのまま作っていく。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"だから、その金額が本当に適正なのかというところはわからないですね、率直に言って。不勉強も不勉強だと思うのですけれども、だから、そういうところを……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"だけど、またそれでこういういろいろ入札されている方たちのほかの事業所の金額なども、そんなに大きな違いがないので、これはそんなにひどいというか、不適切とは思わないですけれども、しかし、基本的な考え方のところはちょっとわからないので、そういう質問をさせていただいたのですが、信頼をしているというところで、そういう説明を受けとめていきたいと、そういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"今回、新築工事ということなのですが、今までの建物は、建てて何年ぐらいになっていたのか、また、従来の建物は、耐震補強はもう済んでいるかと思うのですが、これは何年前に実施したのですか。そういういろいろなものを考えた上で、今回、新築というところに走ったと思うのですが、その辺をお聞かせください。","respondent":"立川経理課長","answer":"それで、今回の計画としましては、いわゆる昭和５６年以前の建物ですので、旧耐震基準ということで、耐震工事が必要ということで考えていたところですけれども、密集住宅市街地整備促進事業との関係もありまして、築後４０年以上たっておりますので、今回。","voiceIndex":11,"id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"従来の耐震基準云々というのはわかるのですが、コンクリートで建てたものは、大体５０年から６０年もつという話の中で、こういうふうに４０年ということで建替え、やむをえない事情もわかりますが、ちょっと時期として、財政的に今やるべきだという決断だとは思うのですが、何か前へ前へ、建てることはいいのですけれども、どんどん前倒し、税金を投入して新しく建てていくというのは、どうなのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私が、資料をいただいたときに、事前に調べればよかったのかもしれないですが、容積率と建ぺい率を教えていただきたいのと、もし両方とも結構余裕があるならば、なぜめいっぱいにしなかったのかなと。そうすると、政策的な判断になってくるのだろうけれども、そこら辺のところをまず教えていただければ。","respondent":"小林施設整備課長","answer":"近隣の住民の方といろいろと、計画説明会などでご意見をもらったところですが、いろいろとご意見がありまして、やはり容積率めいっぱい建てていきますと、いろいろなご意見がありましたものですから、なかなかめいっぱい建てるところが難しかったところは事実としてあります。","voiceIndex":14,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、建物コストは下がっているから、それは民間の考え方であって、私は行政はある程度、その需要に応じたときに、それなりに対応して発注をかけていくということが、平準化してしていくことが必要だと思っていますので、これはこれで私はいいと思っていて、今の４０万円の部分についても、坪単価で１３０万円ぐらいというのは、今の相場から考えて。","respondent":"小林施設整備課長","answer":"非常に難しい質問ですけれども、そういうところでまずは事業を進めていくというのが大前提でありますので、非常に難しい課題だと考えています。","voiceIndex":16,"id":"exchange-008"}]},{"id":"topic-02","title":"第１０４号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更","agenda":"第１０４号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"すみません、課長はそれを事前に、今回、こういう工事を行うのにあたって、関係諸官庁といろいろ打ち合わせをして、それでこの見積もりを出していくのではないですか。そういうものをもし交通量が多い云々なら、おそらく警察のほうも事前に、こういうわけでそこは困るという話があって、見積もりをとって、入札にかけると思うのですが、それはしなかったのですか。","respondent":"和田河川下水道課長","answer":"基本的に区役所が積算するのは、可能性がある限りは安い工法でということで積算をするのが基本ですので、図面上はできると判断して、設計上は地上からの地盤改良工法ということで積算をしたものです。","voiceIndex":32,"id":"exchange-009"}]},{"id":"topic-03","title":"第９５号議案 品川区災害復旧基金条例、および(2) 第９６号議案 品川区災害復旧特別会計条例","agenda":"第９５号議案 品川区災害復旧基金条例、および(2) 第９６号議案 品川区災害復旧特別会計条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"そういう点では、やはり予防が本当に重要だというふうなご認識を区自体が持っておられる、そういう点で、やはりこの災害対策の基金を設置するに当たって、なぜ予防を入れないのか、仕分けをしたそこのところの趣旨がどうなのかをまず伺っておきたいと思います。","respondent":"秋山財政課長","answer":"そういう今まで進めてきた施策の中に、もちろん位置づけられるということで、あくまでも今回の特別会計と基金は、防災に対する備え、品川区としての備えを確実なものにするというメニューの１つというふうに区の大きな防災の事業。","voiceIndex":47,"id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"しかし、やはり書いておいたほうがいいのではないかと思ったので、そのあたりのことを１つ伺います。それともう１つ、品川区はこの間、何年も前から、議会の場でも防災に関する基金をつくる必要があるのではないかという提案がいろいろな方々からありました。それがやれないというふうになったのか、そういう考え方になったのか、そういうものがあれば、やはりわかりやすく説明をしていただきたいと思います。","respondent":"秋山財政課長","answer":"今までできたものができなくなったからこれをつくったということではなくて、特別会計をつくることによって、品川区として大きな災害に対して基金という１つの枠の中にお金を入れするわけですから、現実としてそのお金を用意しているのだということを明確にしたというところで。","voiceIndex":49,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"何かあまりよくわかりません。それをしないで、すぐ執行しなくてはいけない、そこはでは何なのですか。どんなことを想定しているのですか。その具体的なところを教えいただかないとわからないです。よそで発災したところで。困ったということは、どんなことが困ったと聞いているのですか。その辺が全然わからないです。もう少し説明をしていただきたいと思います。","respondent":"秋山財政課長","answer":"これはおっしゃるとおり、すぐ議会を招集して議決すればいいだろうということは、確かに、熊本、ほかの今までの特別会計を持っていない自治体であれば、そういうふうなことをやっていたのですが、そうではなくて、この間もしっかりとした財政的な体制を確保するのだと。","voiceIndex":51,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"今、課長がおっしゃった品川区が当座のところの手当てを早く出したいというところは、それはそれとしてわからなくもないけれども、でも、それはどこの自治体でも会計をつくらないで、基金がなくてもやれてきたことなのに、なぜそういうふうにやれてきたのに、こういうふうに変えようとしているのかという趣旨が、あまり根拠がないかなと思いました。改めて伺って、ほかの方に譲りたいと思います。","respondent":"秋山財政課長","answer":"ただし、災害が起こった後の、それに対応する予算は、どのような状況であったのかという経理の状況を明確にするという意味からも、発災後の復興に関する予算等につきましては、この特別会計の中で使っていきたいというふうに考えていることもあり、今回。","voiceIndex":53,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"ちょっと繰り返しになりますが、今、南委員からもありましたが、桑村副区長のときもそうだったかと思うのですが、企画部長のときに、「基金は資金の固定化につながる、基金は増やさない。なぜそういうふうに明言されていたのが、こういうふうに変わったか。そして、品川区でこのように基金を、とりあえず基金のほうですが、つくるということで、急に１５億円という話が出てきました。","respondent":"秋山財政課長","answer":"熊本も１つのきっかけではありますし、ただ、そのときに、では、当座の資金をどのように確保するのかということを考えたときに、確かに専決であるとか、補正予算というのも１つの方法ではありますけれども、基金と特別会計をつくって、今回セットで明確にし、なおかつ。","voiceIndex":55,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"今、課長にお話ししていただきましたけれども、大切な話ではないですか。特別会計の。では、これが本来なら、予算が出たときに、そのときに明示すべき話ではないのですか。ポッと沸いて、こういうふうにつくりますという話では、僕は違うと思うのです。これだけ立派な、世間にも公表をもちろんしているわけだし、その辺についてどうお考えですか。","respondent":"秋山財政課長","answer":"そう考えると、特別会計がつくっていないと当初の議案は提出できないと思っています。","voiceIndex":57,"id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"最後に意見だけ。せっかくこんな立派なものを提案されてくるならば、やはりきちんと当初予算に持っていけるような、そのときに話が出るような仕組みづくり、提案をすべきだったのではないかと、去年もいきなり文化スポーツ振興基金が出ました。あれも唐突ですよね。意見だけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"すみません、いろいろ教えていただきたい、確認させていただきたいのですが、１５億円ということで、１５億円の金額の根拠と、あと、この中にも被害想定で、迅速な災害救助と復旧体制をつくっていくことが可能になるということで、どういったことを考えていらっしゃるのか、その内容について教えていただきたいのと、どこまでをお金をこれは使えるのか、どこまでが、これ以上は使えないというような。","respondent":"秋山財政課長","answer":"１５億円の根拠ですけれども、今回、予算を立てるときに、財源として活用できるのは、一つ繰越金が考えられます。","voiceIndex":60,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"ただ、お金については、先ほどのお話だと、食料等、また復旧体制のお話でインフラ整備ということで、食料だとすぐに必要、迅速に必要になってくるというところでは、即時投入ができるほうがいいですが、そういった部分では、お金の管理ということで言うと、どうやってお金を、この１５億円については管理していくのかについて教えていただきたいと思います。","respondent":"秋山財政課長","answer":"１５億円の見通しですけれども、今、一般会計を含めて特別会計も当初予算案を策定をしていますので、その中でどの程度の規模を想定するのかということを、今、検討しています。","voiceIndex":62,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"基金のお金の管理の仕方、例えば迅速に投入する際に、例えば食料を買わなければいけないというところで考えたら、現金が必要だと思うのですが、そういった現金が必要になるということは、現金でどこかである程度、一定確保をしていけないのかなというところでは、そういったお金の現金の管理とか、また、即時投入というところなので。","respondent":"秋山財政課長、中山企画部長","answer":"現金の管理といいますと、基金として現金を持っているものを使えるような状態にする。基金を使うには予算案が必要なので、そのための議決をいただいている、そういうふうにお考えいただければと思います。これは一定の、もちろん通常の基金ですから、持ち方の運用で会計管理とやっていく部分と、実際の実行になると、例えば見舞金のようなもの、現金で出すもの、それから支給の支払いをやる場合の決裁性のある持ち方、これは。","voiceIndex":64,"id":"exchange-019"},{"speaker":"吉田委員","kind":"確認","question":"皆さんの議論で少しずつ自分の中で理解しようとしているのですけれども、確認なのですが、これ、資料のほうには、設置目的で、「首都直下地震等が発生した場合」というふうになっていますが、条例のほうは「災害」というわりと大くくりな文言になっていて、説明を聞いていれば、そういう普通の災害、大きなものを想定しているのだろうということはわかるのですけれども、やはり想定しているのは。","respondent":"秋山財政課長","answer":"創設時の規模と書かせていただいたのは、おっしゃるとおりで、今後は、当初予算の中で、特別会計の規模は当初予算の中でご議論をいただくことになりますので、基金については、その都度、状況、それから基金のほうに積める原資がどの時点で出てくるかという話もありますので。","voiceIndex":67,"id":"exchange-020"},{"speaker":"吉田委員","kind":"確認","question":"今までの議論を伺っていると、やはり特別会計を設置して、最初にきちんと議決をしておくということが、そのお金の使いやすさというのでしょうか、目的とする事業が発生してしまった場合、迅速に適用できる、使えるというようなことだと思うのです。今この漠とした感じで決めてしまっていいのか不安なものですから、その辺を確認させてください。","respondent":"秋山財政課長","answer":"私どもとしても、発災から短期間の間にというものは現金としてのものというご説明をしますけれども、その中にはやはりそれなりに避難所の運営の食料であるとか、輸送であるとかというものを想定をして、当初予算の中でご議論をいただくということを考えておるものです。","voiceIndex":69,"id":"exchange-021"},{"speaker":"吉田委員","kind":"確認","question":"最後に確認なのですが、今ここで決めるということは、特別会計を設けるということと、基金を設けるということで、最初の予算規模の１５億円というのは、補正予算の議論のときにもう１回これをやるということでよろしいのでしょうか。確認です。","respondent":"秋山財政課長","answer":"今回ご議決いただくのは条例の２案でございまして、議決後、明日、補正予算として提出させていただいているのは、繰越金を原資とした１５億円を基金に積むということの審議でありまして、当初予算の中では、特別会計の規模も含めて、今回いろいろご議論がございましたので。","voiceIndex":71,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"確認","question":"議論していて、私の理解している確認と、今の答弁とかも含めて、意見がある部分と、ややこしくなるので、あまりあれなのだけれども、あくまで今日は、これは議案としては、特別会計をつくる、基金をつくりますという条例案であって、内容の部分という部分は別にするというつもりでいたのだけれども、私はこういう基金条例をつくる、そういう特別会計を設置するということは、いいことだと思っている。そこは。","respondent":"桑村副区長","answer":"今までいろいろご議論いただきまして、１つは、特別会計を先に設置しないと、特別会計自体が出せないという部分があってこういうことになったと思いますが、１つはお話があったとおり、今まで復旧だ、復興だということにどれだけお金がかかるのか、それは神戸ですとか。","voiceIndex":73,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"まさに私は、この条例案については、先ほども冒頭言ったように、考え方はそれでいいと思うのです。は０－０の話、あとは想定の話と、今言った災害救助法の避難所の扱いを、備蓄はどうするという話を、よく言う３日間という話とか、２日間という人もいる、食料については。そのかわりお金はきちんと用意しておくという部分では、繰り入れなければ０なのだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"いろいろ私も冒頭質問させていただいて、皆さんのご質疑を伺っていて、やはり最初に質問した内容については解明されていません。やはりそのまま疑問のところは疑問です。文言についても、対象の範囲をはっきりさせておかないと、そのときの状況は、どんどんひとり歩きしてしまう。そういうわけですから、やはりこの文言は規定をしておく必要があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"やはり条例を審査するというのは、その条例の中身がどうかということを見極めなければ、賛成していいのか、反対していいのか判断ができないから言っているわけですから、そういうご意見があったにしても、それはそれでご自分の意見として黙って聞いていてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"委員長、言ってください。石田秀男委員、ちょっと静かにして聞いてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"もうそれ以上、静かにしてください。でも、「復興住宅」という言葉を一つピックアップして考えたときに、これは品川区の独自財源でやるべきものではないと思うのです。したがって、そういう意味も含めて、復興まで入れるというのは、やはりどう考えても納得できないです。改めてそこのところについて伺いたいと思います。","respondent":"秋山財政課長","answer":"幾つかご質問いただいていますけれども、まずは有価証券の件でありますけれども、これは基金の通常の、ほかの基金も同じような文言を……。お金を持つ、現金を持つということと同等というふうに考えていただいて結構だと考えています。それから、もちろん一般会計の充実ですけれども、それはそういうご意見というふうに承っておきます。","voiceIndex":82,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"それともう１つの理由が、質問としては伺ってこなかったのですけれども、やはり今、国と地方自治体との関係で、とりわけ東京２３区が財政的にも非常に潤っているということで、法人住民税ですか、そういうものの引き上げだとか、そういう国との関係でのところを見て、やはり基金として積んでおく、そういうことでの１つの方策としてこの基金が出てきたのかなというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問・要望","question":"すみません、最後に確認も含めて、また自分自身の理解の部分も含めて教えていただきたい部分が幾つかありますが、各委員から何度も確認があったとおり、基金条例と、それから特別会計の内容については、設置目的のほうには「地震等の発生した場合」、そして基金条例の設置の第１条にも「災害時」であって、時系列で見ると、あくまでも災害が発生した後の対応のための、それに資するための基金。","respondent":"中山企画部長","answer":"４月に熊本の発災後、国の補正予算の議決が５月１７日、１カ月余。それから、都道府県を通じて歳入されるまで２カ月ぐらいかかる。これが先ほどタイムラグというふうに言っている部分で、今回、こういうものの迅速性を確保するための体制をとってよろしいかというご提案です。","voiceIndex":86,"id":"exchange-030"},{"speaker":"南委員","kind":"意見","question":"反対です。確かにタイムラグはあっても、しっかりその間は区の独自財源を使って支出をしていくということも、議会を招集して議決していければできることですし、品川区は十分な財政状況はありますので、やはりそれは改めてこういうふうにしなくても、私はいいのではないかと思っていますので、そういうことも含めて反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"反対です。その理由は、さっきも言いましたけれども、やはり対象を復旧、復興まで広げていて、これは議決を先にしてしまうわけですから、区長の意思で使う先をどんどん拡大できてしまうという、そういう点で非常に問題があるのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-032"}]},{"id":"topic-04","title":"第１１３号議案 職員の給与に関する条例の一部を改正する条例","agenda":"第１１３号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その中で区の職員の平均給与は６００数十万円ということで出ていて、私は品川区内、中小企業にお勤めの勤労者、それから年金生活者も含めてそうなのですが、多くの方が実質所得、国民所得は減っている中で、皆さんに、区民にかわって行政または我々議員も含めてそうですが、皆様大変な中で、値上げに持っていくというのは、ちょっとまずいのではないかと思うのですが、実際、お聞きしたいのですが。","respondent":"米田人事課長","answer":"ですので、職員の給与の比較といたしましては、人事委員会が行っております民間企業実態調査に基づき行われているものが、いわゆる公務員比較の対象としては正しいものではないかというふうに考えてあります。","voiceIndex":119,"id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"もう１点だけ。今、１,０００社、東京都内の１,０００社の企業にお勤めの会社、５０人以上の規模の方の勤労者所得も含めてということですが、この国税庁のやっているものは、給与所得者数５,６４６万人を対象にして、給与総額をこの人数で割っている。そうすると、対象が５,６４６万人という方を対象にした平均給与と、あまりにもかけ離れていると思うのですが、そこについてもう１回お聞かせください。","respondent":"米田人事課長","answer":"特別区人事委員会における民間企業実態調査におきましては、先ほども申し上げましたが、年齢ですとか、学歴ですとか、役職、それをきちんと民間の５０人以上の従業員の方と対比した上で計算しているものですので、それに基づいて勧告がされており。","voiceIndex":121,"id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"特別区人事委員会から来ている、そういう資料に基づいてというお話ですが、やはりこれだけ新聞等にも載って、大半の国民所得が減っているという状況を踏まえて、また、区内産業にお勤めの方も減っているということを思うと、やはり東京都のほうにも、私はきちんと意見を申して、今はとどまるべきだろうというような、そういう意見もしっかり言っていくべきではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ。教えていただきたいのですが、特別区人事委員会の勧告、これはこれで、５０人以上、前は１００人だったところを５０人までしてやってきた。特別区は。東京都がやらないと言ったら、県費職員の話、そこはやらないけれども、所得を合わせますというようなことがあわせて出てきたと思うのだけれども、こういうことはこれからも起きてしまう可能性はあるのですか。２３区はそろう。","respondent":"米田人事課長","answer":"県費なのですけれども、こちらについては、東京都の人事委員会が東京都全域の民間企業実態調査を行いましたところ、差額がわずかに公務員のほうが安かったのですが、その差額が年間給与ベースにすると１００円未満であったために、改定は行わなかったですので。","voiceIndex":124,"id":"exchange-036"}]},{"id":"topic-05","title":"平成２８年請願第１５号 「不調」となった入札結果を踏まえ、八潮６９号棟（雇用促進住宅八潮宿舎）の購入","agenda":"平成２８年請願第１５号 「不調」となった入札結果を踏まえ、八潮６９号棟（雇用促進住宅八潮宿舎）の購入","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、東ブロック、西ブロック等々の入札、開札等々についての報告、説明がありましたけれども、東ブロックのほうが５２２件、応札なしという、そういう状況をどういうふうに見たらいいのかなと思っているのですけれども、区としてのこの結果について、一定の見解があれば教えていただきたいと思います。その点についても教えてください。ごめんなさい。品川区も買う方向にはない。何点かお願いします。","respondent":"柏原企画調整課長","answer":"ただ、八潮のまちづくりに関しましては、にぎわいであったり、居住者の年齢構成であったり、まちづくりをする上では区としましても考えなくてはいけない部分は多々ありますので、それはまちづくり全体という形では検討は引き続きしていきたいというふうに思ってありますけれども。","voiceIndex":140,"id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"品川の区民。そういうことに対して、そういうことで済まさないような一定の、今までの質疑、行政の中で出してきた見解とはまた違う見解を持つべきだと思うし、期待をされて、ぜひ品川区にすがるしかないのではないかという思いで請願を出されてきているわけですから、そういう点について、あまりにも冷た過ぎると思うのです。その辺の認識、どういうふうに見ているのかをまず伺いたいと思います。","respondent":"柏原企画調整課長","answer":"八潮のまちづくりとか、八潮の今後の話の部分ですけれども、これにつきましては、この６９号棟のほかにも住宅は多々、さまざまな種類があるというところがありますので、ほぼこの住宅だけの問題ということで八潮全体というよりは、ほかの住宅、それから人口の流入であったり。","voiceIndex":142,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"さっきも言ったように、少子化のまちになっている、そういう中で特に６９号棟から通学している子どもが、中学１年生の学年だけでも６分の１はいると。その子どもたちが、何年か先ですけれども、そういう形でずっといったときに、不調になってしまったときには、５年後には退去しなくてはいけなくなるわけですから、望まなくても八潮の一貫校の存続にとっても大きな問題になってこざるを得ないわけです。","respondent":"柏原企画調整課長","answer":"今後１０年間につきましては、家賃の関係であるとか、転売はできないであるとか、もろもろの規制といいますか、取組みをした上で入札に応じているですので、基本的には、一般的な民間売却ということで、今のところで何か不具合が想定できるかというところでは。","voiceIndex":144,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、もっともっと子どもを産んで育ててほしい、そういうことは期待するわけですけれども、しかし、それとこの八潮の６９号棟の売却の問題は、全然質が違う問題ですので、それをもって売却されてしまう、そういう状況に歯どめはかけられないわけですから、機構に対して強く申し入れているというお話ですけれども、今、不調に終わった原因を調査をして。","respondent":"柏原企画調整課長","answer":"今回も入札に関しましては、先ほど来申し上げてありますけれども、売却方法等々を検証して、現に住んでいる方たちが引き続き住み続けられるように全力で取組みをしますですので。","voiceIndex":146,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"最後に確認します。だから、２年間は住めるけれども、３年目以降は出ていかなくてはいけないという、そういうことになって、今までとの考え方、説明とも全然違ってきてしまっている。そういうことについては認識しておられたのか、あるいは、初耳なのか、私が説明したことを質して、きちんと向こうに申し入れなりをしていただきたいと思っていますけれども、それについてはどうでしょうか。","respondent":"柏原企画調整課長","answer":"後段のほうのお話につきましては、私は個別の話のところで承知はしておりませんので、個別のものにつきましては、我々のほうからも機構のほうには確認させていただきたいと思いますが、定期借家の部分と、それから一般でずっと住んでいる。","voiceIndex":148,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"今もちろん調査していただいて、確認していただきたいです。ですから、あと５年住めるところが２年で出ていかなくはいけないことになったということで、新たな状況だと思うので、そこはしっかりと調べていただいて、とんでもないと言って訂正をさせるように働きかけはしていただきたいと思っています。その点について最後に伺って終わりたいと思います。","respondent":"柏原企画調整課長","answer":"契約の形態が個々でどうなっているかというのは、私の手元にありませんし、存じ上げない部分はあるのですが、通常は定期借家という期限を切った入居の契約ということでありますので、通常であれば、その期間内で退去していただくことが通常の部分であります。","voiceIndex":150,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこに対して相変わらずというか、機構と品川区のやりとりが、何か丁寧に進められていないのではないかという印象はどうしても持ってしまうのですけれども、２月の時点の議論の中でも、もう少し機構に対して見通しというのでしょうか、お住まいですので、そんなに短いスパンでは、住んでいらっしゃる方も考えにくい、自分の生活設計とか仕事のことについても及んできてしまいますので、今の時点で。","respondent":"柏原企画調整課長","answer":"繰り返しになりますけれども、なかなか数が多い、それから広いといったところがあるので、なぜ入札に応じてもらえなかったということについては、研究といいますか、検討はしていくということで、それは先ほど委員のほうからもお話がありましたけれども。","voiceIndex":153,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"住まいというのは生活の基本なので、それがもしあったときは、では、区としてはどういうフォローをするとか、機構としてはどういうフォローをするつもりがあるというか、今お話のことは結構手続、入札に向けた手続のことにはそういうふうに進んでいらっしゃるようですけれども、その辺のフォローをもしいろいろ不調が重なったときは、では、どの時点で次の方策を決断するとか。","respondent":"柏原企画調整課長","answer":"前提のお話としましては、繰り返しになってしまいますけれども、現段階で不調になったらというところでのお話はなかなかできない部分がありますけれども、住んでいる方からいたしますと、不安の部分は大きいというのは、それは十分認識はしておりますので。","voiceIndex":155,"id":"exchange-044"},{"speaker":"吉田委員","kind":"意見","question":"私がお話ししているのは、この八潮住宅のこのことについては、今年の第２回定例会にも確かに出ておりますけれども、その前の２月というと第１回定例会のときも、その前段階の請願が出ていると思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":160,"id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"ほかの会派からも、区民のあれは守るのだねというような確認の結果、やはり不採択だったのですけれども、そのときの……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-046"},{"speaker":"吉田委員","kind":"意見","question":"すみません、そのことについて。あら、どこまでいった……。すみません、ちょっと待って、どうしよう。後で……。〔「いいよ、休憩してから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺を教えていただきたいのと、また、先ほどから２月の話もありますが、そうした話の中でも確かにぜひ今住まわれている方の不安をできるだけ取り去っていただくようにというか、相談に乗っていただいて、１,０００人いる品川区民に寄り添ってくださいという話も確かにしていると思いますが、品川区としては、先ほどからも情報をもらっているということですが。","respondent":"柏原企画調整課長","answer":"団体といいますか、お住まいになっている方々との団体のお話し合い、これは自治会の方々も含めてですけれども、お話をさせていただいたりといったところで、そういった対応を個別の対応として区としてもさせていただいたといったところです。","voiceIndex":168,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"若干繰り返しみたいになってしまうかもしれないのですけれども、住んでいる方にとっては５年はすごく短いと思うのです。繰り返しますけれども、品川区民ですので、やはりそこの区民の住まいの不安定さというのは、品川区としてももう少し主体的に機構に積極的に働きかけていただきたいというふうに思うのですけれども、その辺についてはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ただし、今お話がありましたとおり、品川区に住まわれている方々ですので、個別の対応も含めて、どういった形ができるのかというのは、ご相談に応じたいといったことは引き続きさせていただきたと考えています。","voiceIndex":170,"id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"話し合うということでは、今もやりとりはしていらっしゃるようなのですけれども、ぜひ品川区民を守りたいという、区民の住宅をきちんと確保すべきというところについては、皆さんどの方も同じような思いではないかと思いますので、ぜひそのことを機構に対しても、もう少し強く申し入れをしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"確認","question":"そういうことは、やはり区も把握をして、例えばここにある１０年間同じ条件で全ての人が居住できるということだとするならば、そういうふうに言ったとするならば、改めてそこは区も確認をして、どういう状況があっても、ここは品川区民の方なのだから、そこはやはり区もある程度対応はするべきだろうと、それが言っていたことと変わるというのはいいことではないと思うので、そこはもう１回確認を。","respondent":"柏原企画調整課長","answer":"そういった方々の離職者、それから移転就職者の方々の再就職なり、国のエネルギー政策の転換であったりとかというところもありますけれども、こういったところで今のエネルギー政策に変わって、整備されたのは１９６１年ぐらいからだと聞いてありますけれども、一定程度。","voiceIndex":173,"id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそこの２番目の確認はしていただきたいと、区民の方も品川区民であるし、そこら辺の誤解がある説明であってはいけないのかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"民間では大体契約書をつくって、借家法というのがあって、大概、通常は２年間で更新していくというのが一般的な契約だと思うのです。この方たち、確かに将来の不安はあるのですが、いろいろなそういう契約書ならびに区が相談窓口になって、これからも住民のために支援していくということですから、それは信じて、契約書、法の下に進めていくというのが区の立場であるべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、５年間は、平成３３年までに今の住宅は売れなかったら撤去する、廃止するということですから、５年間は何とか住んでいられるけれども、その後の５年間の全体で今から言って売れたときの１０年間ということだから、買い手が見つかったときであって、全然保証などないというところは、改めて確認をしておきたいと思っています。","respondent":"柏原企画調整課長","answer":"ただ、先ほど来、いろいろ議論が出てありますけれども、品川区民、品川区に住んでおられる方ということで、それは同じですので、そういった方たちに対して不安をどうやって取り除けるのか、個別にどういう対応ができるのかということにつきましては、引き続き。","voiceIndex":177,"id":"exchange-054"},{"speaker":"石田（秀）委員","kind":"意見","question":"今日、結論を出してもらいたいと思います。態度については、先ほどお話ししたように、一定の役割を終えたということについては、私どもは支持をする。今言った区民に誤解を与えるようなことをもし機構側が言っているのなら、それは区がいろいろと区民に携わってもらいたいと思います。購入については、先ほども言ったけれども、私はするべきではないと思っていますので、不採択。不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-055"},{"speaker":"つる副委員長","kind":"確認","question":"第２回定例会のときに出されたときにも不採択にさせていただいた理由を申し上げましたが、そのときも含めて、今もこの６９号棟の自治会の皆さんは、自治会としての動き、これも会派の中で確認したときにされているというふうに伺っておりますし、当然今日ここにある請願趣旨に書かれている内容、また質疑の中でさまざま出てきた声が非常に切実なものであるということは事実でありますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"今、副委員長の発言を聞いてわからないところがあったので、そこについても表明をしておきたいと思っているのですけれども、自治会が動いていると、確かに動いてはいるのですけれども、居住者のそういう願いに対しての方向性とはちょっと方向が違うというふうに思っておりまして、その点について、どの程度お調べになったり、あるいは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すで、態度は不採択でお願いいたします。今回もいろいろ皆さんからお話を聞いた中で、しっかりと今やはり品川区民がそういった不安な状況にあるというのは事実であるので、そうしたところを品川区としても連携をしっかりとっていただきながら、てきるだけそうした不安の払拭に努めていただきながら、これについて連携、機構等としっかりとお話をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-058"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということで、実際、契約書、借家法がある限り、住民を簡単に追い出すということはできないはずです。ですが、やはり法治国家ですから、そこをやはりきちんと理解していただいてやっていただきたいと思います。品川区もできるだけの支援をしていると思いますので、お願いいたします。請願の趣旨に対しては反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"ただ、今回、不調ということがあって、一段と住んでいる方たちの不安定さは増しているわけで、その段階で、購入についてというふうについていますけれども、機構と真剣に話し合ってほしいということについては、本当にそのとおりだというふうに思いますので、話し合った結果の結論はまたどうかということはあると思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64240,"voices":193}},{"id":"h28-20161129-6","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"区民委員会","time":"午前１０時００分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"本日は、都市型観光","agenda":"本日は、都市型観光","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"この品川区観光振興協議会というのが設立されて、今後の都市型観光を品川区で確立というのですか、期待をするところです。この委員名簿ですが、４０名と多くて、手挙げ方式なのか、区からアプローチをして入ってくださいと言ったのか、その辺を、どういう感じでこの方々がこの名簿に入っているのかということ。例えばですが。だからその辺をどうお考えかというところを、とりあえずお聞かせください。","respondent":"鈴木文化観光課長","answer":"それから情報発信について、特にＳＮＳに関して、特定の担当者を置いたり、または代理店に依頼したりという部分ですが、先ほどご説明しましたように、しながわ観光協会を、この協議会もしくはしながわ観光の情報発信の拠点ということで考えておりまして、現在。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"協議会というのは集合体ですから。レジュメの裏面ですが、外国人観光客への対応ということで、観光の情報発信とか、東京モノレールでのメディアジャックとか、いろいろ書いてあるのですけれど、私の一般質問で聞いたかもしれませんけれど、こういうもので今、品川区に来訪される外国人は何を求めて来ているのですか。何をもってそういうデータが出てきたかというのを、お答えいただきたいと思います。","respondent":"鈴木文化観光課長","answer":"それから国のほうで外国人観光客についての統計とか調査をしておりますので、その情報というのも区で直接取って参考にしているということで、そういう複数の情報に基づいて、じゃあ、品川の観光の外国人対応はどうしたらよいかというのを考えているというところで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これ以上言いませんが、例えば区議会議員は４０人いますから、誰かが外国人のデータはどうなのか出してくださいということで、すぐ出せるような状況にはしていただきたいと思いますので、よろしくお願いします。一言あれば、一言で構わないのでお願いします。","respondent":"鈴木文化観光課長","answer":"すみません、説明が不足していたかもしれませんが、国の調査というのは具体的には、区がかかわるところでは区内すべてのホテル、宿泊施設について、まず区の保健所とかで把握しているデータの照会が、国からまいります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問","question":"それで、せっかくあるのだったら、例えばしながわ観光協会が調査をした外国人観光客の動向という資料というのは、１年間どんどん積み重ねて、２年、３年とできるわけですよね。そういうものが出せるようにしてくださいという質問をしているので、そこがほしいので。","respondent":"鈴木文化観光課長","answer":"失礼いたしました。ご指摘のとおり、しっかりとデータを積み上げて、傾向とか推移とかも見られるような形で、情報の分析も続けていきたいと考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、先ほど言ったように住民にとってピンとこない、なぜ品川は観光かという思いについては、区としてはどういうふうに考えていらっしゃるのか、伺いたいと思います。３つ目は、どうしてそこまで力を入れるのか、改めてそこの説明も伺いたいと思います。区の考えで結構ですので、都市型観光事業というのは、区にとって年間の予算は今どれぐらいになっているのか、この具体像をいただきたいと思います。","respondent":"鈴木文化観光課長","answer":"参考までに、区が、文化観光課が実施するものと、観光協会に委託をかけているものだけをまとめますと、平成２８年度、今年度予算で約１億７,０００万円の予算を計上しております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"その辺について、区の見解を伺いたいと思います。私が問題意識として持っているのは、この都市型観光の取組みそのものが、オフィスとかマンション、ホテルなど再開発のポテンシャルを上げるために目的が置かれているとすると、これは問題だなと思っているのです。その点についてはどのようにお考えなのか、伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"もちろん１００％、全員が不満がないとは申し上げられませんけれども、一定程度しっかりと、暮らしの部分の施策は行われているというふうに認識はしております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"最後にもう１点、別のことで。この資料の裏面の下、今後の取組みのところですけれども、先ほど羽田空港の機能強化も含めて、視野に入れてというお話がありましたけれども、品川区というかこの観光事業ですけれど、品川の上を通過する飛行ルートに期待をしているのか、計画を容認しているのか、そこを伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"品川区の上空を飛行ルートが通るということに関しては、私は所管ではございませんので詳しい情報やそれに関する区の考え方を私が申し上げるものではございませんが、ただ品川区の上空を通るかどうかということではなく、羽田空港の機能が強化されるということは。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"これで最後にしますけれども、品川の上を通るかどうかでなくてといっても、この羽田空港の機能強化というのは品川の上を通る計画として今、議論されているわけであって、そこは切り離せない問題だと思うのです。そうではないのか、そうなのか。機能強化の問題と、上を通る問題は切り離せないと私は思いますけれども、先ほど視野に入れてというお話がありましたので、そこにかかって伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"ただし区民の方の不安、いろいろな危険性というのは区としても認識しているので、国や都に働きかけて安全確保の強化とか、いろいろな要望を出しているというふうに、認識しています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"はじめに、副会長の方ですけれど、跡見学園女子大学の教授ですけれども、都市観光といえば立教大学だと思うのですけれど、その辺はいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"数年前に跡見学園女子大学のほうで観光の学科を設置して、そこをしっかりとＰＲというか売りにしていこうというときに招聘して、入っていただいたというふうに聞いております。たしかその前に、立教大学で観光の研究をされていたというふうに聞いております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"それでよくわかります。すっきりして質問できますが。それをわざわざ文化スポーツ振興部という部をつくって、なおかつ文化観光課までつくった理由というのは、それだけ区として文化観光に力を入れていくという形で、いいのかということの確認と、ここも改めてですけれども、なぜそこまで観光に力を入れなくてはいけないのか、改めてお伺いします。","respondent":"鈴木文化観光課長","answer":"以前の組織では、観光に関しては産業振興の部門にあって、今は新しい部ができて、その理由となぜそこまで力を入れるのかですが、やはり一番大きな理由は、オリンピックに向けて外国人が増えたり、国内からの来訪者も増えるということを考えますと。","voiceIndex":23,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"そうだったのですね。継続はないのですね。そういう答弁に聞こえてしまったのですけれど。なぜかというと人口が増えているわけですから。それで、いかがですかということ。それと、とても細かいことで１点あるのですけれど、出ているのであえて伺いますが、伊藤博文公のお墓がありますよと一番に書いてありますけれど、西大井のあそこですよね、踏切。あそこに伊藤公のお骨はあるのですか。","respondent":"鈴木文化観光課長","answer":"ただ、先ほど申し上げましたように以前の１０年間のアクションプランについては、当時のそういう考え方で進めていたのだと思います。","voiceIndex":25,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"私は観光に否定的ではありません。否定はしません。観光を否定するわけではないですけれども、まず住んでいる方、という思いがあって、今まで質問させていただいたのですけれども、あえて最後にお伺いしますけれども、すべて行政がやることというのはバランスもありますけれども、そういう意味において観光の位置づけを、課長はどういうふうに思っていらっしゃるのかというのを最後にお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"その辺はトータルで、防災が先とか、福祉が先とか、観光が先ということではなくて、区として全体のバランス、またはそのタイミング、状況によって重点的に取り組むという位置づけはありますけれども、全部しっかりとやらなければいけないことであると考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、課長はオリンピック・パラリンピックというのがまずありますという話をしてくださったのですけれども、昨日もこの委員会で、その他のところでビーチバレーのパネルのことを伺ってしまったのですけれども、少し気がかりなニュースを見ました。ビーチバレーの会場は品川区というのがクエスチョンというニュースを、私、目にしてしまいました。ちょっと情報があれば教えていただきたいです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"都議会自民党のホームページでもう提言の内容がアップされていますので、そちらの中で私も確認いたしましたところ、さまざまいろいろな提言をされる中で、具体的にビーチバレーボール会場について、抜本的に見直したほうがいいということが書かれていたということで。","voiceIndex":29,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"それ、大変なことですよね。第１回定例会のときに、区長の施政方針にもビーチバレー、ホッケー、そしてブラインドサッカーが予定と出てきて、正式にはブラインドサッカーはならないわけです。それで２つ残ったわけですけれども、こうやって盛り上げてきている中でどういう、でも提言されたということであるならば、どういう対策をしていくか、現時点でいいですから、お考えを教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区といたしましては、当然のことながら区内に設けたビーチバレーボール会場でオリンピックが行われるということについて、早くから機運醸成の事業をしてまいりましたので、引き続き区で、当初の予定どおりやっていただきたいという気持ちです。","voiceIndex":31,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問","question":"さすが区民委員会は情報が早いなと思いまして。はこれを述べまして、質問に入ります。協議会の委員ならびにオブザーバーで８５名という数なのですけれども、事務局はどういうふうな位置づけになるのか、このオブザーバーを入れて、平成２８年１１月１日現在で８５という数ですが、今後の拡大・展開等、そういったことも可能なのか、その辺を教えてください。","respondent":"鈴木文化観光課長","answer":"今、協議会でいろいろ検討している中でも、実際にそういう趣旨であればというので新たに参加を申し出ていただいた団体もありますので、今後も、物理的な会場の制約等はもちろんありますけれども、基本的には、参加いただけるという意思表示をいただければ、入ることは可能です。","voiceIndex":33,"id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺をさらに視野を広めていただきたいと。今、区内で活躍されているメンバーが中心になってやるから、こういう形になるのは当然だと思うのですが、さらに、ホテルに限らずすべてのことで、鉄道事業者もそうですし、水辺関係も、旅行会社も、既存の人たちが活躍されて、さらに新規の拡大・展開をされると、品川区の発展になると思いますので、その辺の目線をお願いしたいと思いますが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ただ、区としては既存の施設や団体だけに徹底しているということではありませんので、宿泊業でも、今、実証実験が行われている水辺の舟運事業とか、新たな事業者の方が出てきたり、また新たな事業が成り立った場合には、当然お声がけをして入っていただくということと。","voiceIndex":35,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１点。個別の話になってしまうのですけれども、水辺活用とかいろいろ部会が、４部会に分かれてそれぞれ専門的に議論されて、反映されると思うのですけれども、その一つだけ取り上げますと水辺で、いろいろと今後の展開という資料にも載っているのですけれども、桜が載っていないのです。それは個別の話ですけれど、一つ一つ要望を区からも申し入れていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"新しいものをつくる、つくるではなくて、もう少し区内のそういう本当に資源に目を向けてほしいということと。イルミネーションによる街並みの活用で、この前イルミネーションの報告がされました。それも暗いところでイルミネーションが光ってきれいだなという感じで、来るわけですけれども、大井町駅前のイルミネーションは、明るいところに明るいものというのはどうなのでしょう。","respondent":"鈴木文化観光課長","answer":"１点目の地域活性や治安についてですけれども、今回、正副委員長とご相談してリクエストいただいた主な項目を中心に構成しておりますので、当然ご指摘の地域活性や治安については、プランの中でも言及しておりまして、認識はしています。","voiceIndex":38,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"そういうところに目を向けてほしいと思います。治安について。２０２０年の後のこと、オリンピック後、ほかの開催国とかでもあるように落ち込みというのはやはりありますので、その部分、オリンピックまでの明るいところを見るのでなく、その後のこともしっかりと考えていかなければいけないと思うのですけれども、それがこのプランでは読み取れなかったと思うので、そこの部分を教えていただきたいです。","respondent":"鈴木文化観光課長、濱田生活安全担当課長","answer":"それから住民の方への負担ですが、区としてもやはり日常生活の中に来訪者、外部の方が入ってくることというのは、対応が必要だというふうには考えておりまして、具体的な例では、各町会長にもこの計画の資料をお送りして。よって、そういった問題が発生すれば情報を共有して、まちでいえば自主的防犯団体、区では今１６団体ありますが、そういった方たちと区と警察が情報を共有しながら、治安対策を進めていきたいと思います。","voiceIndex":40,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど治安について４３ページに書かれているということでしたが、やはり具体的なことが書かれていないので、きっと観光プランを見た方、地域住民の方が、ちょっとこれでは、観光客が来ても怖いなという印象を持つのではないかと。そして、リニア新幹線の品川駅開業に向けてと書いてあるのですけれども、今、一都六県で工事計画承認処分の取り消しを求める行政訴訟が起きていることを、ご存じでしょうか。","respondent":"鈴木文化観光課長","answer":"それから５年後の見直しに関しても、先ほど申しましたように大きな方向性、方針と戦略を立てた計画でございまして、具体的には協議会で皆さんから意見をいただいて、より適切な展開の方法やルートを考えていくというスタイルですので。","voiceIndex":43,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"リニアのことは知ってください。五輪後も、起きてからでないとわからないというのですけれども、これは本当に先ほども申しましたが、今までオリンピックを開催した地域がその後、終わってからどうなったかという話はあるので、そういうところをきちんと把握しなければいけないと思いますし、今から考えておかなければいけないと思うので、見解を伺います。","respondent":"鈴木文化観光課長","answer":"さまざま視野に入れなければ、もしくは考慮しなければならない項目について、大きな動きがあるものであるから載せているという認識です。それから５年後を今から考える必要があるですが、区としても５年たったら考えるということではありません。","voiceIndex":45,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"最後に伺います。オリンピックに向けてということで、何かよい方面しか見ていないのかなと、明るい楽しくなるようなところしか見ていなくて、そのような状態では足元をすくわれてしまうのではないかと、思ってしまいます。治安のこともそうですし、五輪後のことなども、本当にきちんと計画を立てて、それを示してほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"やはり行政視察に行ったとき、日本人はあまり思わなかった、お猿が温泉に入っているシーンというのは、非常に外国人にとっては珍しいシーンだったというのを聞いたとき、私たちの日常茶飯事、品川区の中で見ている視点というのは、外国人の方から見たら全く違っていいものに見えたり、ここから見えるロケーションってすごいねという、私たちには何でもないところが視点になったり。","respondent":"鈴木文化観光課長","answer":"それが、先ほど申し上げました外国人観光客への対応の中での、体験型ツアーなど今までと違うものを検討しているというところにつながってあります。","voiceIndex":48,"id":"exchange-023"},{"speaker":"こんの委員","kind":"提案","question":"日常の中に埋もれている品川のよさの発掘というのは、やはりいろいろな視点でものを聞くという考え方が大事だというのは、区がされている中でもあると思うので、これをより具体的に進めるにあたって、私もまちの人たちの声も聞いて、また提案なり、声を上げていきたいと思うのですが、最後に感想で終わるのですが、先ほども言った、生まれ育った品川区、大井町駅前も、本当に暗くて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問","question":"端的に、平成１８年度から都市型観光アクションプランをつくって、今年になった。１０年間でこれだけなのと。例えば５年とか１０年の期間でなくて、これに基づいて短期的に、効果的に、具体的な観光施策を立案していかないと、また５年、１０年たってしまう気がするのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ただし課題もありまして、例えば観光情報の一元化や、それを使ったプロモーションの強化、各環境整備や規制緩和への取組み、区民レベルでのおもてなしの意識の醸成、人材の育成といった受入れ体制の充実についても、まだ課題だと認識しておりますので。","voiceIndex":51,"id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"私が危惧したのが、平成１８年から平成２７年の１０年間で計画をつくった、これは新しいことなのでしょうけれど、時間をかけすぎではないでしょうか。だからそれをつくったのなら、プランであって具体化して、実績を出して、費用対効果ではないですが、そこまで、これからまた５年かかるか、１０年かかるか、心配になってしまうのです。","respondent":"鈴木文化観光課長","answer":"新しい観光プラン、新しい協議会の設立によって、新たな展開のフェーズに移ったと認識しておりますので、以前のプランも無駄だったとは思いませんが、よりスピード感を持って、具体的に目に見える成果なり、効果なりが出るような取組みを、しっかりしていきたいと考えております。","voiceIndex":53,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2770#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":33549,"voices":61}},{"id":"h28-20161129-7","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"西大井四丁目障害者グループホーム整備","agenda":"西大井四丁目障害者グループホーム整備","exchanges":[{"speaker":"松永委員","kind":"質問","question":"いつもだと、資料に図面で大体屋上がどうなっているか記載があったと思うのですけれども、この場合の屋上はどのような形になっているのか教えてください。","respondent":"中山障害者福祉課長","answer":"これは木造の通常の家のような形になります。ただ、一部２階の上にロフトは設けさせていただいて、ロフトのところは物置等になるかと思うのですが、屋上は特になく普通の屋根という形状になってあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あわせて土地の貸し付けというのは、無償貸与ということになるのかについてもお聞かせください。それから、建物の建設費用というのはどれぐらいかかるのか、わかったら教えていただきたいのと、そういう場合の補助金の仕組みは、東京都とか国からの仕組みがどうなっているのか、また区からもあるのか、補助金の仕組みについてもお聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"そのほか、運営費の中で、こちらはわりと重度の方を想定しているということになってきますので、運営が開始された暁に、また助成のような形は考えているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回はこういう知的障害のグループホームということで、これは本当に求められている施設ですし、区としても今後、５カ所ぐらいはこのほかに建設をしていきたいというのが前の答弁でもありましたけれども、対象者というところでは、重度の方ということなのですけれども、グループホームができたら入りたいと希望されている方の人数は。","respondent":"中山障害者福祉課長","answer":"なので、世話人が各フロアにそれぞれ１人ずつ配置になるのと、それから夕飯の時間帯ですとか、朝ご飯の時間帯ですとか、そういうところは２人体制みたいな形で支援に入る予定です。資格なのですけれども、サービス管理責任者は、そういった一定の研修とかを受ける必要があります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それともう一つは、既に１１月に地域には、こういう施設ができますよという説明がされたということで、１２月に今度は建設計画の近隣説明会があるということで、ここに書かれていますけれども、近くにふれあい作業所があるので、それでお祭りとかも毎年されているので、地域としては理解がある地域なのかなと思うのですけれども、このグループホームができるという説明会をやったところで。","respondent":"中山障害者福祉課長","answer":"選考に当たりましては、福栄会と区と一緒に入って、あるいは相談支援センターのケアマネジャーにも入っていただいて、行う予定になっています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"図面を見ながら感じたことなのですけれども、１階のほうが、これは玄関を出て、私道のほうが出入り口になっているということなのかなと読み取れるのですけれども、それでいいのかどうかということと、１階に軽自動車が描かれていると思うのですけれども、どういった目的で使われるのか、その用途について教えていただきたいのと、あと２階に居室がある方は、外階段を通って。","respondent":"中山障害者福祉課長","answer":"軽自動車なのですけれども、福栄会が今回、西大井四丁目のこのグループホームの運営に当たっては、既に西大井つばさの家があり、またグループホーム森前があるということで、３つのグループホームを上手に、職員も移動しながらというのでしょうか。","voiceIndex":15,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"大体レイアウトがわかりました。安全対策とかそういう形で、入居される方に対しての、建物内もそうですけれども、周辺の事情とかも説明していただいて、事故など発生しないように気をつけていただければと思いますが、そのような会合というのでしょうか、定期的にやられるとか、そういうことは考えておられるのか教えてください。","respondent":"中山障害者福祉課長","answer":"そういった中で、さまざまな入居者に対する指導といいますか、近隣との関係の持ち方ですとか、そういったことは今でもグループホームでは定例的に打ち合わせをやったりはしておりますので、そういった中で、ここに入る方たちが地域の方たちと上手にご近所づき合いできるように。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤副委員長","kind":"質問","question":"３点お伺いします。３点目として、今回は重度の方を重点にということでしたけれども、知的障害者のご家族の方々から伺うのですが、すぐこうしたグループホームに入居するというのは難しく、体験などステップを踏んでいかないと、なかなか入居は難しいという悩みが出されておりますけれども、そうした悩みに対しての区としての何か手だてといいますか、どのように考えているのか、以上３点お伺いします。","respondent":"中山障害者福祉課長","answer":"やはり急に生活環境が変わるというのはなかなかに難しい方もいらっしゃると思いますので、そういったところも活用しながらイメージをつくような形を通じて、安心して次のステップに入れるように、そこは気をかけていきたいと考えております。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"猫の不妊・去勢手術費助成事業の実施状況","agenda":"猫の不妊・去勢手術費助成事業の実施状況","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"伺いたいことは、先ほど説明の中に、野良猫を捕らえるとおっしゃっていたと思うのですが、どのように野良猫と判断して捕らえるのかというのと、現在は区内１１町会認定とあるのですが、ほかの町会はどうなっているのかという現状を教えてください。","respondent":"井浦生活衛生課長","answer":"ちなみに平成２８年度につきましては、１３地区全ての全域につきまして、各町会長の会議でこの事業の説明をしたところです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"（３）のモデル事業ですけれども、モデル事業をすることによって、認定前の地域猫がすごく減少して、地域としてもとても、猫にとってもいいのかなと思うのですけれども、このモデル事業というのは、もっとこれからどんどん増やしていく、地域から申請があればどんどん受け付けて、モデル事業ということになっていますけれども、どんどん受け入れて、これを拡大していくという考えなのでしょうか。","respondent":"井浦生活衛生課長","answer":"１人ではなかなか実施することが難しいという事業ですので、協力していただく方を確保するということと、先ほど申しました負担額、餌代もありますし、さまざまな金銭的な負担もありますので、町会でご協力いただく、あるいは募金を募るという形で運営されてありますので。","voiceIndex":27,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"町会長がいいですよということで、多分ここの地域という地域も指定されて、そこで何頭ということで申請書を出して、許可されるというところだと思うのですけれども、そうしますと、区としてはそこのところを責任持ってやってくれる人がいれば、どんどんモデル地区、モデル事業を増やして、地域猫とする活動をどんどん拡大していきたいという考えでやっていられるのかというところをお聞かせください。","respondent":"井浦生活衛生課長","answer":"飼い主のいない猫の頭数は、４００頭という形で規模が大きくなってありますので、こちらの数字がモデル地区の数字に移行していけば、かなり地域猫の減少と、不幸な猫の減少ということで、動物愛護にもつながると考えているところです。","voiceIndex":29,"id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"（３）のモデル事業の助成の金額が、メスの場合は１万８,０００円でオスが１万円ということなので、それでワクチンが７,０００円なので、例えばメスの場合は、プラスワクチンもやる場合には２万５,０００円出るということでいいのかということと、それから裏面のほうで、４で事業費の（３）のモデル事業助成については、平成２７年度決算なのですけれども。","respondent":"井浦生活衛生課長","answer":"２点目の平成２８年度のモデル事業の助成額の増額につきましてもご指摘のとおりでございまして、かなりモデル地区としての取り組みが猫の減少に資するというところがありますので、拡大をし、そして持ち出しの費用負担を減少させるという観点から。","voiceIndex":31,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"そういう方が必ずしもその町会に住んでいるわけではないのですが、そういうふうにやりたいけれども担い手がいないというときに、うまく区でマッチング的なこととか、そういうのはできる場合とできない場合があるでしょうけれども、やっていらっしゃるのですか。","respondent":"井浦生活衛生課長","answer":"そのために品川区としては、年に五、六回、ベテランの担い手の方、あるいは獣医師の先生を講師に相談会を開催してございまして、日常的に電話窓口でご相談をお受けする中で、このような会をご紹介しまして、成功している事例での手法、お金の募り方、チラシ、アンケートの実施等。","voiceIndex":33,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"確認","question":"それで、グループの方などは自分たちでそういうジャンパーなどをつくって、誤解されないでやっているのだけれども、個人の方はなかなかそうもいかないし、今後ご希望があるかどうかというのも確認してもらいたいのですけれども、もしそういう希望があれば、区のほうで、担い手の方が安全で活動できるような統一したシンボル的なものとか、区の許可というか。","respondent":"井浦生活衛生課長","answer":"私どもとしましても、区としての腕章ですとか、たすき、あるいは会員証のようなものを工夫できないかということで検討してございまして、担い手の方の個人の方、グループの方のご意見をお聞きしまして、もし年度内にできるものであれば。","voiceIndex":35,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このモデル事業なのですけれども、猫の餌やりの場所が公園内だとか区道とかはだめだということで、私道だったり、自分の家の敷地だったりということでないとできないというところで、結構、地域猫がいる場所が公園で、その中で飼っていて、餌をやるにもすごく注意をしながら、毎日同じ場所できれいに片づけて、１０分間ぐらいで終わってしまうということなのですけれども、そういうふうに餌やりを。","respondent":"井浦生活衛生課長","answer":"これは個々の公園の利用調整という中で公園課として受けとめて、支援してくださっているです。都立公園につきましても、同様の協力や支援をしているところがあるということを聞いてあります。","voiceIndex":37,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も相談を受けた方は、朝の６時ぐらい、誰もいないところで、１０分間ぐらいで、新聞紙を広げて全部周りに散らからないようにして、それできれいに片づけて、排せつ物も全部きれいに公園の中もお掃除をしてということでやっているのだけれども、なかなか公園の中というのが認められないということで、ちょっと外れたところの私道で許可を得て。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-03","title":"健康大学しながわの状況","agenda":"健康大学しながわの状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"健康の問題というのは区民の皆さんの中でも大変関心の高いことだと思うのですけれども、この健康大学で、１つは、健康チャレンジコースは民間に委託して、基礎編、運動編、ワンデー健康づくり講座ということで、健康づくり講座は大学と連携ということなのですけれども、基礎編と運動編の民間委託はどこにされているのかということを、１つお聞かせいただきたいのと、この健康大学をすることによって。","respondent":"榎本荏原保健センター所長","answer":"健康づくりの推進委員との関係ですが、健康大学しながわの卒業生の方の中にも、健康づくり推進委員をされている方もいらっしゃいますので、そういったところでも関係ができておりますのと、それから、ふれあい健康塾を実施しておりますが。","voiceIndex":44,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういう方が受講されて担い手になっていくのか、３０代、４０代となると子育て世代だったりとか、仕事をしていたりとかということになると思うのですけれども、そういうところで、どういう人を担い手として、区としては育てていこうと考えられているのか、そしてまた、こういうところに応募されている方がどういう方なのかということについてもお聞かせいただけたらと思います。","respondent":"榎本荏原保健センター所長","answer":"集まった方を見ておりましても、健康に対して非常に関心がありまして、講習を受けた後でも積極的に質問をしたりとか、学ぶ姿勢が非常に強くていらっしゃいますので、そういった方々を少しずつ育ててというのでしょうか、地域の中で核となってやっていく。","voiceIndex":46,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"卒業生による地域健康づくり活動グループというのが６グループあるとご説明いただいて、ここに書いてあるのですけれども、それで平成２７年度は２８回、１,１３８名の区民に健康教育を実施していただいたということなのですが、どういった場でそういう実施をされるのかということと、それから、このグループの方たちは、日ごろはご自分たちでそれぞれの、お口の体操だったらお口の体操とか、紙芝居とか。","respondent":"榎本荏原保健センター所長","answer":"ふれあい健康塾でも幾つかの地域で呼ばれて行っております。ほっと・サロンでも実施しております。それから、ゆうゆうプラザ、多目的のお祭りなどにも伺って、行っているです。そのほかにも、ご連絡が入って依頼があったところには伺っているという状況です。","voiceIndex":48,"id":"exchange-018"},{"speaker":"安藤副委員長","kind":"質問","question":"公開講座のところでお伺いしたいのですけれども、いろいろ健康に関する説というのは、どんどん目まぐるしく変わっていくような印象もありますけれども、公開講座はテーマの選び方といいますか、区としてはどのような基準といいますか考え方で、テーマを選んでおられるのかなというのが１点と、もしわかればでいいのですが、直近の６月と９月と１２月のテーマがわかれば教えてください。","respondent":"榎本荏原保健センター所長","answer":"３保健センターにそれぞれの健康大学しながわの担当者がおりまして、集まって会議をする場があります。そういったところで今の最新のトピックスでありますとか、どんな健康のテーマで講演会をしたほうがいいかということを、そこでテーマを出し合って検討するというのもあります。","voiceIndex":52,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアパスですけれども、ケアパスは今年の１２月ぐらいにつくられるというふうな、前は予定だったかなと思うのですけれども、できたら、この厚生委員会にもご報告いただけると思うのですが、ご報告いただける時期はいつぐらいになるかを教えていただきたいと思います。とりあえずそんなところで、また後で続けて伺います。","respondent":"永尾高齢者福祉課長","answer":"そのサポート医よりもさらに難しいことについて連携支援をお願いしたいということであれば、地域連携型認知症疾患医療センターとして、東京都から昨年の９月に指定されている荏原中延クリニックの酒井医師が受けることになっております。","voiceIndex":58,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認知症初期集中支援チームというところなのですけれども、これは平成２８年度からはどこの自治体も設置が義務づけられることになっているということなのですが、私たちが今回厚生委員会で視察に行った敦賀市というところで、この認知症の初期集中支援をモデルでずっとされているところの視察をしてきたのですけれども、専門のドクターや保健師などが２人チームで訪問をして。","respondent":"永尾高齢者福祉課長","answer":"それで、２チームということですと、当然品川区は人口がずっと多いので、なかなか難しいかと思いますので、どのぐらいの症状の人までが、このチームで見るかとか、どのぐらいのエリアでやるのかとか、そういうのもこれからこのモデル事業、今モデルケースで２件やっていますので。","voiceIndex":60,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この問題でも、今回学校も８回されているということなので、ここが小学校、中学校、どういう学校に行かれたのかというのも教えていただきたいのですけれども、敦賀市でも小学校の子どもたちに保健師たちが行って、サポーター養成ではないですけれども、認知症とはというところを、ほとんどの学校でそういうことをされているという報告をしていただいたのですけれども。","respondent":"永尾高齢者福祉課長","answer":"警察の件ですけれども、警察は昨年度に全部の警察の署員についてのサポーター養成研修が終了しておりますので、今年度は予定はございません。","voiceIndex":62,"id":"exchange-022"},{"speaker":"渡辺委員","kind":"質問","question":"聞いて終わるのではなく次のステップ、それは段階があっていいと思うのです。先ほどお話があったように、カフェの取り組みだとかは上級クラスだとしても、ほんのちょっと携われるような次のステップというか、そんな事例が具体的にメニューにあると、受講者の方も、これだったら私もできるなとか、そういう仕組みづくりを具現化していったらどうかなと思うのですが、その辺の考え方を教えてください。","respondent":"永尾高齢者福祉課長","answer":"実働隊の目標というところになりますけれども、なかなか人数でやるのは難しいかと思っておりまして、まず今の段階としては認知症について、認知症の方が普通に地域の中に歩いていても、違和感なく普通に対応し、困っていればお声かけしたり、助けてあげたり。","voiceIndex":64,"id":"exchange-023"},{"speaker":"渡辺委員","kind":"質問","question":"まだ道半ばというか、１０年間のスパンの中で、いろいろなそれこそチャレンジで進められるべきだと思っています。もう１点、認知症に関するアンケート実施について、今この回収率とか、対象者数の数字があります。今分析中となっていますが、今後のこの辺の情報的なものというのでしょうか、まとめの時期だとか、大まかなスケジュールの目安を教えていただければと思います。","respondent":"永尾高齢者福祉課長","answer":"ですので、かなり関心があるかなという印象を受けております。アンケートの結果ですけれども、できれば今年度中の委員会で報告をしたいと考えております。","voiceIndex":66,"id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"真ん中あたりの徘徊高齢者探索システム（ＧＰＳ）ですけれども、さきほどご説明がありましたがちょうど９月末で２０件が登録されていると。その中で実際に徘徊されてしまって、ＧＰＳを使って見つかったというか、そういうケースが何件かあったかどうかというのを教えてください。","respondent":"永尾高齢者福祉課長","answer":"この２０件のうちではないのですけれども、今年の平成２８年７月末だと、利用者が１８人いらっしゃいました。そのうちオペレーターによる電話で検索をお願いした方が２８件、インターネットで接続をした方が８件という状況になっています。","voiceIndex":68,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"提案","question":"以前にうちの会派の議員が、本会議とかでもご提案したかもしれないのですけれども、太宰府市の例を通じて、こういう徘徊の方をまちで、多分この上にある高齢者見守りネットワークなど、こういう方たちが徘徊の方を探すような模擬訓練を、太宰府でたしかやっているというので視察をして、一回そういう訓練を品川でも考えてみたらどうかという提案をたしかしたと思うのですが、そういうことは今後。","respondent":"永尾高齢者福祉課長","answer":"今のところ品川区では、予定はないのですけれども、ただ、認知症の検討会議等をこれからも続ける予定ですので、その中で医療機関や、福祉関係のケアマネ等の意見も聞きながら、どういう方法でやるのが適切かということも検討していきたいと考えております。","voiceIndex":70,"id":"exchange-026"},{"speaker":"松永委員","kind":"確認","question":"もう一点が、徘徊による発見の仕組みづくりの運用の中で、アイロンシール、反射シールとキーホルダー、これは１セットでお渡ししているのかという確認と、「ハメパチタイプまたはキャラクタータイプ」というのがよくわからないのですが、キャラクターは多分、この横の絵のものなのか、もしこれでキーホルダーをつけるとしたら、どういった場所につけたほうがいいですよというような。","respondent":"永尾高齢者福祉課長","answer":"区の施設を使いたいということであれば、区でそちらも紹介しています。それと、アイロンシール、靴反射シール、キーホルダーですけれども、１セットでお渡ししております。","voiceIndex":72,"id":"exchange-027"},{"speaker":"安藤副委員長","kind":"質問","question":"ここに気軽に相談できるというワンストップ的な窓口というのは、ある程度明確になっていたほうが相談しやすいのではないかと思うのですけれども、ケアパスということもありますと、各段階でそれぞれ、ここですよというのはわかるのですが、まずはここに相談して、つないでいきますよといった窓口は明確になるのかどうかというのを、現状がどうなのかということとあわせて。","respondent":"永尾高齢者福祉課長","answer":"それで、ケアパスの中で、今検討しているのは、まずこれを見たときに、どういうところに行った方がいいのかというようなチャートを、今つくっているところです。","voiceIndex":74,"id":"exchange-028"},{"speaker":"安藤副委員長","kind":"意見","question":"まだまだ介護保険そのものとか、そういった仕組みもご存じない方もいらっしゃったりしますので、そうしたところが、最初にここに相談できるというところをわかるように工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう場所がないというのを、地域の方からも何人かから伺っていまして、もしも区として在宅支援センターでやるのであれば、在宅支援センターのところに３職種を配置していただきたいし、そこに３職種が配置できないのであれば、ぜひ、それはきちんとした形での窓口というのはつくる必要があるのではないかと思うのですけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"認知症のケアとなってきますと、なかなか難しいところがありまして、というのは、本当に多職種でチームで動かないと、なかなか対応が難しいところがあります。それを、この広い地域の中で、１つのところで何カ所もつくるというのは、かなり現実的には難しいかなと考えています。","voiceIndex":77,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、例えば認知症の初期集中支援を受けたいとかということで、希望すれば受けられるような仕組みがあるのかということと、私は在宅支援センターではなくて、在宅支援センターでも済む場合もあるのかもしれないのですけれども、品川の区の中にある地域包括の中ででも、きちんと認知症のことで相談をしたいというところでの窓口というのはつくるべきなのではないかなと思うのですけれども。","respondent":"永尾高齢者福祉課長","answer":"ですので、在宅介護支援センターというのはいろいろなサービスがありますけれども、診断を受ける場所とかサービスとか、そういうものを適切な場所に振り向けるという役割もありますので、最初から専門的なところだけ、例えば医療なら医療だけに聞いてしまうと。","voiceIndex":79,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域包括を１カ所しかつくっていないというのも、品川区独自なわけですけれども、そういう点でいえば、私は在宅支援センターのほうにもきちんと保健師の配置というところも検討していただきたいですし、そういうところできちんと相談に乗れる体制というところでは、ぜひ検討していただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":35810,"voices":85}},{"id":"h28-20161129-8","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"建設委員会","time":"午前１０時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"北品川五丁目第１地区市街地再開発組合施行による都市基盤整備工事","agenda":"北品川五丁目第１地区市街地再開発組合施行による都市基盤整備工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"「暫定」という名前になっておりますが、これはやはり暫定であって、今後どういうアプローチをされるのでしょうかというのが１点目と、２点目の、既存のエレベーターが移動されているのですが、現地を見てくればよかったのでしょうけれど、階段になっていて、ニューシティに行くときは、要は足の悪い方はどういう移動の仕方になるのでしょうか。","respondent":"稲田都市開発課長","answer":"目黒川デッキの今後です。現在までもいろいろと、再開発組合等々、大崎ニューシティ側にアプローチしてきたところです。この４月にも文書等を出してというところでございましたが、今の段階ではなかなか交渉にも応じてくれないという状況があります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"継続的に計画どおりにいけるような状況に修復していただきたいと考えています。それと、この新設エレベーターは遠くなるのですか。移設したところを見ると、ニューシティに行くとき遠くなってしまっているのかなという、それはないのでしょうか。案内など、わかるようにはなっていますか。わかりやすさというのはどうなっているのか、教えてください。","respondent":"稲田都市開発課長","answer":"案内におきましては、写真が小さくて申し訳ないのですが、1)の写真を見ていただきますと、エレベーターの左側に車いすの大きな表示等もしておりますので、私ども現場を確認した上では、目立たないというところはなかったと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この施行は市街地再開発組合でやっていると思いますが、費用的にはどのぐらいかかっているのでしょうか。１、２それぞれ、別々に教えてもらえれば。","respondent":"稲田都市開発課長","answer":"大雑把で目黒川デッキが１０億円、デッキ階段が４億円、Ｏ歩道橋の混雑緩和が７億円と聞いております。これはもう本当に大雑把な数字で、概略という具合でお聞き取りいただければと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これだけの負担が出ると、やり方によっては、今後の計画において、資金的に開発組合は大丈夫なのかというのが気になるので、その辺のご見解を教えてください。","respondent":"稲田都市開発課長","answer":"先ほど申しました金額の中で、目黒川デッキとＯ歩道橋の混雑緩和は当初から計画していたものです。今回、デッキ暫定階段はプラスアルファでかかった４億円ですが。再開発組合と協議していく中では、これがすごく負担を抱えているという状況ではなさそうです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっともう一回確認させてください。最初に予定していなかったのは、目黒川デッキのほうは最初予定していなかったと。そちらは最初から予定していたのでしたか。これは結局つなげられないから、代わりにやった部分というのはないのでしょうか。そこがちょっとわからないのですが。","respondent":"稲田都市開発課長","answer":"大変申し訳ございません、説明がちょっとうまくなくて。つなげなくて、新たにかかった部分が、目黒川デッキの暫定階段です。これが約４億円です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"開発全体からしたら４億円というのは大したことない金額かもしれないけれど、普通に考えると大変な金額だと自分などは思うのですが、これが、次につないでいく中で影響してこなければいいのだけども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"今の目黒川デッキ暫定階段のほうで確認ですけれど、一応、本工事のほうの接続は目指していくということで、暫定ということになっていますけれど、これは本格的な接続ができた場合にどういう扱いになるのでしょうか。取り壊してしまうということでしょうか、そういうことはないのでしょうか。","respondent":"稲田都市開発課長","answer":"この階段の将来つながったところにおきましては、どうするかという取扱いについてはまだ決めておりません。道路管理者と協議しながら、どうするかというところだと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"決めていないということは取り外しもあり得るということかと思うのですが、つけておくと、つけておいたで、取り外したほうがいい理由というのが何かあるのであれば教えていただけますでしょうか。","respondent":"稲田都市開発課長","answer":"この階段をどう捉えるかなのですが、とってつけた不要なものと考えれば、つながった暁には取らなければいけない。ところが、これは非常用の階段にもなるではないかというような話になれば、せっかくお金をかけてつくったので残しておこうかという考えもあります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、道路管理者と相談すると言うと、道路管理者は、区ではなくなるのですか。こういうケースではよく区に提供されますよね。天王洲の通路などもたしか、大きな金額ででき上がったのを区が管理していると思うのですけれど、今後、非常用の暫定階段はどこが管理するのか。","respondent":"稲田都市開発課長","answer":"これは、道路管理者の、区のものです。区のほうに引き継がれまして、区が基本的には管理する。ただ、維持管理上は管理組合が管理していくというものです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど費用のところ、１０億円、４億円、７億円で、２１億円かかっているということで、再開発組合の責任によるということなのですけれども、全て再開発組合が費用負担ということでいいのでしょうか。今回の件はなかなか大変な、こういった混雑解消とか暫定階段というのは、開発の中では今までなかったことなのだと思われているのか、その辺を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"このような、まちの中で混雑緩和工事をやらなければいけないなどというのが出てくるというところは、当然、今までの開発においてもやっているものでございまして、そこに入ってくる人口や、通る人たちの量等も考えて、道を広くしなければいけない。","voiceIndex":22,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"不具合なところ等々が直っていくということですけれども、こういったエレベーターを見ても、やはり車いすや障害のある方にとっては、歩行者優先で追いやられている感が、すごく感じますし、あと補助金も入っているということだったのですけれど、どこからどれぐらい、この工事に関しては入ったのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先ほどは全体的な話をしましたが、このＯ歩道橋の拡幅とかデッキの工事におきましては補助金は入っていないところです。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"品川区の環境に関する三計画の実績報告等","agenda":"品川区の環境に関する三計画の実績報告等","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"環境計画の重点プロジェクトについてなのですけれど、重点プロジェクト１で民間活力を活用した再生可能エネルギーの導入促進とありまして、区有施設に太陽光発電設備の設置を進めているということなのですけれども、太陽光発電以外の再生可能エネルギーの導入、例えば地中熱発電など、都市部でも効果が高いと思われる再生可能エネルギーがあると思うのですけれども。","respondent":"三ツ橋環境課長","answer":"しかしながら、来年策定する予定です環境計画においては、太陽光以外のものについても引き続き検討しながら取り組んでいきたいと思います。","voiceIndex":30,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ太陽光発電以外の再生可能エネルギーの導入も積極的に進めていっていただきたいと考えております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、平成２５年度、平成２２年度ということでいろいろ策定してやってはみたけれども、この中で大きく変わってきた。だから、そういうのは、やってはみたけれども、でも品川区の現状とは合わないから、少し違う方向に行こうではないかみたいなことも絶対あると思うので、今後変えていくための、こういう方向でというのが何かあれば教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"そのあたりを一番注視しながら、品川区としてどの程度の割合がいいのか、ＣＯ２の排出量にする目標がいいのか、それともエネルギー消費量がいいのか、そのあたりを検討しながら進めていこうと思うところが改訂のポイントです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"推進体制のところで、区民、事業者、区という形があって、それぞれ関係しながらということなのでしょうけれども、どうなのでしょう、区民の人たちの意識というのと事業者に対する意識。なので、そこら辺の工夫を、次のステップの中で、やはり意識づけ、動機づけというものを具体的なところに落とし込んでいってほしいと思いますが、それについての考えをお願いします。","respondent":"三ツ橋環境課長","answer":"区としてできることというのが、例えば今回もお話ししましたように、エコライフアイデアコンテストの中で、みんなどれだけ対応できるのか、皆さんがどういうことができるのか募集して、またそれを水平展開していくことも。","voiceIndex":35,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それともう一つですが、進捗管理チェックシートの中の真ん中の基本目標２の2)水辺に親しめる空間の整備・開放ということで、平成３３年度までに５カ所以上（新規）と書いてありますけれども、これも具体的に５カ所と書いてある場所、５カ所ということで今進めている場所を教えてください。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"そのあたりを踏まえながら、区としてできること、また民間事業者に任せることというものもありますので、このあたりを具体的に検討してまいりたいと考えています。委員ご指摘の、水辺に親しめる空間を５カ所以上、整備・開放するという目標に対しまして、我々、河川下水道課では平成２４年度から整備を進めております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問","question":"カーシェアリング、民間の会社にお願いするということですけれども、その民間の会社というのは、大手企業の例えばトヨタとか日産とか、そういったところと一緒にやっていくという考え方でよろしいのでしょうか。それと、水辺のことはわかりました。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"カーシェアリングにつきましては、駐車場、パーキングの業者がカーシェアリングを進めておりまして、そちらです。寺田倉庫の、西側の天王洲運河沿いがまだ開放されてございませんので、こちらを東品川海上公園とつなぐ形で整備できればと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"塚本委員","kind":"確認","question":"三計画の実績報告で、３番目の品川区地球温暖化防止対策実行計画（第三次）ですけれど、速報値で基準年比８.６％減を達成できたというところなのですが、品川区の排出について削減なのですけれども、区役所という、これは区役所１m2あたりということは、この本庁舎ということでいいのでしょうか。それとも、いわゆる品川区が持っている区有施設を言っているのかというところの確認をお願いします。","respondent":"三ツ橋環境課長","answer":"実行計画の対象の場所ですけれども、区役所だけではなく区役所の出先も含めて、区全体のことを指しております。次に総排出量ですが、電気がほとんどで、今こちらに書いておりますように電気が主なものですけれども、そのほかガスなどが含まれております。","voiceIndex":43,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"その基準年というのを何年にしているのかということを１つお伺いしたいのと、その上で、今回８.６％達成に至った大きな要因について教えてください。","respondent":"三ツ橋環境課長","answer":"達成できた理由といたしまして、しながわエコリンクを実行いたしておりまして、その中で削減目標、こちら前年度比１％ずつ削減はしております。その中で、やはり紙の削減の取組みですとか、また節電の取組みなどにつきまして実施しております。","voiceIndex":45,"id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"なかなかＣＯ２を減らすのは難しいエネルギー環境にある中で、このような形で進めていっていただいて非常にすばらしいと思いますので、今後ともぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"増えてしまった原因と、いろいろと節電とかエコトバとか、いろいろとイベントはやられて、そこにも多くの方が参加されているということなのですけれど、もっと広げなければいけないのだろうという思いでいるのですが、そのためには重点プロジェクトというのもありますけれども、さらに進めていくために、区としてはどういった姿勢で区民に訴えていくのかというのを伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"区が率先してＣＯ２の削減、またエネルギー対策に取り組まなければならないというのは非常に難しいものがありますけれども、高い目標を掲げ、また実効効果のある目標を掲げながら取り組まないといけないと考えています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"共産党の調査ですけれども、４年前の大崎第三地区のところでの業務棟１棟が出す排出量が１m2あたり年間ネットで１１トンということだったのです。それから大井第三地区全体で見ると、年間８,８８０トンのＣＯ２が排出されているということなのです。なので、まちづくりのあり方というのも、環境の面からも考えていかなくてはいけないのではないかと思うのですけれども、その辺はいかがでしょうか。","respondent":"三ツ橋環境課長、鈴木建築課長、稲田都市開発課長、藤田都市環境部長","answer":"そのような取組みをしながら、まちづくりというのは、古いものはやはり省エネ効果が高くないので。建物の側面で言いますと、法律的に建築物省エネ法というのが昨年度施行されまして。開発におきましては、開発等の機会を捉えた最先端の省エネルギー技術の導入とか。どうしても、やはり品川区としてコントロールのできない排出係数によって増えてしまっているというのが現状です。","voiceIndex":50,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"今おっしゃられた、基準年度より１８.７％減少ということですけれども、基準年度というのは、要は２０１３年、今、国が出している基準年でいいのでしょうかということと、今、パリ協定などもとても話題になっていますけれども、世界は１９９０年比で削減していこうということで各国が目標を出しているわけです。国が出してきているものを基本にして立てられている計画なのでしょうか。","respondent":"三ツ橋環境課長","answer":"今、委員ご指摘の国の基準年、また東京都の基準年がありますけれども、それらを比較しながら、一番いい基準年を見定め、またそれに対して目標を高く掲げるというように考えておりますので、実際、品川区として取り組むべきことを取り組んでいきたいと思います。","voiceIndex":55,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ごめんなさい、先ほど部長が言ったａのところの基準年というのは、平成２１年度ということなのですかね。平成１８年度。本当だ、書いてある。全世界で起こってくるというところでは、やはり日本がしっかりと、そして品川区が削減していくという役割は大きいと思っていますので、私たちもいろいろ勉強しながら、一緒にさらに削減していくように頑張っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"その下の景観「重点地区」の指定地区数なのですけれど、目標が平成３０年までに４地区ということで、あと２カ年ほどしかないのですけれども、具体的にどこを指定していくのかということが、現在わかっているところで教えていただけないでしょうか。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"景観地区というのは、ちょっと所管と調整していきながら、実際にこちらにつきましては、所管と調整しています。残りの１地区については、水辺であるとか、幾つかちょっと候補がありまして、現段階ではどうするかというところを検討しています。","voiceIndex":58,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"今おっしゃられた大崎、武蔵小山というのが、平成２５年度から平成２７年度のいずれかに入ってくるということですか。","respondent":"中村都市計画課長","answer":"今、実際に重点地区として積極的に活動を行っているのは旧東海道地区で、それ以外の地区については、今、策定が、大崎についてはこの６月に策定されたばかりですので。武蔵小山その他の水辺等のその他の地区についても、まだこれからのことです。","voiceIndex":63,"id":"exchange-026"}]},{"id":"topic-03","title":"しながわ中央公園（拡張部）の開園式","agenda":"しながわ中央公園（拡張部）の開園式","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"ヘリコプターを用いた自衛隊と区の連携訓練とありまして、また完成イメージ図でもヘリコプターが飛んでいる図があるのですけれども、実際にヘリコプターが飛んできて着陸するというような訓練が行われるのでしょうか。","respondent":"溝口公園課長","answer":"今現在、自衛隊と最終調整をしていますが、今現在のところでは、この完成イメージ図に描いてあるようなヘリコプターに現地に来ていただいて着陸して、そういったところでの訓練・イベントを開催できるよう予定しています。","voiceIndex":69,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"この開園式は、もちろん区民の方どなたでもいいのでしょうか。告知はどうされるのでしょうか。","respondent":"溝口公園課長","answer":"当委員会報告後に、地元の町会等にご説明に上がるとともに、１月１１日号の広報で、開園式、またイベントを開催することについての告知を行っていきたいと考えているものです。","voiceIndex":71,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう大分でき上がりまして、なかなかすばらしいと思っています。完成後の公園を見ていると、中小企業センターを外しているではないですか。そこも更地にするのではないかと、自分はうがった見方をするけれど、やはりこういう図面を出してきたときに、これだけ大きな広場になるのかというのがちょっと気になったのですけれども。","respondent":"溝口公園課長","answer":"今後につきましては、区民の方に誤解を与えないように、イメージ図といったものについてはしっかりつくってお知らせしていきたいと考えております。","voiceIndex":73,"id":"exchange-029"},{"speaker":"塚本委員","kind":"質問・要望","question":"それについて、どのようなことを今想定しているか、周知についてお伺いしたいのと、あと、くれぐれも区民の方々もここに、どうなのだろう、ヘリコプターの発着のときは、区民の方は普通に皆さん見学に来られるのですかね。いずれにしても、無事故でできるようにということで、重ね重ねお願いしたいと思いますけれど、周知についてだけご答弁いただければと思います。","respondent":"溝口公園課長","answer":"近隣の方への周知につきましては、当日、やはり音、または風等、予想されますので、しっかりと、この後、報告の後に一軒一軒回って、その説明に回りたいと考えております。","voiceIndex":75,"id":"exchange-030"}]},{"id":"topic-04","title":"舟運社会実験に伴う目黒川の橋梁ライトアップの実施","agenda":"舟運社会実験に伴う目黒川の橋梁ライトアップの実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ＬＥＤを使うので、あまり経費はかからないとは思うのですけれど、どのぐらいの予算を考えているのでしょうか、教えてください。","respondent":"和田河川下水道課長","answer":"こちらは設置費、それから照明が一部レンタルしていますからレンタル費、それから維持費等を含めまして、合計で７００万円ほどを予算として計上しています。","voiceIndex":81,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"これは、昭和橋とか、いろいろライトを選ばれたのでしょうが、こういうのにするというのは、何か要望があってですか。ご意見などいろいろ聞かれてこういうのにしたのか、その辺はいかがでしょうか。","respondent":"和田河川下水道課長","answer":"こちらですが、委託会社の中で、ライトアップのデザイナーを入れまして、橋梁一つ一つの形状とか、それから周りの雰囲気とどのように調和するかというようなことを考えて、この４基をこのように照らすということを考えたものです。","voiceIndex":83,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"７００万円ですから、７００万円の中にその経費が入っているのかと思うのですけれど、いろいろ工夫できるとは思うんです。それで、効果によってはもう少し予算をかけてもいいのかという部分もあるので、あと、人の出入り、結構、見学者が来ていただけるのであれば、それも大きな目玉になってくると思うので、予算化も含めていろいろ考えていただきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-033"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、ライトアップの時間帯に舟は通しているのでしょうか。","respondent":"和田河川下水道課長","answer":"現在、２つの舟運事業者が、今「目黒川みんなのイルミネーション」をしているところなのですけれども、これを１つの目玉として、るるコースをつくって遡上していると聞いています。","voiceIndex":86,"id":"exchange-034"}]},{"id":"topic-05","title":"本日は、震災対策に関することのうち、災害時の受援","agenda":"本日は、震災対策に関することのうち、災害時の受援","exchanges":[{"speaker":"西本委員","kind":"質問","question":"こういう形でまとめていただき、とてもありがたいと思いました。そこで早速、質問があるのですが、まず１つは、協定内容が、それぞれ同じものもあれば違うものがあるのですけれど、その違いはどこから来るのでしょうかということです。それと(4)ボランティアです。前々からいろいろ指摘されていると思うのです。区の考え方として、区の整理の仕方、これからの進め方について教えてください。","respondent":"古巻防災課長","answer":"訓練等も今後、社会福祉協議会と検討していますので、そういった中で問題点の洗い出しでありますとか、マニュアルの検証等を進めて、より具体的にかつ実行力のある計画というふうに定めていきたいと考えているところです。","voiceIndex":92,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"また近隣区においても、まだ何か協議の場があまりないような感じなので、これは誰が手を挙げればいいのですか、やろうよと。ただ単に協定を組んだだけであって、具体的な行動提起までしているのでしょうかというのを、ちょっとお聞きしたいと思います。何か具体的にあるのですか、社協との調整の仕方。考えていること、進めること、これからやろうとしていることなどがあったら教えてください。","respondent":"古巻防災課長","answer":"なので、場所は今、先ほど、輸送拠点のところでご説明させていただきましたけれども、そちらから避難所への物資の搬送については、一定ルールに従ってやるというような流れの整理をしてはいるところです。","voiceIndex":94,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"あらかじめ予測した形での、支援物資をどういうふうに備蓄していくかということも考えていけるのかと思うので、ぜひそういう考えのもとでやっていただきたいですし、それから支援していただけるところに対しましても、やはりそれにタイミングを合わせるような形で、これが必要です、あれが必要です、また区内の中での情報収集の構築、考えておられると思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問","question":"都立・私立学校との協定ということで、実際、区の指定されている避難所に避難される人もいる中で、都立と私立学校との協定ということで、つい先日、中延の朋優学院が品川区と協定を結んだということで、そこには備蓄倉庫も備えているということなのですが、文教大学付属高等学校、これは二、三年前ですか、協定を結んだと思うのですけれども。","respondent":"古巻防災課長","answer":"２点ご質問いただいております。","voiceIndex":97,"id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問","question":"燃料のことなのですけれど、全ての車両について常時一定量の燃料を維持するよう、給油の基本的なルールをということですから、この全ての車両に常時一定量の燃料ということは、満タン状態を全ての車両に対して維持していくようにこれからルールを定めるということの解釈でよろしいのでしょうか。","respondent":"古巻防災課長","answer":"実際に防災課の車にもシールで、半分以下になったら満タンにということで徹底していますので、そういった形のルールで、全ての車両について燃料が、発災時にも動けるように、きちんと給油しておくというようなルールになっております。","voiceIndex":99,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"幾つかお伺いしたいと思います。その辺の、フェーズという言い方をしていいのか、発災後の時間の経過とともに、受援の地域防災計画等での検討というのがされていくのだろうと思うのですが、時間経過についてのことでの考え方というのを、ひとつお伺いしたいと思います。","respondent":"古巻防災課長","answer":"一定の検討の考え方、枠組みは確かにあるのですけれど、受援に関しましても、当然そういった考え方をよりはっきりとさせていく。","voiceIndex":101,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"この情報収集・伝達体制というところの中に、もう一つ、もう入っているのかもしれませんけれども、適切に何が必要なのか、品川区として今どういうところに困っていて、こういう応援が必要なのだという、適切な要請の発信というのですか、そういうところもぜひ検討課題としては必要なのではないかということを思っているのですけれども、この中にもちろん入っているということであれば。","respondent":"古巻防災課長","answer":"ですので、どこからどういった形でということはありますけれども、きちんと正確な情報が迅速に発信できるような体制についても、こういった情報の流れというのでしょうか、流通というか、そういった中に含めて検討していく必要はあると考えております。","voiceIndex":103,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"全体的に言うとそんな感じになるのかと思うのですけれども、例えば自治体等と様々な協定を、ここに示していただいたとおり、全てで５２ですか、たくさんの自治体ともそういう提携をしている、協定を組んでいる、結んでいると。そういう情報通信のあり方というようなものを確保していく。そういうところが大事かと思うのですが、何か今そこについてお考えがあればお伺いしたいと思います。","respondent":"古巻防災課長","answer":"具体的な話というのは、今、現状だとなかなか難しいところはあるのですけれども、具体的にちょっと今お答えする材料がないのですが、そこは発信というところを十分に意識しながら、情報の流れの整理をしていきたいと考えております。","voiceIndex":105,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"それは相手が選ばないといけないところもあると思うので、普段から協定があるところについてはこういう形でと、それはメールなのかもしれないし電話なのかもしれないし、何か専用の無線を使うのかもしれませんしということをやっておくということと、もう一つは、広い意味では、広域に支援を要請する上で今言ったようなＳＮＳなどという手段もあるので、そういう手段。","respondent":"松代防災まちづくり部長","answer":"一方で、私どもは品川区の中での起こったことに対応するということと、広域的な観点で対応するということを、役割分担をしっかり持つことが重要だと考えています。","voiceIndex":108,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。今後の検討課題の(4)物流全般における民間物流業者の活用についてというところで、これはもう少し詳しくご説明いただきたいのですが、何かある種の業務を委託するというか、具体的にこういうことをお願いしたいのだみたいなイメージがあるのかどうか。あるいは、そういうことではないのかどうか。ご説明をもう少し詳しくいただければと思います。","respondent":"古巻防災課長","answer":"イメージしているところですけれども、こちらの３ページ目の３(4)のところ、物流全般における民間物流業者の活用についての内容ですけれども、まだ具体的に動きがあるということではないのですが、区としての考え方としましては、やはり様々な物流が。","voiceIndex":110,"id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"受援について、さらに具体化を進め、地域防災計画に反映させていくとあるのですけれど、この地域防災計画に新たな項として「受援」という項をつけるのか、避難所とか、いろいろな項の中に、どんどん受援の部分をつけ加えていくのかという、まだそこまではいっていないかもしれないのですけれど、もしそういうイメージがあったら教えていただきたいのと、あと、受援計画を立てる。","respondent":"古巻防災課長","answer":"地域防災計画の中への位置づけですけれど、これはまさに今検討しているところでございまして、どういった形になるのかというのを今お示しはできないところなのですけれども、今現在の形ですと、かなりいろいろなところへ分散して書かれているような形になっておりますので。","voiceIndex":112,"id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、どういう形で、区の各所管で連携しながらつくられていくのか、つくられていくまでというのが、もっと区民に声を聞くのかとか、議会の中でもっと議論できる場をつくるのかとか、そういうイメージはどうでしょうか。","respondent":"古巻防災課長","answer":"それに先立って当然、議会でご報告等もするというような形になろうかと思いますので、そういった過程でいろいろご意見を伺いながらよりよい形でまとめていければと思います。","voiceIndex":114,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。「受援」などという言葉も意識がなかったので、様々な課題を我々も捉えております。それで、１つ１つというよりも十分ご理解いただいていると思いますので、いい計画を立てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-047"},{"speaker":"木村副委員長","kind":"質問・要望","question":"(3)輸送体制の中に協力協定に基づく車両というのがあるのですけれども、ここではどのような車両のことを指してのことなのか、ちょっと教えていただきたいと思います。","respondent":"古巻防災課長","answer":"流通業者であります赤帽という業者がありますけれど、そちらからも車両の提供を受けるというような形で正式な協定が締結されてありますので、具体的にはそちらを指しているとご理解いただければと思います。","voiceIndex":117,"id":"exchange-048"},{"speaker":"木村副委員長","kind":"質問","question":"今、赤帽と言ったのはバイク便のことを言っているのですか。軽自動車、そうですか。例えば震災があったときに、道路というのが、車両が通行できるかどうかということを考えないといけないと思うのです。そういうところとの、民間との協定というか、そういう話し合いというものはどのようになっているのかお聞きしたいと思います。","respondent":"古巻防災課長","answer":"今ご指摘いただきましたバイク、それから自転車等の活用に関しての話し合いということですけれども、すみません、具体的には今、業者とそこまでの話はしていないと思うのですけれども、その辺は道路等の通行の問題が出てくるというのは想定できますので。","voiceIndex":119,"id":"exchange-049"},{"speaker":"木村副委員長","kind":"質問","question":"ぜひそれも早目に協定、話し合いをしていくことをお願いしたいと思います。それで、あとヘリコプターによる救援物資や人員を運んだりということを考えて、この中に、災害時の臨時離着場というのですか、候補地なり事案のところ、今、品川区のそばにもヘリポートをつくっていますけれども、臨時のところという、またそういう候補地というのは考えているのですか。","respondent":"古巻防災課長","answer":"当然、今後できますしながわ中央公園のヘリポートもこういった中に含めていくというような形で、そこが基点になっていこうかと思いますけれど、現状まだできておりませんので、まだこちらの計画には載せていません。今、現状の計画の中では５つ想定しています。","voiceIndex":121,"id":"exchange-050"},{"speaker":"木村副委員長","kind":"質問・要望","question":"その５カ所を、そういう意味では、こちらで考えているということで、何もコンクリートできちんとしたところでなければ着陸できないというわけではないと思います。ヘリコプターは、いざとなったときには、占有で使えるわけではないですよね。例えばどのような回数、どのような感じで使えるのか、それがわかれば教えてください。","respondent":"古巻防災課長、松代防災まちづくり部長","answer":"全体的には東京都に要請して、ローテーションといいましょうか、順繰りに回って対応していただくというような形になろうかと思います。そういうことで、東京都に要請いたしまして調整していただくというような形になろうかと思います。そういった意味で、その状況に応じて活動されると考えていますけれども、１つには、まず自衛隊のヘリ等の要請は、東京都を通じた自衛隊への要請のもと飛来して。","voiceIndex":123,"id":"exchange-051"},{"speaker":"木村副委員長","kind":"質問・要望","question":"こんなことはあまり考えたくはないのでしょうけれども、最悪の状態のことをまずは考えて、いろいろと計画を練っていくことが一番いいのではないかと考えています。これはまた要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-052"},{"speaker":"若林委員長","kind":"質問・要望","question":"では私のほうから。確認といいますか、参考に教えていただきたいのですが、１ページ目の相互協力協定一覧がございまして、協定締結日の中で、改正している協定が、例えば特別区が１回改正していて、東海道五十三次が２回改正していて、その２カ所ですか、改正をしている。","respondent":"古巻防災課長","answer":"改正ですけれども、現状ちょっと内容を把握しておりません。申し訳ございません。確認いたします。","voiceIndex":127,"id":"exchange-053"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"一般質問での南恵子議員の「八潮団地が子どもも高齢者もみんなが元気に暮らせるまちに」という質問で、「八潮のＵＲ住宅や住宅供給公社などの空き室を区が借り上げて、区営住宅のような低廉な家賃で子育て世帯が入居できるよう家賃助成を求めます」という質問で、区の答弁が「ＵＲ住宅では親と子世帯が近居した場合の家賃減額を行っている」と。そして、あと「公社住宅では倍率優遇制度を実施している」と。","respondent":"今井住宅課長","answer":"再質問等でも、やはり今後説明しますけれども、この八潮団地につきましては、都営や公社、ＵＲなどの、いわゆる公的住宅で構成されておりまして、分譲につきましても公社が分譲したものですので、その点も踏まえまして。","voiceIndex":132,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"昨日の今日で資料もつくっていただきありがとうございました。ですので、それ以外にＵＲや住宅供給公社というのは、そうはいっても１０万円を超えてくるというところでは、なかなか魅力を持って入ってくるというのは難しいのではないかということで、家賃助成を求めたわけです。そして、この近居割をされている方というのは把握はされていないでしょうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"八潮に限らず区としての総合戦略プランの中で、やはりバランスのよい年齢構成というのは、持続可能な自治体として大切なことだという認識もある一方で、実際には八潮も、広い家族構成のところにお孫さんが転居してきたなどという話も伺いますし、実際にこういう空き室が出て。","voiceIndex":135,"id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、ぜひ区として実態を見ていただきたいと思うのです。私も八潮の皆さんにお話を伺うと、空いているところは多いと伺うのです。","respondent":"今井住宅課長","answer":"一般質問でも申しましたとおり、区としても、第二回定例会でもご答弁申しましたとおり、八潮団地については今後の活性化も含め検討課題と考えておりまして、庁内ＰＴ等を含めて多角的な視点から八潮の課題については検討していく予定です。","voiceIndex":137,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"釣れていない、釣れないとおもしろくないという。ニジマスが入ると少しは違うのかと思うのですが、大体、これは１日何尾ぐらい、放流というか、それはどのぐらい、どういう形で、１日例えば何匹加えていくとか、やっていくのでしょうか。餌や道具などというのはどういう形になっているのでしょうか。","respondent":"溝口公園課長","answer":"ただ、今回、社会実験的にやる中ですから、どのぐらいの利用が見込まれるのかといったものも含めまして十分検証しながら、今後、来年度どうしていくのかというのを見定めていきたいと考えているものです。","voiceIndex":147,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"釣れなくてもおもしろくないし、釣れ過ぎてしまうと２匹しか持って帰れないので、すぐ終わってしまうというのがあるので、そこそこ加減で釣れる必要があると思うので、ちょっといろいろ考えていただきたい。近くにこういう施設があるというのは、とてもいいのではないかと思っていますので、その兼ね合いをぜひ、もう少し計っていただいて、皆さんが楽しめるように工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"この予算と、アンケートの結果を踏まえてからだと思うのですけれども、継続するとしたら、利用料金はどのぐらいになるのでしょうか。","respondent":"溝口公園課長","answer":"そう考えると、実費相当を考えると５００円ぐらいが妥当なところだとは思いますが、その辺も含めて今回アンケートをとりますので、そういった中で適正な金額、または利用する方が利用しやすい金額というのを見定めていきたいと考えているものです。","voiceIndex":150,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"早急な、１カ月から２カ月ぐらいの間のお金ということになるのですけれど、この特別会計の歳出に持っていく部分というのは、災害救助・災害復旧に関わる事業ということになるのですが、担当部署として、この辺はどの程度まで想定しているのか。例えば私ども自民党としても勉強した中で、非常食、食品系統をどちらで買うのか。歳出目的をもう少し教えてください。","respondent":"古巻防災課長","answer":"災害後直ちに使うものということでは、備蓄品というのはわかりやすい部分ですので、そういったところを入れる、入れないあたりを検討を進めている、詰めているところです。","voiceIndex":155,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ですから、変な言い方ですが、どちらも発災時に供えた備蓄ですけれども、その辺の仕切りがどうかと、はっきり決めていって、これから予算を組んでいく中で決めるのでしょうけれども、この辺は私どもとして疑問を持っているところがあります。当然、総務委員会で終わっていると思うのですが、こちらの部署として確認だけさせてもらおうと思ったので、その辺の今後の話があれば教えてください。","respondent":"古巻防災課長","answer":"今ご指摘いただいた点を含めまして、今後、いただいた意見を踏まえまして検討を詰めていきたいと考えております。予算の中でご提案しますので、よろしくお願いいたします。","voiceIndex":157,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"なので、もっと自由度のあるような使い方が必要になる部分があるのかどうなのか。具体的にイメージがつかないので、こういう基金、会計があるのはいいのですけれど、とてもすばらしいことだと思うのですが、ただ具体的に何に使うのですかというのがすぐに出ないので、何かちょっとでも具体的なイメージがあれば助かるのですけれども。","respondent":"古巻防災課長","answer":"イメージというようなお話なのですけれど、まさにちょっと今イメージを詰めているところなのですけれども、発災後、一日、二日ですぐにお金が必要になるかというと、支払い先も相当混乱していると思いますので、一日、二日というような短いスパンではなくて。","voiceIndex":159,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"特別会計という形をとるのも反対はしないし、いいことだと思うのですが、でも次、具体的になったときには、もっとこういうときにこういうのが必要なのですよというところまで、ぜひ準備していただきたいと思っていますので、今後よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":52933,"voices":164}},{"id":"h28-20161129-9","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"文教委員会","time":"午前１０時００分～午後 ４時３７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"小規模保育事業等における連携施設の設定","agenda":"小規模保育事業等における連携施設の設定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"表のところで連携施設が各園いろいろ書いてありますけれども、１園あるところから３園あるところ、４園あるところもありますね、幅があるのですが、これは基準とかそういったものがあるのでしょうか、伺いたいと思います。","respondent":"竹田保育課長","answer":"ただ、通常の転園と同じ選考となります。それから、幅があるというお話ですが、小規模保育事業においてもさまざま定員があり、また受け入れ先の認可園にも２歳と３歳の差分でさまざま数字が異なることから、連携施設の多い少ないがあるものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、できるだけ近隣の園と連携するということですけれども、特に基準とかというものはないということなのでしょうか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"こちらの連携園に基準があるのかということですが、先ほど申し上げた基本的な考え方に基づいて設定しておりますので、近隣の園というところが基本です。すみません、ちょっと説明が。お話しさせていただきたいのは、小規模保育園であると３歳になったら預けるところがなかったらどうするのだと、こういう不安を解消するために設定した仕組みです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"この連携施設は今回小規模のほうでの連携施設ということですけれども、認証保育園のほうもやはり２歳クラスまでしかいられないというところがありますので、そういった認証保育園での連携施設というのは今回国のほうで法律が変えられてこうなってきているというところがあると思うのですけれども、認証保育園のほうで何か実施するお考えがあるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"現在、国から連携施設の設定を求められているのは、小規模保育事業等です。このたび、それに従いまして決定いたしました。認証保育所につきましては、今後数の動向を見ながら検討していきたいと考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"周知のほうなのですけれども、１２月１日からホームページで周知していくということですけれども、この小規模保育園の場合、１２月１日以前に申請されたのが継続されて入園が決まるという方もいるのかなと思うのですけれども、そういった、既に申請してしまっている方にも周知をやっていっていただきたいと思うのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"毎年１２月１日付で新園の開設情報ならびにさまざまな情報を、お申し込みいただいている方皆さんにご通知差し上げております。今回は、その中に連携の設定についても載せているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"幾つかお伺いしたいと思うのです。そうすると、スケジュールで出ているのが、入園申し込み受け付けでということで、例えば複数の連携施設があって、そこに希望する方が多かった場合、その受け入れる保育園の３歳児のプラス枠が全て連携園で埋まるというようなこともあり得るということなのでしょうか。どういう形で調整をされるのでしょうか。","respondent":"竹田保育課長","answer":"小規模保育事業にも連携園にも定数枠というものがありますので、その定数枠で連携園については２歳と３歳分の差分を使って、小規模の定数を受け入れるという形です。希望が特定の園に集中した場合は利用調整します。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"利用調整をするというのはわかります。それで、２歳と３歳の定数の差分のところに、何と言ったらいいのですかね、優先的に入っていくような形になると思うのですけれども、この小規模の方の希望だけで２歳と３歳の定数差分が埋まってしまうような運用もされるのでしょうか。このスケジュールのままだとちょっと難しいと思うのですけれども、どうでしょうか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"この連携園で全部埋めるのかですが、可能性としてはあろうかと思いますけれども、具体的な運用についてはちょっと今後検討させていただきたいと考えています。実際に進めてしまうと、おっしゃるとおり認証保育園との差が生まれますので、幅広く設定したというのはそういう意味もありますので、可能な限り機会の均等が図れるようにしたいと思いますが、枠が何枠余っている。","voiceIndex":16,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"それからもう一点。保育内容の支援と代替保育の実施なのですが、これは公立の園については粛々とされていくと思うのですけれども、私立の園にも同じ内容を求めるというのは、これもまた何かそれなりに人の手当てとか必要ではないかと思うのですが、その辺はどうなっているのでしょう。その辺の相談を受けたり代替保育を実施したりする側の体制整備というのはどのようになっているのでしょうか。","respondent":"竹田保育課長","answer":"そもそも小規模保育施設には、区の独自加算で代替要員の費用が支給されておりますので、私立の認可保育園は代替保育は求めないというのが基本です。ただ、いろいろなケースが考えられますので、そういった場合は公立を中心に受け入れていくということを今考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あべ委員","kind":"確認","question":"(2)の保育内容の支援については、認定園が公立・私立とありますけれども、基本的には公立のほうで対応するというお考えということでよろしいでしょうか。","respondent":"竹田保育課長","answer":"家庭的保育事業については今までも急な病気等で近隣の公立園で受け入れたという実績もありますので、このようにしていく考えです。それから、相談、助言等ですが、こちらについては新しい制度ですので、今後協定書も結びますので、徐々に深めていきたいと考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはお願いです。今日出していただいた中で、２の連携の（３）のところの「代わっての保育提供」というのは、今までやられていた公立の保育園に、家庭的なところで困難なときに公立に連れて行って保育をするということでいいのか、ちょっとそこを確認させていただきたいのが１点と、３のところの(1)の1)の巡回指導という、現在行われているこの中身をちょっと教えてください。","respondent":"竹田保育課長","answer":"認証保育所につきましては、例えば来年ですけれども、卒園児２９４人を推定しておりまして、それで認可保育園に申し込む方はそのうち１５０人、来年３月の定員枠は２８０人ですので、全体で考えれば認証保育所の卒園児も区内で受け入れられる体制はできているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この連携園の表のところでは、困難な人というのは、先ほど伺った通常の選考になるということですか。これ以外のところで、うちはすごい困難なので、ここがいいというふうに希望した場合は通常の選考になるということでしょうか。そのことを１点、お伺いします。","respondent":"竹田保育課長","answer":"こちらの連携園以外をご希望なさっている方については、現在認可園にいる方が転園を希望するのと同じように選考になります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"何点か確認いたします。連携施設の中で保育ルームＣｌｏｖｅｒ西小山園のところが、ここに入っている清水台しか今決まっていないと思います。そうなった場合に、保証されないというのはちょっと通常の抽選で入るというのはどうかなと思うのですけれども、そこら辺は人数的にそれが確保できないというようなことなのでしょうか。もう少し教えていただきたいと思います。","respondent":"竹田保育課長","answer":"こちらの、まだ設定が決まっていない園につきましては、新規開設園の動向や区外転出者の数、引っ越しなどでの転園希望、あるいは３歳以外での転園希望、１、２歳のときに希望したり、あるいは認証ですと４歳、５歳になってから転園ということもありますので。","voiceIndex":27,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこはぜひ行く先がないというようなことがないようにご検討いただきたいのと、この施設はやはり国が求めているものということですけれども、認証においてもまたこれからの運用の中でしっかりと、品川区として一歩進んだ運用の仕方をぜひご検討いただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"数字は置いておいて、今、どうしましょうかというお話が幾つか出ているのですけれども、認証の方々についての扱いは国ではもちろん決めてこないわけですけれども、東京都のほうにどのような、何らかの方策について働きかけるというか、相談、協議するとかということについては何かあるのでしょうか。","respondent":"大澤待機児童対策担当課長、竹田保育課長","answer":"２歳と３歳の定員の枠の差ですけれども、新規開設につきましては、今できれば４人以上の差はつけてくださいとお願いしていまして、最低でも３人の差はつけていただくように新規開設については働きかけておりまして。東京都への申し入れですが、機会を捉えて適宜申し入れていきたいと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"どういうことを言ったらいいのでしょうか、すみません、具体的に。どのような方策がというところはなかなか難しくて余り思いつかないので。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"毎月２３区の課長会等で東京都の担当の方が説明にいらっしゃってお会いする場面があります。新規開設をして３歳児以降の枠を広げるということで今回も補正でかなり予算をつけていただきましたし、私がたまたまご提案したことが直接都知事の耳に入って。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-02","title":"を引き続き聴取いたします。 (2)八潮地区幼保一体施設の定員","agenda":"を引き続き聴取いたします。 (2)八潮地区幼保一体施設の定員","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"これは拝見すると平成３１年の４月から新しい幼保一体移設ができると０歳児は３人、３歳児は２名減るということなのですよね。それは結局遊戯室の広さを現状のままで確保するのでスペースがとれないということでよろしいのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"保護者、地元住民等の要望から、現状の遊戯室の広さを確保してほしいという要望がありましたので、遊戯室をつぶさないと限られたスペースになりまして、最大限入れましても０歳児、３歳児に関しては３名と２名の減になってしまいます。","voiceIndex":41,"id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、結局この保育園は現実として数が減ることになると思うのですけれども、ただ八潮というのは要するに人口が減っていますよね。そうすると、今現在八潮わかば幼稚園にしろ八潮南保育園にしろ、利用している方というのは八潮のエリア以外からも結局たくさん越境というか、わざわざ来て入園されている方というのは結構いるのですか。","respondent":"佐藤保育施設調整担当課長","answer":"八潮の保育園の在園者の住所の関係ですが、八潮地区に住んでいる方が約５３％、八潮以外の方が約４７％で、ほぼ半分半分の状況です。","voiceIndex":43,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、八潮が減った分、今の課長のご説明ですと、八潮北と西と中央の受け入れの弾力化を検討するということは、足りなくなった分はほかの近隣の保育園で吸収できるというふうに考えればいいのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"定員の弾力化の関係ですが、八潮については施設が比較的広く整備されていますので、人員配置等を行った上で１園当たり０歳児１から２名の受け入れは可能と考えております。八潮北・西・中央の大規模改修時に、状況によって定員の拡大等も検討したいと考えております。","voiceIndex":45,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、新しい幼保一体施設は、住民の希望で遊戯室の大きさに関しては現状のままとすると。それとあと、人数が減った分に関しては、ただ近隣から来ている方も多いので、近隣の保育園を弾力的に定員拡大することによって十分吸収できると。そうすると、とりあえず余り大きな利用者のご負担はない状態で新しい施設ができるというふうにお考えだと理解してよろしいでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"先ほどご説明させていただきました八潮地区内の保育園の定員の拡大を図っていければ、こういったことで八潮にお住まいの方、またそれ以外の方々の保育の利便性も高まると考えております。","voiceIndex":47,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"行き先がなくなってしまったということがないように、丁寧にご説明をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり保育園などにしていっていただきたいと思うのですけれども、これが幼保一体施設が統廃合ということになって八潮南のところがなくなってしまうということになると、サービスがその地域ではちょっと少なくなってしまうということになってしまうので、今のお考えを伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"八潮南保育園の園舎の利用に関しては、平成３３年度まで八潮北・西・中央保育園の改修で使いますので、その時点でまた活用については検討していきたいと考えております。","voiceIndex":53,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"今、この八潮わかば幼稚園の敷地・建物というのは幼稚園で使っていらっしゃるということなのですが、実際の在籍者数というのは今どれくらいですか。","respondent":"佐藤保育施設調整担当課長","answer":"八潮わかば幼稚園の在園者の状況なのですけれども、４月１日の時点で４歳児が２５名、５歳児が２８名です。","voiceIndex":55,"id":"exchange-021"},{"speaker":"あべ委員","kind":"確認","question":"もちろんスタッフの数も相当に増える中で、基準は当然あって計算をされているのでしょうけれども、保育士の事務室等々を含めてかなりこれまでと敷地の感覚といったらいいのですかね、１人当たりの面積というか、きついことになってくるかなと思うのですが、保育士、スタッフの事務室などを含めてかなり手狭になる部分もあるのではないかと思うのですが、何か増築なんかを図る部分はあるのでしたか。","respondent":"佐藤保育施設調整担当課長","answer":"増築は特にできないのですけれども、職員の休憩室とあと幼保一体施設ですので、地域の子育て支援施設ということで、倉庫の部分をつぶして一時相談室みたいなものをつくります。そういうのも全部入れて、あと施設の広さの基準等もクリアした上で、この定員です。","voiceIndex":57,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"それが１つとても残念だなと思っているのと、あと４の（１）のところの定員減の対応ということで、「八潮北、西、中央保育園の定員弾力化の拡大検討」ということなので、これはいつの時点からになるのでしょうか。私、この弾力化というのはちょっと余分に詰め込むというイメージがとても強いので、定員を増やすという形にならないのかどうか。","respondent":"佐藤保育施設調整担当課長、大澤待機児童対策担当課長","answer":"３点ご質問があったと思うのですけれども、１点目の定員が変わらないようにということは、以前に文教委員会でもご質問いただいたのですが、実施設計中ですのでどうなるかわかりませんという回答を私はさせていただいたと考えております。東大井と勝島につきましては、平成２９年に２園新規開設、また平成３０年に今区民公園が決まっておりますので、そちらのほうにも開設予定があります。平成３１年の開設について、今のところまだ未定という状況です。","voiceIndex":59,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４の（１）のところ、弾力化なのですが、品川区全体では定員の１１０％まで弾力化をしていて、八潮は９９.９％というので、その辺少しほかよりも緩やかだという感覚だと思うのですけれども、やはり弾力化って定員以上に入っているという意味で、東京都全体とか２３区を比べても品川の弾力化の率はすごく高いのですよね。決して１１０％をよしとしないでいただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"弾力化の関係ですが、繰り返しになってしまいますが、園の運営の安全面を重視して園運営が十分可能な範囲で行っておりますので、何も詰め込んでいるという認識はございません。待機児童の関係もあります。","voiceIndex":62,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"弾力化のところは、特に本当に安全面は当然です。そこの職員の方が一番よくわかっていらっしゃるので、園長先生だけではなく、働いている皆さんの意見をきちんと聞いていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけお尋ねするのですが、この幼保一体型の施設は、旧来品川区にある幼保連携並列型の形をとることになるのでしょうか。それが１つ。それからもう一つは、以前にもちょっと質問したときに、たしか前任の部長がお答えになったのは、幾つかの理由を挙げて、認定こども園については現状では変えて、進めていくつもりはないというようなお話を伺ったのですが、今後もその方針に変わりはないでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"保育士と先生は別々に今区は採用していますけれども、それを一体とした資格になりまして、５年間の経過措置はありますけれども、そのような課題については２３区全体で検討しておりますので、その辺の推移を見ていきたいと考えております。","voiceIndex":65,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今保育教諭の課題をお話しされたわけですが、私立のほうについて昨日かな、お話しになりましたけれども、進めてバックアップをしていっていただきたいのと、今の保育教諭の件については研究ということですが、ぜひほかの自治体とも協力して方策を考えていっていただきたいと思います。この点については別の機会にまたお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません、ちょっと先ほどの数字を確認させていただきたいのですけれども、今八潮以外から来られている方が４７％ということで、主にはやはり勝島、東大井の範囲なのでしょうか。南大井も入ってくるのですか。多く来られているエリアの中で、来年度、再来年度に新規開設する園の定員はどのくらい増えるのかというのをお伺いしたいのですけれども。","respondent":"佐藤保育施設調整担当課長、大澤待機児童対策担当課長","answer":"八潮の保育園に通っている方の八潮以外の住所の割合ですが、東大井で約１０％、東品川が７.７％、南大井が５.１％です。人数としては、東大井が４３名、東品川が３２名、南大井が２１名、あと大井と南品川が数名の状況です。平成２９年の勝島と東大井の定員増ですが、１３７名を予定しています。","voiceIndex":68,"id":"exchange-028"}]},{"id":"topic-03","title":"平成２９年度入学希望申請の状況","agenda":"平成２９年度入学希望申請の状況","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、この荏原平塚から、結局ここから逃げた人はどこに行くのかというと、これを見ると荏原第一中学校と、それから戸越台のほうが結構人数が多いので、そちらに流れているみたいなのですけれども、こういう全体の不人気校というのに関して教育委員会としてやはり何か取り組みとか精力的になされているのでしょうか。","respondent":"有馬学務課長","answer":"今年で言いますと、いわゆる義務教育学校の学区外進級数（ｄ）の欄の２１、これが要は今年でいうとそっくり抜けている。去年ベースでいくと、この２１と８を足すと２９ということですので、そういう意味で言えば、傾向としては同じというふうに考えています。","voiceIndex":75,"id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、教育委員会としては、これを学校の区割りの問題がメインでこういうアンバランスになっているというふうに考えていると理解してよろしいでしょうか。","respondent":"有馬学務課長","answer":"荏原平塚学園も学校説明会等を行って、できるだけということで努力はしていますけれども、荏原平塚学園だからというのでそのままでいいかということは、また今後検討していきたいと思いますけれども、一番のネックとなっているところは。","voiceIndex":77,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"希望申請数のところなのですけれども、小学校、義務教育学校も中学校も平成２７年度から自分のエリア外のところに希望する人の割合が減ってきていると思うのですが、この傾向をどのように認識をされているのかちょっとお伺いしたいと思います。","respondent":"有馬学務課長","answer":"もうちょっと過去を見ますと、平成２４年度は小学校で言えば３２.６％ありましたので、この間７.３％落ちてきているということで、これはでこぼこではなくてずっと徐々に下がってきているとまず認識をしております。","voiceIndex":79,"id":"exchange-031"},{"speaker":"新妻委員","kind":"質問","question":"これは逆にいい傾向であるという認識をされているということですかね。","respondent":"有馬学務課長","answer":"これは当然学校がそれぞれ競争していきながらということもありながら、そういう各学校が切磋琢磨しながら住民に地元の学校を選んでもらえるということはとてもいいことだと考えております。","voiceIndex":81,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"まちづくりとの関係で、人口が増えていて学校の対応をこれから見直していかなければいけないなという地域があるかどうか、それが１点と、あと中学校のほうなのですけれども、受け入れ枠よりも実際に予定者のところがかなり多くても抽選にならなくて済むところが幾つもあるのですが、その辺の考え方というか、大丈夫だよというところを教えてください。","respondent":"有馬学務課長","answer":"中学校のほうの、今の希望者数と受け入れ枠の差が大きいのに抽選になっていないということですけれども、これは例年の傾向ですが、３割程度が私立に抜けるというようなこともございまして、例年で言えばこの範囲の中でおさまっているということですので。","voiceIndex":83,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"今、３割ぐらい私立にということなのですけれども、私立を選択する傾向というのは余りこの間変わりないのでしょうか、推移として。","respondent":"有馬学務課長","answer":"この間、小学校のほうについては６％程度、中学校につきましても大体３０％程度というようなことで、大きな変更はありませんので、来年度についても大体大まかにいえばそのような数字で推移するものと考えています。","voiceIndex":85,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"近年の傾向として、住民基本台帳による子どもの数が受け入れ枠を大きく上回っている学校がかなり増えてきています。こういうのは、まさか外に出ていくことを希望されない方まで外に出ることはないと思うのですが、どのように対処されているのですか。","respondent":"有馬学務課長","answer":"今回の場合につきましては、またここも私立にある程度抜ける数字もありますので、希望される４５名についてはなかなか厳しいところがあろうかと思いますけれども、それ以外の区域内の児童についてはきちんと受け入れを、しっかりしていくということで。","voiceIndex":87,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"今後かなりぎりぎりなところが幾つか出てくるのではないかと思うのですけれども、その際はどういうふうに対応されるつもりでしょうか。","respondent":"有馬学務課長","answer":"そういった場合は、直前になってそういうことがないように、今年度で言えばもう既に来年度の予算のときに平成３０年度の予測を見ながら教室増に対応する工事を前年度に行っていくというようなことで対応をしていくというような形で。","voiceIndex":89,"id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"なので、役所があなたは学区外に行ってくださいというのはできないけれども、結局選択制という形をとって保護者の意思を尊重している手続のような感じではあるけれども、多過ぎるところから出ていってもらう仕組みとして機能しているように見えるのですが、ここまでぎりぎりの数字の中で運用されると、選択制そのものの性格が変わってきていると捉えたことはないのですか、教育委員会としては。","respondent":"有馬学務課長","answer":"老朽化しているところもありますし、そういったものとの兼ね合いでそれは推計のところを見ていかなければいけないと思っていますし、学校選択を今後どうしていくかということについては、そういう物理的なものもちょっと片隅に置きながら。","voiceIndex":91,"id":"exchange-037"},{"speaker":"あべ委員","kind":"意見","question":"ちょっと繰り返しになるかもしれませんが、学校選択制の議論をこれからしていくと思うのですけれども、多分この制度を今現実的に一番考えているのは区と教育委員会だと思うのですね。これがないと、多分相当より多くの教室数が必要になってくるという意味では、その辺を議論されるいろいろな方にご理解をいただくというか、前提としてそういったことも議論の中では必要なのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"確認","question":"つまり、１番が今これを見ていたら城南になっているので、今後そういった学校番号で運用していくように進められていくのでしょうか。義務教育学校というくくりができたので、そこはそういった仕組みになるのかなと思ったので、それが１つ。ご兄弟で待機となられた学校がどれだけあったかということの確認だけしたいと思います。","respondent":"有馬学務課長","answer":"その７校のうち５校につきましては全員待機です。全員待機の方が５校で２１名です。ほかの２校につきましては、１０人のうち半分の５名が待機ということですので、合計兄弟枠での待機は２６名となっています。","voiceIndex":94,"id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。兄弟枠はまた別の機会で。番号のほうは、すみません、去年の表と順番が違ったので。さっきちょっと言い忘れたのですけれども、すみません、１つだけ。昨年抽選にならなかった学校で、小学校のほうですが山中と浜川と小山台、品川学園ですか、今年度は抽選になったのですが、その辺についてどのような要因というか、もしありましたらお願いいたします。","respondent":"有馬学務課長","answer":"品川学園が３年ぶりに抽選になったということですが、外へ希望する人が５名減って希望する人が８名増えたというようなことで、その差をあらわすと１３名というような影響が出たというようなことで、このくらいの数でも抽選になるぐらい。","voiceIndex":96,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"意見","question":"数字的に１桁ぐらいの住基人口が増えたとしてもこうやって抽選になったり、もともとぎりぎりというかいっぱい入るまで地域の方が移動していたという認識でよろしいですね、ありがとうあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-041"}]},{"id":"topic-04","title":"平成２９年度品川区立学校教育職員採用候補者選考の結果","agenda":"平成２９年度品川区立学校教育職員採用候補者選考の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"もともと採用予定の人数とかというのは決まっていたのでしょうか。","respondent":"熊谷指導課長","answer":"採用予定人数は６名程度ということで考えておりました。","voiceIndex":103,"id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、一次選考、二次選考、さらに面接試験と３回の試験をくぐってきて、それでこの人はすばらしいだろうと思うような方を６名、定員ぎりぎりまで選んだら、結局１名辞退があったということですよね。たしか２年前も渋谷課長のときに全滅だったとかという話もあって、これは例えば補欠で繰り上がりだとか、何かもしも抜けた場合補充するような手立てとかというようなご検討はされているのでしょうか。","respondent":"熊谷指導課長","answer":"ただ、６名ということで、実際には１名辞退がございましたけれども、名簿登載者から１名繰り上げてとりたかったかと申しますと、そこまでではない、６名程度となっておりますので、今年度についてはこの５名でやっていきたいということで、今回は５名を採用したところです。","voiceIndex":105,"id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、たまたま今年東京都の試験に受かって辞退された方が１名いたみたいなのですけれども、当然それが２名とか３名とかもっと複数出る可能性もあるわけですよね。そうすると、例えば欠員が出た場合に、補充するとかというようなことをあらかじめ想定したお考えとかはないのでしょうか。それとも、そのときはまたそのときで減った人数で今年はこれでいきますということになるのか。","respondent":"熊谷指導課長","answer":"先ほどの名簿登載者１２名ですけれども、実際に名簿登載しておりますので、補欠繰り上げということも考えておりました。ただし、今年に関しては、特段５名で、繰り上げなくてもよいと判断いたしましたが、必要に応じて繰り上げるということももちろん想定しています。","voiceIndex":107,"id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"何か仕組みも少し変えたのだったと思うのですが、教えてください。それから、内定を辞退された方は都で採用が決まったということなのですが、こんなことを伺っていいのか、逆に辞退されなかったというか、採用予定の５人の方も多分この教員試験だけではなくていろいろな採用試験を受けられていると思うのですけれども、それでも区を選んだということなのか。その辺の状況を教えていただけばと思います。","respondent":"熊谷指導課長","answer":"それからもう一つですけれども、実はそうしたこともありまして、これまでは小学校の教員養成課程のある大学しかこちらからはご案内をしていなかったところもあるのですけれども、実際に小学校の教員養成課程がない大学にも１５校ほど人事係が回りまして。","voiceIndex":109,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさい。その中で、経験があって受験をして受かった方が何人くらいいらっしゃるのかお聞きしたいのと、あと、教員の方はすごく広い範囲から受験をされると思うのですが、今回はどんな傾向だったのか。区内の方がどのくらい合格者の中にいらっしゃるのかなということをお聞きしたいと思います。","respondent":"熊谷指導課長","answer":"現在１９名おりますけれども、経験があった方は１１名です。皆さんさまざま東京都のみならず、他県、私立での経験がございました。","voiceIndex":113,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"つまり、中学校社会だけとか中学校数学だけの方はとってないということですよね、合格していないという状況ですよね。もちろん両方持っているから合格させているということではないと思っていますけれども、受験生の身からするとそういった部分を気にされることもあるのではないかと思うのですが、その辺はいかがでしょうか。","respondent":"熊谷指導課長","answer":"中学校の保健体育２名だけが小学校免許を持っていないのですけれども、そのことで小学校免許を持っていないと受からないのではないかと将来の受験生が思うのでないかということですが、それにつきましても説明会等、あとは大学での説明等でそういったことはなく。","voiceIndex":115,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"１名の方が産休代替ということで、品川区の学校で実際に働かれているということで、４月からいわゆる即戦力というかそういう形になられる方だと思いますので、その点は大変よかった、それはもちろんいろいろな理由の中の１つなのでしょうけれども、いいと思いますので、そういった方がたくさん受験されることを期待したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-048"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"やはりほかの地区と比べると、予算的に考えるとなかなか品川区だけというわけにはいかないという状況かと思うのですが、これはどういうふうにこの先検討されていくのか、やはり都にも求めることは求めていかないといけないのかなと思うのですが、どういうふうに考えられて進められていくのか、教えてください。","respondent":"熊谷指導課長","answer":"平成３０年度までを目途に、中学校９校と義務教育学校６校を含めたいわゆる各中学校区に２名ずつ合計３０名を目途に計画的に採用していく予定で考えております。現段階では３０名が上限ということで、これからあと２年間ありますので、適正な採用を行っていきたいと考えています。","voiceIndex":118,"id":"exchange-049"},{"speaker":"沢田副委員長","kind":"質問","question":"平成３０年まででこの固有教員の制度の採用はこの先はとりあえずしないという形なのですか。","respondent":"熊谷指導課長","answer":"現在のところは平成３０年を目途にということで、これで一旦固有教員についてはこれ以上は採用しないということで考えております。","voiceIndex":120,"id":"exchange-050"},{"speaker":"沢田副委員長","kind":"質問","question":"そうすると、この先固有教員が今度どんどん定着していきますけれども、どんどん年齢を重ねられて、例えば役職、副校長になられている方もいらっしゃいましたが、校長になられたりとかしてきたときに、今度はやはり役職がついてくれば下の固有教員の方がいなくなっていきますが、またそのときはそのときで採用を考えていくということなのですか。そのときによってということですか。","respondent":"熊谷指導課長","answer":"平成３０年というのが目標で目途に考えておりますけれども、やはりそれぞれこれから副校長であったり主幹教諭であったりさまざまな職種になっていきますので、そういったことも含めて、あと将来的にはやはり退職ということもありますので。","voiceIndex":122,"id":"exchange-051"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"やっていること自体はいいことをやっているなと思っていますし、実際の事業を見せていただいて、例えば両親学級なんかも取り組んでやっていていいなと思うのですが、こういう表記の仕方でちょっとやはり引っかかるところがあるのですが、その辺は多分意識していると思うのですが、さらに一歩アンテナを立てて。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"そういう意味では、適地がございましたら今後もそういったいわゆる子どもが都会においてなかなか親しむことが難しい自然体験に近いようなものを子どもたちに与えていきたいと、そういった思いはありますので。住基台帳の中で親と１８歳以下の子のみの世帯というところだけで落とすと、３,９３０世帯というところなので、おおむね全体で３,０００世帯ぐらいはいるのだろうなというところと。","voiceIndex":130,"id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"子育て交流サロンについては、今後また増やしていくというお答えはなかった、これはこの３カ所で空白地帯対応ということで打ちどめということで理解してよろしいでしょうか。経済的な問題だけではないところというのは、やはり時間のところが大きいかな。この配慮というのはどのような形があり得ると現段階で検討されているのでしょうか。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"こうした施設における魅力創出を、特に適地があればその他の場所についても予算の範囲内で検討してまいりたいと考えております。経済的な部分と経済的な部分以外ということで、ご提案いただいたのですけれども、子どもの未来応援プロジェクトについては、ひとり親家庭云々ではなくて、経済的に大変な人たちも含めて、経済的に大変でなくても。","voiceIndex":133,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"それで金融系の資格を取って、それから生活保護を外して正社員として働き始めて、１年ではないな、２年ぐらいですかね。何かそういうような話も聞きました。ただ、それを支えるためには、今のように就労を進めるとかパートでもとにかく少しは働いてという指導だけではない選択肢が必要だと思っているのですが、行政としてはそういうことというのは標準的に対応が可能なのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"お子さんが小さいうちにひとり親になられた方というと、その状態で離婚されている方でご相談に見える方には、ＤＶであったりとか離婚のショックでお母さんもちょっと働ける状態にない方もいらっしゃるので。","voiceIndex":136,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ご質疑の中で、ひとり親家庭の方の把握が難しいという中でも、一応２,５００世帯ぐらいではないかと推計しているというお話だったのですけれども、児童育成手当受給者の調査で、やはりこれを受けていない方もいらっしゃるという考えでいいですか。漏れている方もいろいろ含めて２,５００世帯ぐらいになってくるということでいいのか、改めて確認させていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"転入したりで品川区内にいらっしゃると、窓口に来てひとり親家庭であれば所得を見させていただいてということでやっておりますので、児童育成手当をもらっていない人ももちろんいますが、その方は所得制限以上の方なので。","voiceIndex":138,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"やはりそういったところでしっかり支援をしていくということを今考えていらっしゃると思うのですけれども、今まだ検討中ということですが、現在の検討の中で出てきた課題があれば伺いたいと思います。そして、カテゴリーを分けて分科会で検討中ということなのですけれども、この分科会の中では今回出された４つのカテゴリーで分かれて検討されているということでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"分科会のカテゴリーについては、今日のカテゴリーは厚労省のひとり親施策のカテゴリーなのですけれども、貧困対策のカテゴリーも似ているのですけれども若干違いまして、経済的支援、学習支援、親の就労支援、居場所づくり、食事の提供というふうになっているので。","voiceIndex":140,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、５つのカテゴリーだということで、課題はこれからということで、そういった中でやはりこの間求めておりますのは就学援助をやはりこういったひとり親家庭の方が受けてやられていると思うのですけれども、この間もずっと求めてきましたけれども、４月より前に入学準備金、やはりこういった困窮されている方というのは大変だと思いますので、こういった支給を今後考えていかれるのか。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"就学援助の入学準備金の関係ですけれども、これは決算特別委員会でも申し上げましたが、現行の制度で申し上げますと、前年度の収入をもって認定していくということですので。奨学金についてですけれども、今の段階ですと、国のほうで大学に向けて３万円ずつという案が出ているかと思うのですが、それも正式に決定したわけではございませんし。","voiceIndex":142,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"奨学金のほうは国で今３万円で検討しているということですけれども、３万円で十分だと区で考えていらっしゃるのか、さらに増額等求めていく考えはあるのか伺いたいと思います。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"就学援助については、その財源は財調である程度補填されておりますけれども、財調そのものが性質的には一般財源ですので、そもそも一般財源を投入しているです。国の３万円というのも、そういう案が出ているというだけで決まっているわけではありませんし、今後国であるとか都で、東京都も今いろいろ考えて動いているところなので、国、都。","voiceIndex":145,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実施に向けて積極的にやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この施設にしても子どもがいらっしゃる家庭、子どもたちが使っているのであえて在宅とか在宅でないという分け方は今余り必要ないのではないかなとちょっと思ったのでそれが１点と、あと在宅子育てと書いてある下のところの児童センターの事業なのですが、サンデー子育てサポート事業、日曜日もやっているという意味では余りちょっと認識がないので、この事業を教えてほしいのと、あと。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"こういった６館の利用の定着を見ながら、ご指摘の点につきましては必要性については検討してまいりたいと考えています。国の動向といたしましては、４カ月に１回の支払いというと、まとめて入ったときには大きいのですけれども、４カ月間それをもたせるというのが、というところで、支給の頻度を増やそうというところで。","voiceIndex":149,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、生活保護ではなくて仕事を続けていく中で頑張っていきたいのだけれども、こういう事例に対して援助が少ないですよねというお話をたびたび伺っているので、ぜひ子育て世代のところの応援をしていく手当の充実を頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-061"},{"speaker":"新妻委員","kind":"質問・要望","question":"子育て家庭支援についてから伺いたいと思います。このようにまとめていただいて、こんなに事業をやっているのだなということを改めて確認をさせていただきました。例えば、子育てをされている世代のお父さん、お母さんが子育てに悩んだときにまずどこに相談をするのかというのは、どこでまず確認ができるのでしょうか。","respondent":"高山子ども育成課長","answer":"区内大学の連携という点につきましては、これは産後ケア事業の中で区内の保健医療大学という、東五反田にありますＮＴＴ東日本関東病院の前にあります医療系の大学の協力を得て、日帰り型の産後ケア事業について実施していると伺っております。","voiceIndex":153,"id":"exchange-062"},{"speaker":"新妻委員","kind":"質問・要望","question":"さまざま窓口はあると思っていますし、それも周知されているのだろうと思うのですけれども、本当に子育ての中でここというような、わかりやすい拠点といいますか、そういう何かあったらそこに電話したら全てのところにつながっていくのだというような、ワンストップで対応できるような窓口という、わかりやすい場があるといいなということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-063"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、ひとり親の調査のほうも大変貴重な調査で、すごくわかりやすいですが、先ほどのプロジェクトの中で、今ちょっとご説明があった課長方ではなく、学校のほうからこの調査を見たときにどのような課題があるかというところが教育委員会のほうでどういうふうに感じたかという点を伺って、ソーシャルワーカーとかカウンセラーとか就学援助は教育委員会としての課題とここに出ているのですが。","respondent":"高山子ども育成課長、有馬学務課長","answer":"一方で、児童センターは築４０年を超える建築物も増えて、エレベーターを保有しないセンターもありますので、そういった施設の更新は待ったなしですので。これから、これをもとにプロジェクトの中でクロス集計みたいなものを行っていくということで、教育委員会としてはそれをもって全体でもう一度確認作業を行うということですので。","voiceIndex":156,"id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。児童センターについては、役割というのは、大きな話ですみません、ネウボラを導入されたということですので、児童センターの役割はますます重要になると思いますので、また検討を進めていっていただきたいと思います。教育委員会のほうのプロジェクトの中でぜひ教育委員会としてのお立場で改善策というかそういうものを積極的にお話ししていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"大学とか産婦人科の中でつながってきているのですけれども、小児科とはつながらないのですか。さっきの話というのは、まさしく今の小児科でやっていることと同じことなので、要するに小児科あるいは小児科医会とつながるとか、コンタクトは全然ないのだけれども、そういう仕組みというのはあるのでしょうか。","respondent":"高山子ども育成課長","answer":"ネウボラネットワーク事業の組織図の中には、庁内的な連携もそうなのですが、対外的には例えばＮＰＯ法人であるとか、あるいは社会福祉協議会であるとか、もちろん医療機関も含めてなのですけれども。","voiceIndex":160,"id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはさっき言いました。経済的支援だけではなくて、例えば家事ヘルプですとかそういった子育て支援や家事の支援という家まわりのほうというのは逆に父子家庭は母子家庭以上になかなかサービスの選択肢がないと聞きますので、そこを父子家庭に対するサービスということではどのようなことを区としては考えているか、どのようなサービス、選択肢があるのか、ここも教えていただきたいと思います。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長、齋藤子ども未来部長","answer":"子育てに関する事業を全て区で直接的に実施するということでもなく、お話の中にありました例えば北品川を中心としたママかつでありますとか。養育費の件なのですけれども、せんだっての一般質問でもお答えさせていただいたのですけれども。今うちでできるのは、例えば債務名義とは何だ、取るためにどうするのだ、これがあったら払わなかったら強制の履行ができるとかという相談。","voiceIndex":162,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ力を入れていただきたいのと、国の動向を見るだけではなくて、やはり声を都に対して、国に対していろいろな機会で上げていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-068"},{"speaker":"沢田副委員長","kind":"質問","question":"在宅で子育てをしている家庭には幾らかお金を支給するとか、保育園に預けない、そういう家庭に、そのかわりに何かこういうオアシスルームとか家事支援とか、何ていうのですかね、こういった育児支援とか、そういったことに対しても補助をしていけば、どうしても仕事をせざるを得なくて働いている方たちに対してよりも、そういったことをしていく。","respondent":"齋藤子ども未来部長","answer":"やはりあるところまでは母親が育てるべきだという意識があって、先ほどあべ委員からご指摘いただきましたけれどもこういう書き方になっている部分。","voiceIndex":167,"id":"exchange-069"},{"speaker":"沢田副委員長","kind":"質問","question":"だから、やはりもう少し多様な、保育園に税を投入してそれだけ子育てサービスを充実させるということもすごく重要だと思いますけれども、もし家で育てていきたいと思っている方でもそれと同じくらいの財政的な支援をしても、決して財政的に予算的に厳しくなるとかではなく、保育園にかかっている分がそっちに行くわけですから、そういうのが選択の中にあってもいいのではないかなと思っていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-070"}]},{"id":"topic-06","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"保護者に対する謝罪についての答弁が曖昧でしたので、改めて何についての謝罪なのか伺いたいと思います。次に、３番目の看護師配置のところです。改めて、看護師配置できない民間委託は問題ではないのか伺います。区も調査しているということで、この間の経過と課題、抜本的な改善策の提案はあるべきだと思います。報告書の提出はしないとの答弁でしたけれども、提出しない理由を伺います。","respondent":"竹田保育課長","answer":"ひろまち保育園に関する謝罪については、８月２３日、１１月１１日、１２日の計３回保護者説明会において補助金を不正流用するなどの事業者を選んだこと、および事業者を変更することになったことに対しておわびをお伝えするとともに。","voiceIndex":174,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"看護師配置のところでは、年間で精算していくので問題ではないという話でしたけれども、配置できないことについて伺っております。現在も配置されていないと思います。精算すればいいということなのか伺いたいと思います。報告書の提出については、調査中ということなので、そうすると調査し終わった後に報告書を提出していただけるということでしょうか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"引き続き配置を求めてまいります。それから、第三者委員会の件につきましては、調査報告の内容を議会、保護者の方にご説明しておりまして、区としては報告書を提出する考えはございません。１つ目の債務不履行で看護師がついていないのは確かによくありません。うちの保育課長からも私からも代表代行の方には何度も申し入れをしておりますが、なかなかうまくいっておりません。","voiceIndex":178,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"調査報告書のほうなのですけれども、調査が終わったら報告していただけるということでしたが、この間口頭での説明はありましたが、文書の提出がなかったのですね。やはり今回の問題は保育園の事業者がかわる、保育士がかわるという重大事態ですから、文書にまとめて提出するべきだと思います。重大事態とは思っていないので提出しないということなのでしょうか。伺います。","respondent":"竹田保育課長","answer":"第三者委員会の件ですが、この件についてはしっかり調査してご報告したいと考えております。前回の委員会の報告の中でも、ご説明した資料に一定程度入れさせていただいたものです。","voiceIndex":181,"id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"報告書のところでは、前回報告したというお話ですけれども、それは兵庫県の報告書にはこうありましたという報告だったと思うのですね。やはり区としての調査をどうやっています、どうしてこういったことが起きたのかということをまとめるべきだと思うのですけれども、いかがでしょうかということです。","respondent":"齋藤子ども未来部長","answer":"ということで、何が言いたいかというと、報告書自体は法に基づいてできるものと、委託契約に基づいてできることは違いがあるので、ご理解いただければと考えています。","voiceIndex":183,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、報告書の件は今の品川区の契約等のやり方では、法的には報告書はできないということですか。","respondent":"齋藤子ども未来部長","answer":"２つあって、まず、民間だから看護師が入ってできないのではなくて、何か開き直った言い方で申しわけないのですけれども、たまたま配置もできないような民間の社会福祉法人を選んでしまったのがうちの落ち度なのです。","voiceIndex":185,"id":"exchange-075"},{"speaker":"あべ委員","kind":"質問","question":"調査技術というのは、やはり一定必要だと思うのですが、そういったもの、例えば外部の力を活用して今調査技術の専門家みたいなのもいるらしいのですけれども、そういったものも活用しながら、何か不正が疑われることについて、何かはチェックする仕組みがないと、領収書さえあればいいということでは行政として困るのではないかと思うのですけれども、どのようにお考えでしょうか。","respondent":"齋藤子ども未来部長","answer":"今日この場ではお話しできませんけれども、いろいろ調べもしている部分がありますので、それは追ってご説明させていただければと思います。","voiceIndex":187,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問の繰り返しになるかならないかは、質問にきちんと答えてくださっているかどうかにかかっていて、やはり不十分であるので足りませんよという意味でフォローさせていただいているので、その点はご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところを答えていただきたいと思います。質問の３のところは、地域年齢ごとの認可保育園の需要調査を求めています。質問５のところは、認可外保育施設の支援について、総合的な待機児童対策の中で検討いたしますということで、総合的な対策とはちょっと大ざっぱだったので、この支援が前に進むのかどうか、再度お尋ねをしたいと思って質問に入れました。","respondent":"大澤待機児童対策担当課長","answer":"検査指導の強化につきましては、東京都と連携して適切な指導検査をしてまいります。ほかの議員からも決算特別委員会の総括質疑の際にご質問がありましたが、保護者の負担のあり方については、今後別途検討してまいります。","voiceIndex":192,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちが、質問した趣旨は、「待機児童が解消しないのは、子どもを産む母親のせいですか、働く母親が増えるせいですか、伺います」となっているのですが、私たち、この質問の中にはそうではないでしょうという思いが込められているのですが、そこの、何ていうのですか、区がやはりそういった対応ができていないことへのお答えを求めたのですが、そこに全然触れなくて、区政が評価されていますというのでは。","respondent":"大澤待機児童対策担当課長","answer":"待機児童が解消されないというのは、何度も申し上げているとおり、計画上では推計上では解消できるほどの認可保育園の開設は平成２９年に予定しております。","voiceIndex":195,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後ですけれども、ご努力されているのは十分わかっています。でも、対策が間に合わないということについて、やはり間に合わせようと思うのであれば、やはり間に合っていない現状についての点検とか反省がない限り、次に行かないと思うのです。ぜひその点を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":70402,"voices":206}},{"id":"h28-20161129-5","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"総務委員会","time":"午前１０時００分～午後 ４時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９４号議案、平成２８年度品川区一般会計補正予算","agenda":"第９４号議案、平成２８年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"保育士の確保のためにはぜひ必要だと思うのですが、対象者数は大体把握されているのでしょうか。もちろん事業所を通してでしょうけれども、例えば多くの方が私も助成を受けたいと、増えた場合はどういうふうに対応されるのですか。予算は予算で計上されていますけれども、追加で出た場合には追加計上していくのですか。お聞かせください。","respondent":"秋山財政課長","answer":"保育従事者の宿舎の借上ですけれども、実績で１６０人から１７０人の間と聞いております。増える対象は、これはまだ想定ではありますけれども、あと１０人ぐらいではないかと所管から聞いているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"相当の保育士の方が、こういう支援事業があればすごく助かる。そうするとまた、区立もそうですけれども、私立保育園の保育士の皆さんも相当助かる。恐らくすごいことではないかなと思いますので、各事業所、また、保育士にも、こういうものがありますよという普及啓発に力を入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"吉田委員","kind":"確認","question":"基金の創設については、私も必要だろうということで賛成をしたのですけれども、３.１１、東日本大震災の後、割と立て続けと言ってもいいのかなと思いますが、大きな規模の震災が起きているということで、そのときに国や都からの補助が回ってくるのに若干の時間がある、必要なのでその辺をということだったと思うのですが、先方も忙しい時期ではありますけれども。","respondent":"秋山財政課長","answer":"今回の補正予算で出した１５億円というのは繰越金からの１５億円ということですので、それをどう使うかというのは、当初予算でこちらからご提案をする予定ですので、具体的にどういう形で使うというのは、今後、検討していくです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"例えば大都会だったら、とりあえず命をつなぐライフラインのところなのかとか、そういうことを思うのですが、今後、当初予算で考えていくということであっても、もう間がないわけですから、その辺、どこまでの範囲を想定されているのかということと、それから、これから運用規則とかをつくっていかれると思うのですが、昨日もちょっと議論になりましたけれども、この基金を使っていくのか。","respondent":"秋山財政課長","answer":"今後の当初予算の中の策定ですけれども、例えばヒアリングというご提案もありましたが、避難所を開設するとした時点で何が必要になって何が足りなかったのかというのは、熊本に実際に行って話は聞いておりますので、そういう中で具体的に何が必要かというのは。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"はとにかく特別会計をつくって、財源にこの基金を充てていって、今決めるのは繰越金の中からまずは１５億円を最初に積んでおく。それはやっぱり繰り越しがあったからという感じで捉えてよろしいのでしょうか。","respondent":"秋山財政課長","answer":"話の最初のスイッチというのはやはりこれが必要ですというところで特別会計や何かを組み立てたわけなのですけれども、ただ、その財源はどうするかと考えたときに、今使える繰越金が１５億円ありますというので、１５億円を今回ご提案させていただいたです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"反対の理由は、昨日、各所管で行われた防災対策費以外は、それぞれの所管で意見を申し上げ、賛成はしているのですけれども、保育園に関する家賃助成とか宿舎借上は待機児童解消につながることで、それは了解できるところですが、防災対策費として基金に１５億円の積み立てをするというこの問題については、昨日の基金の質疑でも反対する理由を申し上げていたわけですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"ただ、今も質問をしましたとおり、やはり私たちは、予算立ての制度と繰越金の額については納得できないものがあって、ずっと質問してまいりました。ほかの震災の後、とにかく国からの補助金が間に合わないことがあるというのは私たちも聞いておりますので、それを迅速に手当する基金が必要と考え、今回、疑問は残しながら、額としてはこれくらいは必要なのではないかと判断して、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"}]},{"id":"topic-02","title":"新地方公会計制度に基づく財務４表","agenda":"新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"「５.公表について」なのですけれども、１２月２１日というのはどの段階が公表されるか、教えていただけますか。","respondent":"秋山財政課長","answer":"これは平成２７年度の決算です。財政状況というのは、「平成２７年度の決算をお知らせします」という表題だったと思うのですけれども、平成２７年度の決算の記事の中で、今回ご報告させていただいている財務４表は平成２７年度のものですので、それを公表することになります。","voiceIndex":30,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"これからまた公会計の考え方が変わっていきますよね。発生主義をとってやっていくとなると、バランスシートも割と早くできるようになるわけですよね。そのときもこのタイミングは変わらないのでしょうか。それとも今後は新しい公会計制度に基づいて変わっていくのか、その辺を教えてください。","respondent":"秋山財政課長","answer":"今の財務４表につきましては、決算統計といって国が４月末に確定した数字をもとにつくっておりますので、ちょっと時間がかかっているですけれども、今度から公会計制度で新しいシステムを入れまして、発生主義でいきますので、出納閉鎖後に財務４表は出るという形で予定しており。","voiceIndex":32,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"心配するのです。どんなふうに見ていったらいいのかというのを教えていただきたいなと思うのが１つと、それから左下の連結対象団体のところで、５０％出資している団体名が書かれているのですけれども、５０％には満たないけれども出資をしている、あるいは出えん金を出している団体がほかにもあると思うのです。それがどのくらい、どういう団体があるのかという全体の姿を知りたいなと考えています。","respondent":"秋山財政課長","answer":"民間企業も含めてそうなのですけれども、財務４表をつくるというのは、トータルで見たときにこの会社は大丈夫なのかとかというのを評価するために統一の基準で比べましょうというのが財務４表のそもそもの目的になりますので、財務４表を見ただけで。","voiceIndex":35,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"言ってもどうしようもないのですけれども、しかし、内容は区民の願いに沿った方向での財政執行をぜひしていただきたい、そういう予算を組んでいただきたいということもあわせて言っておきたいなと思います。それから、５０％以下のところが知りたいなと思っているのです。というのは、私、この前の一般質問で……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"その資料を提供していただきたいなと。ある場所がわかれば、自分で探します。ということも含めて、教えてください。","respondent":"秋山財政課長","answer":"決算委員会の資料として出している決算書の中に、区が出資している団体の一覧がありますので、そちらを確認すれば出ております。","voiceIndex":38,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"決算書を見てみたいと思いますけれども、その発端になった意識というのが、この前の一般質問で取り上げた東京熱供給株式会社に２％出資しているのですよね。ですから、そういう類いのものがどのぐらいあるのかなというのを知りたくて質問したのですけれども、決算書に出ているということですよね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"}]},{"id":"topic-03","title":"品川区公式ホームページのトップページリニューアル","agenda":"品川区公式ホームページのトップページリニューアル","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"」とかコメントとか、いろいろなデータ収集もかなりできたり、逆にお金を払うことで発信とかもできるのですが、そういったところはこれからということで、考えとしてはあるかどうかというのを教えていただきたいと思います。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"シティプロモーション動画の再生回数についてのお問い合わせですが、昨日カウントいたしましたところ、２本あるうちのまずはお祭り編につきましては約１,４００回、商店街編については約１,０００回の再生回数がございました。」機能とか、そういうものを使いながら、皆様のご意見を集約したりということにも活用を検討してまいりたいと思っているところです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"公式ユーチューブということで、私も何回か検索したりしているのですが、品川区と入れてもなかなかこれが出てこないという話もあったり、自分でもやったのですが、なかなかアクセスしないところが課題かなと思っているのですが、そうしたところは今後どういうふうにしていくのかなというところを教えてください。","respondent":"中元広報広聴課長","answer":"品川区公式ユーチューブは、実は１２月１９日目途で今準備をしておりまして、それで今、ユーチューブでは、「不動麗子」で検索をしていただくと比較的上段に出てまいります。","voiceIndex":49,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。これからだというところで承知しましたが、「不動麗子」で検索は知らないとできないですよね。これは「しながわネットＴＶ」で検索するのか、「品川区」とかで検索するとぱっと出るようになるように工夫されているのか、そこだけ教えてください。","respondent":"中元広報広聴課長","answer":"そこのところは機能を確認しますが、こちらとしては「しながわネットＴＶ」という名前で検索ができるように工夫してまいりたいと考えているところです。","voiceIndex":51,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"再生回数もいかに増やして知ってもらうかというところでは、電車の広告で流していただいて１,４００回とかだと、この数が多いか少ないかは別にして、まだまだ見てもらえるものはあるのかなと思うので、ぜひ工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-017"}]},{"id":"topic-04","title":"第２２回品川区世論調査","agenda":"第２２回品川区世論調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"不在の方が２８６人もいらっしゃって、７１.３％の回収率ということなので、高い数字だとは思うのですけれども、なかなか何月何日の何時頃とか、相手の在宅の関係を調査するのは大変なので、こういうやり方が一般的だとは思うのですけれども、その辺のところを伺いたいのと、訪問したときに、１５分野４０問を１つ１つ確認して、丸をしたり、ご意見を聞くという調査方法なのかどうかを伺います。","respondent":"中元広報広聴課長","answer":"やはりあまりに多くなりますと回答のご負担が大きくなりますので、昨年の状況とか過去の状況とかを検討しながらある程度絞り込み、その際に設問も各課と調整をさせていただいておりまして、やはりある程度、各課として施策を考える中で調査のほうも考えているです。","voiceIndex":62,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"個別のいろいろな要求について伺うというのはなかなか難しいところがありますよね。したがって、そういうご苦労をされて、こういう項目になっているのかなと思ったのですけれども、もうひと工夫というか、もう少しあったほうがいいかなと思いましたので、今後のところでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"やはり３８万人の人口の中で１,０７０人の方たちの意見をここに調査として取り入れているわけですが、私は手段があるのですから、もっと幅広い人数、例えば１万人単位とか、そういうことができないなら別ですけれども、できる仕組みを持っているわけですから、できるだけ大勢の品川に対する考え方、思いをもっと反映させて、そういう調査票を出していただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"人数に対しては、どれぐらいからずっとこの１,５００人に調査をやられているのかというのは調べていないからわからないのですけれども、私ももう少し増えてもいいのかなというところと、２０歳以上というところで、例えば選挙が１８歳に引き下げられたとかというところもありますし、年齢については、そういう動きがある中で今後も二十歳以上で行くのか。","respondent":"中元広報広聴課長","answer":"１８歳以上というところなのですが、今までの調査が二十歳以上を対象に実施しておりまして、経年変化を見ているところもありますので、その辺のところをどう考えるかというのは今後の課題とさせていただきたいです。","voiceIndex":68,"id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば不在が２８６件で、危惧していたのは、特に２０代とか３０代の働き盛りの方がここに多く実は入っていて、そういう人たちの声がここにはなかなか反映されていないのではないかなという心配があったのですが、今のお話だと、年齢構成は考慮して、そこにちゃんと意見は聞けているということでいいのかの確認をさせていただきたいのと、あと、８地域にというところで。","respondent":"中元広報広聴課長","answer":"サンプルといたしましては、回答してきた結果ですが、２０代が１０５人、３０代が２１２人、４０代が２２４人というサンプルでしておりまして、やはり２０代が回答数としては若干少なくなっているところです。","voiceIndex":70,"id":"exchange-022"}]},{"id":"topic-05","title":"大井町駅東口ペデストリアンデッキ耐震補強工事請負契約","agenda":"大井町駅東口ペデストリアンデッキ耐震補強工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません、すごく基本的な質問で恥ずかしいのですけれども、９ページのこういう感じの表を私は初めて見たというか。結局ほとんど皆さん辞退して、２者だけの応札ということですよね。状況を説明していただけますか。","respondent":"立川経理課長","answer":"本件につきましては、今回、指名競争入札を実施したのですが、その前に制限付き一般競争入札ということで条件を変えて２回実施したのですけれども、入札が成立しなかったということで、今回、指名競争入札に切りかえて行うことになったわけです。","voiceIndex":84,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":27127,"voices":95}},{"id":"h28-20161129-10","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年第４回定例会","agenda":"平成２８年第４回定例会","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"平成２７年の、国税庁のほうで昨年の、勤労者所得、年間の平均給与が４２０万円と公表されました。２３区の公務員平均給与が６６０万と、これだけ一般の勤労者の給与が低い中、職員の給与がこういうふうに上がっていくというのは、ちょっといかがなものかなと思いまして、我々の会派としては、反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1290,"voices":10}}]);
